<script>
    var url = new URL(window.location.href);
    $(document).ready(function () {
       
        if (url.searchParams.has('followup_status')) {
            $(".followup_status").val(url.searchParams.get('followup_status'));               
        }
       

        $(".dt-search").on("change", function () {
            const $this = $(this);
            const group = $this.data("group"); // e.g., "checkin" or "query"
            const type = $this.hasClass("date_from") ? "from" : "to";

            const $fromInput = $(`.date_from[data-group='${group}']`);
            const $toInput = $(`.date_to[data-group='${group}']`);
            const $fromShow = $(`.dt-search-show[data-group='${group}']`).eq(0);
            const $toShow = $(`.dt-search-show[data-group='${group}']`).eq(1);

            const fromVal = $fromInput.val();
            const toVal = $toInput.val();

            const fromDate = fromVal ? new Date(fromVal) : null;
            const toDate = toVal ? new Date(toVal) : null;

            const selectedDate = new Date($this.val());
            const formattedDate = selectedDate.toLocaleDateString("en-IN", {
                year: "numeric",
                month: "short",
                day: "2-digit"
            });

            // Update corresponding display field
            if (type === "from") {
                $fromShow.val(formattedDate).parent().addClass("is-focused");
            } else {
                $toShow.val(formattedDate).parent().addClass("is-focused");
            }

            // Validation logic
            if (type === "from") {
                if (!toVal) {
                    $toInput.attr("min", $this.val());
                } else if (fromDate && toDate && fromDate > toDate) {
                    $toInput.val('').attr("min", $this.val());
                    $toShow.val('');
                }
            } else {
                if (!fromVal) {
                    $fromInput.attr("max", $this.val());
                } else if (fromDate && toDate && fromDate > toDate) {
                    $fromInput.val('').attr("max", $this.val());
                    $fromShow.val('');
                }
            }
        });
        
        $("#frm_1").on("change",".dt-transfer", function () {
            var idx = $(this).index(".dt-transfer");
            const selectedDate = new Date($(".dt-transfer").eq(idx).val());
            //const lastDayDate = new Date(selectedDate.getFullYear(), selectedDate.getMonth() + 1, 0);
            const options = {
                year: 'numeric',
                month: 'short',
                day: '2-digit'
            };
            const formattedDate = selectedDate.toLocaleDateString('en-IN', options);
            $(".dt-transfer-show").eq(idx).val(formattedDate).parent().addClass('is-focused');
        });
    });
</script>
<script>
            // Function to toggle between time selection and flight details
            function toggleFlightDetails() {
                if ($('#fligt_details_yes').is(':checked')) {
                    $('#time_selection_block').hide();
                    $('#flight_details_block').show();
                    $('.time_arrival_div').hide();
                    $('.time_departure_div').hide();
                    $('.flight_arrival_div').show();
                    $('.flight_departure_div').show();
                    $('#initial_early_checkin').prop('disabled', true).prop('checked', false);
                    $('#initial_late_checkout').prop('disabled', true).prop('checked', false);
                } else {
                    $('#time_selection_block').show();
                    $('#flight_details_block').hide();
                    $('.flight_arrival_div').hide();
                    $('.flight_departure_div').hide();
                    $('.time_arrival_div').show();
                    $('.time_departure_div').show();
                    // $('#initial_early_checkin').prop('disabled', true).prop('checked', false);
                    // $('#initial_late_checkout').prop('disabled', true).prop('checked', false);
                    updateCheckboxStates();
                }
                updateSummary();
            }

            // Function to update arrival time display based on selection
            function updateArrivalTime() {
                const selectedTime = $('#arrival_time_selection').val();
                $('#arrival_time_display').val(selectedTime);
                updateCheckboxStates();
                updateSummary();
            }

            // Function to update departure time display based on selection
            function updateDepartureTime() {
                const selectedTime = $('#departing_time_selection').val();
                $('#departure_time_display').val(selectedTime);
                updateCheckboxStates();
                updateSummary();
            }

            function updateCheckboxStates() {
                const arrivalTime = $('#arrival_time_selection').val();
                const departureTime = $('#departing_time_selection').val();
                
                // Early check-in logic: enabled for morning arrival, disabled for evening
                if (arrivalTime === 'morning') {
                    $('#initial_early_checkin').prop('disabled', false);
                } else if (arrivalTime === 'evening') {
                    $('#initial_early_checkin').prop('disabled', true).prop('checked', false);
                } else {
                    $('#initial_early_checkin').prop('disabled', true).prop('checked', false);
                }
                
                // Late check-out logic: disabled for morning departure, enabled for evening
                if (departureTime === 'morning') {
                    $('#initial_late_checkout').prop('disabled', true).prop('checked', false);
                } else if (departureTime === 'evening') {
                    $('#initial_late_checkout').prop('disabled', false);
                } else {
                    $('#initial_late_checkout').prop('disabled', true).prop('checked', false);
                }
            }

            // Function to update the summary section
            function updateSummary() {
                // Update arrival summary
                const arrivalTime = $('#arrival_time_display').val();
                $('#summary-arrival').text(arrivalTime ? arrivalTime.charAt(0).toUpperCase() + arrivalTime.slice(1) : 'Not selected');
                
                // Update departure summary
                const departureTime = $('#departure_time_display').val();
                $('#summary-departure').text(departureTime ? departureTime.charAt(0).toUpperCase() + departureTime.slice(1) : 'Not selected');
                
                // Update check-in summary
                const earlyCheckin = $('#initial_early_checkin').is(':checked');
                $('#summary-checkin').text(earlyCheckin ? 'Yes' : 'No');
            }

            // Initial state
            toggleFlightDetails();

            // Add event listeners
            $('input[name="fligt_details"]').change(toggleFlightDetails);
            $('#arrival_time_selection').change(updateArrivalTime);
            $('#departing_time_selection').change(updateDepartureTime);
            $('#initial_early_checkin').change(updateSummary);
            
            // Initialize summary
            updateSummary();
</script>
<script>
    
    $(document).ready(function () {
        $(".company").autocomplete({
