                            insertGuideSite(res.siteData);
                        });

                        if (selectedSiteData) {
                            let i = 0;
                            let li = `
                                <li style="display:inline-flex;">
                                    <input type="hidden" name="hdn_site_id[${i}][]" value="${selectedSiteData.id}">
