                            let li = `
                                <li style="display:inline-flex;">
                                    <input type="hidden" name="hdn_site_id[${i}][]" value="${airportTransfer.id}">
                                    <i class="fa fa-circle-o" style="margin:6px;"></i>
                                    <input type="hidden" name="hdn_itinerary_content[${i}][]" value="${airportTransfer.site_name}">
