        // helper function to insert selected site
        function insertGuideSite(siteData) {
            // Prevent duplicates
            $(".itinerary_ul").eq(0).find(".guide-site").remove();
            $(".itinerary_ul").eq(0).find(".site-464").remove();
            let selectedVal = $("input[name='driver_cum_guide']:checked").val();
            let selectedguide = $("input[name='guide']:checked").val();
            let selectedSite = null;
           if(qdata.enquiry_abbr ==='FGE' || qdata.enquiry_abbr ==='IGE' || qdata.enquiry_abbr ==='GGE' || qdata.enquiry_abbr ==='FAZ' || qdata.enquiry_abbr ==='GAZ' || qdata.enquiry_abbr ==='IAZ')
            {
                selectedSite = siteData.find(s => s.id == "199");
            }
            else if(qdata.enquiry_abbr ==='FUZ' || qdata.enquiry_abbr ==='IUZ' || qdata.enquiry_abbr ==='GUZ')
            {
                selectedSite = siteData.find(s => s.id == "422");
            }
            else if(qdata.enquiry_abbr ==='FAR' || qdata.enquiry_abbr ==='IAR' || qdata.enquiry_abbr ==='GAR')
            {
                selectedSite = siteData.find(s => s.id == "394");
            }
            else
            {
                if (selectedVal === "driver_guide") {
                    selectedSite = siteData.find(s => s.id == "43");
                } else if (selectedVal === "guide") {
                    selectedSite = siteData.find(s => s.id == "199");
                }
            }
            
            let site464 = siteData.find(s => s.id == "464");   

            if (selectedSite) {
                let i = 0;
                let li = `
                    <li style="display:inline-flex;" class="guide-site">
                        <input type="hidden" name="hdn_site_id[${i}][]" value="${selectedSite.id}">
                        <i class="fa fa-circle-o" style="margin:6px;"></i>
                        <input type="hidden" name="hdn_itinerary_content[${i}][]" value="${selectedSite.site_name}">
                        <div class="description">${selectedSite.site_name}
                        <span style="display:none;"><br>Entry Fee : 0 (A) 0 (C)  |
                        <button type="button" data-site-id="${selectedSite.id}" 
                            class="btn btn-sm btn-link activities" style="padding:0;">
                            Add Activities
                        </button></span>
                        ${selectedSite.description}
                        </div>
                        <i title="Remove" class="bi bi-x-lg edit-remove"
                        style="color:red;cursor: pointer;float: right;margin-top: 5px;position:relative;"></i>
                        <input type="hidden" class="activities-list" name="hdn_activities[${i}][]" value="">
                    </li>
                `;
                
                // Insert guide site after the first day description
                $(".itinerary_ul").eq(0).find("li:has(div[style*='list-style-type: circle'])").after(li);
                
                if (site464) {
                    let li464 = `
                        <li style="display:inline-flex;" class="site-464">
                            <input type="hidden" name="hdn_site_id[${i}][]" value="${site464.id}">
                            <i class="fa fa-circle-o" style="margin:6px;"></i>
                            <input type="hidden" name="hdn_itinerary_content[${i}][]" value="${site464.site_name}">
                            <div class="description">${site464.site_name}
                            <span style="display:none;"><br>Entry Fee : 0 (A) 0 (C)  |
                            <button type="button" data-site-id="${site464.id}" 
                                class="btn btn-sm btn-link activities" style="padding:0;">
                                Add Activities
                            </button></span>
                            ${site464.description}
                            </div>
                            <i title="Remove" class="bi bi-x-lg edit-remove"
                            style="color:red;cursor: pointer;float: right;margin-top: 5px;position:relative;"></i>
                            <input type="hidden" class="activities-list" name="hdn_activities[${i}][]" value="">
                        </li>
                    `;
                    // Insert site 464 after the guide site (so it appears above site 30)
                    $(".guide-site").after(li464);
                }
            }
        }

        // Function to add site 15 to all middle days
        function addSite15ToMiddleDays(siteData) {
            let site15 = siteData.find(s => s.id == "15");
            
            if (site15) {
                // Get all itinerary days (all .itinerary_ul elements)
                const itineraryDays = $(".itinerary_ul");
                
                // Loop through all days except first (index 0) and last (index length-1)
                for (let i = 1; i < itineraryDays.length - 1; i++) {
                    let li = `
                        <li style="display:inline-flex;" class="site-15">
                            <input type="hidden" name="hdn_site_id[${i}][]" value="${site15.id}">
                            <i class="fa fa-circle-o" style="margin:6px;"></i>
                            <input type="hidden" name="hdn_itinerary_content[${i}][]" value="${site15.site_name}">
                            <div class="description">
                                ${site15.site_name} 
                                <span style="display:none;"><br>Entry Fee : 0 (A) 0 (C)  |  
                                <button type="button" data-site-id="${site15.id}" 
                                    class="btn btn-sm btn-link activities" style="padding:0;">
                                    Add Activities
                                </button></span>
                                ${site15.description}
                            </div>
                            <i title="Remove" class="bi bi-x-lg edit-remove" 
                            style="color:red;cursor: pointer;float: right;margin-top: 5px;position:relative;"></i>
                            <input type="hidden" class="activities-list" name="hdn_activities[${i}][]" value="">
                        </li>
                    `;
                    $(itineraryDays[i]).append(li);
                }
            }
        }


        // define globally (outside)
