        let quotationNewMode = false;

        // mode control
        let quotationMode = 'edit'; // edit | view | new
        let quotationModeToken = 0;

        function setQuotationMode(mode) {
            quotationMode = mode;
            quotationModeToken++;

            quotationView = (mode === 'view');

            if (mode === 'view') {
                $('.file_status').val('view');
            } else if (mode === 'edit') {
                $('.file_status').val('edit');
            } else {
                $('.file_status').val('');
            }

            return quotationModeToken;
        }

