        $(document)
        .off("click.quotationMode", ".quotations-made")
        .on(
            "click.quotationMode",
            ".quotations-made",
            function () {
                disableChildCheck = true;

                const isPreviewTrigger =
                    $(this).attr("data-preview-mode") === "yes";

                let currentToken;
                let nights = 0;

                resetSavedCityItineraryWatcher();

                if (isPreviewTrigger) {
                    currentToken = setQuotationMode("view");

                    /*
                    * Preview me saved quotation ka count use hoga.
                    */
                    nights =
                        parseInt(
                            window.currentQuotationData
                                ?.no_of_nights,
                            10
                        ) ||
                        parseInt(qdata.nights, 10) ||
                        0;

                } else {
                    currentToken = setQuotationMode("edit");

                    quotationView = false;
                    quotationNewMode = false;

                    const quotationId =
                        $(this).attr("data-id");

                    if (quotationId) {
                        $("#quotation_id").val(
                            quotationId
                        );
                    }

                    $("#savedQuotationPreviewModal")
                        .modal("hide");

                    /*
                    * Edit mode me current enquiry latest source hai.
                    */
                    nights =
                        parseInt(
                            window.currentEnquiryNights,
                            10
                        ) ||
                        parseInt(qdata.nights, 10) ||
                        parseInt(
                            $("#number_of_nights").val(),
                            10
                        ) ||
                        parseInt(
                            window.currentQuotationData
                                ?.no_of_nights,
                            10
                        ) ||
                        0;

                    $("#number_of_nights").val(nights);

                    if (
                        window.currentQuotationData &&
                        typeof window
                            .currentQuotationData ===
                            "object"
                    ) {
                        window.currentQuotationData
                            .no_of_nights = nights;
                    }
                }

                localStorage.removeItem("db_night");
                localStorage.setItem(
                    "db_night",
                    nights
                );

                if (
                    typeof generateItineraryHTML ===
                    "function"
                ) {
                    generateItineraryHTML(nights);
                }

                if (
                    typeof generatesavedhotelHTMl ===
                    "function"
                ) {
                    generatesavedhotelHTMl(nights);
                }

                if (isPreviewTrigger) {
                    setTimeout(function () {
                        if (
                            quotationMode === "view" &&
                            quotationModeToken ===
                                currentToken
                        ) {
                            $(".file_status").val("view");
                            makeQuotationReadOnly();
                        }
                    }, 500);

                    setTimeout(function () {
                        if (
                            quotationMode === "view" &&
                            quotationModeToken ===
                                currentToken
                        ) {
                            $(".file_status").val("view");
                            makeQuotationReadOnly();
                        }
                    }, 1500);

                } else {
                    setTimeout(function () {
                        if (
                            quotationMode === "edit" &&
                            quotationModeToken ===
                                currentToken
                        ) {
                            $(".file_status").val("edit");
                            quotationView = false;

                            removeAllQuotationReadonlyDisabled();
                        }
                    }, 300);

                    setTimeout(function () {
                        if (
                            quotationMode === "edit" &&
                            quotationModeToken ===
                                currentToken
                        ) {
                            $(".file_status").val("edit");
                            quotationView = false;

                            removeAllQuotationReadonlyDisabled();
                        }
                    }, 1500);
                }
            }
        );
        
        function updateCnbCwbVisibility() {
            var children = parseInt($("#number_of_child").val()) || 0;
            
            if (children > 0) {
                // Show ALL CNB and CWB containers
                $(".cnb-cwb-container").show();
            } else {
                // Hide ALL CNB and CWB containers
                $(".cnb-cwb-container").hide();
                // Also uncheck them when hiding
                $(".cnb-cwb-option").prop('checked', false);
            }
        }

