            const daySelect = document.getElementById('daySelect');
            const allDiv = document.getElementById('allDiv');
            const daysDiv = document.getElementById('daysDiv');
            const mealType = document.getElementById('mealType');

            let availableMeals = [];

            daySelect.addEventListener('change', function () {
                renderByDaySelect();
            });

            
            getCountryFromEnquiry(qdata.enquiry_abbr);
            let cutoff_meal_sitescene = '2026-05-24 00:00:00';
            let saved_last_meal_quotation_date = localStorage.getItem('first_quotation_date');

            if (
                saved_last_meal_quotation_date === '' ||
                new Date(saved_last_meal_quotation_date) >= new Date(cutoff_meal_sitescene)
            ) {
                $('#mealType').on('change', function () {
                    const selectedMealTypes = $(this).val();
                    const country = getCountryFromEnquiry(qdata.enquiry_abbr);
                    if (!country || !selectedMealTypes.length) return;
                    $.ajax({
                        url: "<?= base_url('get-meals-by-country') ?>",
                        type: "POST",
                        dataType: "json",
                        data: {
                            country: country,
                            ctype: selectedMealTypes
                        },
                        success: function (res) {
                            // availableMeals = res;
                            availableMeals = {
                                indian: [],
                                international: [],
                                local: []
                            };

                            res.forEach(meal => {
                                const type = meal.ctype.toLowerCase();
                                if (availableMeals[type]) {
                                    availableMeals[type].push(meal);
                                }
                            });

                            renderByDaySelect();
                        }
                    });

                });

                function buildMealCheckboxes(namePrefix, meals, title) {

                    if (!meals || !meals.length) return '';

                    let html = `
                        <div class="day-box">
                            <div class="day">
                                <b>${title}</b>
                            </div>
                            <div class="meal-row-wrapper">
                                <div class="lunch">
                    `;

                    meals.forEach(meal => {

                        const key = meal.Buffet
                            .toLowerCase()
                            .replace(/\s+/g, '_');

                        html += `
                                <input
                                    type="checkbox"
                                    name="${namePrefix}[${meal.ctype.toLowerCase()}][${key}][${meal.id}]"
                                    value="1"
                                >

                                <label>${meal.Buffet}</label>
                        `;
                    });

                    html += `
                                </div>
                            </div>
                        </div>
                    `;

                    return html;
                }

                function renderByDaySelect() {
                    const value = daySelect.value;
                    allDiv.classList.remove('active');
                    daysDiv.classList.remove('active');
                    daysDiv.innerHTML = '';

                    if (!availableMeals) return;

                    function renderMealSections(prefix, dayTitle) {
                        return `
                            ${buildMealCheckboxes(
                                prefix,
                                availableMeals.indian,
                                `${dayTitle} (Indian)`
                            )}

                            ${buildMealCheckboxes(
                                prefix,
                                availableMeals.international,
                                `${dayTitle} (International)`
                            )}

                            ${buildMealCheckboxes(
                                prefix,
                                availableMeals.local,
                                `${dayTitle} (Local)`
                            )}
                        `;
                    }

                    if (value === 'all') {
                        daysDiv.classList.add('active');
                        daysDiv.innerHTML = `
                            ${renderMealSections('meals[all]', 'All Days')}
                        `;

                    } else if (value === 'days') {
                        daysDiv.classList.add('active');
                        let daysHTML = '';
                        for (let i = 1; i <= total_days; i++) {
                            daysHTML += `
                                ${renderMealSections(`meals[day_${i}]`, `Day ${i}`)}
                            `;
                        }

