                document.addEventListener('change', function (e) {
                    if (!e.target.matches('input[type="checkbox"][name^="meals["]')) return;

                    hasUserMadeChanges = true;

                    if (!savedMealDataGlobal) {
                        // savedMealDataGlobal = { cusine: mealType.value, days: daySelect.value, meals: {} };
                        savedMealDataGlobal = { 
                            cusine: $('#mealType').val() || [],   // val() returns array for multi-select
                            days: daySelect.value, 
                            meals: {} 
                        };
                    }

                    const name = e.target.name;
                    const isChecked = e.target.checked;

                    // Regex to capture: dayKey, cuisine, buffetKey, mealId
                    const match = name.match(/meals\[([^\]]+)\]\[([^\]]+)\]\[([^\]]+)\]\[([^\]]+)\]/);
                    if (!match) return;

                    const dayKey = match[1];
                    const cuisine = match[2];
                    const buffetKey = match[3];
                    const mealId = match[4];

                    if (!savedMealDataGlobal.meals[dayKey]) savedMealDataGlobal.meals[dayKey] = {};
                    if (!savedMealDataGlobal.meals[dayKey][cuisine]) savedMealDataGlobal.meals[dayKey][cuisine] = {};
                    if (!savedMealDataGlobal.meals[dayKey][cuisine][buffetKey]) savedMealDataGlobal.meals[dayKey][cuisine][buffetKey] = {};

                    if (isChecked) {
                        savedMealDataGlobal.meals[dayKey][cuisine][buffetKey][mealId] = 1;
                    } else {
                        delete savedMealDataGlobal.meals[dayKey][cuisine][buffetKey][mealId];
                        // Clean up empty objects
                        if (Object.keys(savedMealDataGlobal.meals[dayKey][cuisine][buffetKey]).length === 0) {
                            delete savedMealDataGlobal.meals[dayKey][cuisine][buffetKey];
                        }
                        if (Object.keys(savedMealDataGlobal.meals[dayKey][cuisine]).length === 0) {
                            delete savedMealDataGlobal.meals[dayKey][cuisine];
                        }
                        if (Object.keys(savedMealDataGlobal.meals[dayKey]).length === 0) {
                            delete savedMealDataGlobal.meals[dayKey];
                        }
                    }

                    console.log('Updated meal data:', savedMealDataGlobal);
                });

                function clearAllMealCheckboxes() {
                    document.querySelectorAll('input[name^="meals["][type="checkbox"]')
                        .forEach(cb => cb.checked = false);
