                function applySavedMeals(savedMealData) {
                    if (!savedMealData || !savedMealData.meals) {
                        console.log('No saved meal data to apply');
                        return;
                    }
                    console.log('Applying saved meals:', savedMealData);

                    clearAllMealCheckboxes();

                    // Iterate over the nested structure
                    for (const [dayKey, cuisines] of Object.entries(savedMealData.meals)) {
                        for (const [cuisine, buffetKeys] of Object.entries(cuisines)) {
                            for (const [buffetKey, mealIds] of Object.entries(buffetKeys)) {
                                for (const [mealId, value] of Object.entries(mealIds)) {
                                    if (value == 1) {
                                        // Find checkbox by meal ID within the same day and cuisine (ignore buffet key)
                                        const prefix = `meals[${dayKey}][${cuisine}]`;
                                        const checkboxes = document.querySelectorAll(`input[name^="${prefix}"][type="checkbox"]`);
                                        let found = false;
                                        for (let cb of checkboxes) {
                                            if (cb.name.endsWith(`[${mealId}]`)) {
                                                cb.checked = true;
                                                console.log(`Checked: ${cb.name}`);
                                                found = true;
                                                break;
                                            }
                                        }
                                        if (!found) {
                                            console.log(`Checkbox not found for mealId ${mealId} in ${dayKey}/${cuisine}`);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

