                        savedMealDataGlobal = { cusine: mealType.value, days: daySelect.value, meals: {} };
                    }

                    const name = e.target.name;
                    const value = e.target.checked ? 1 : 0;

                    // Parse the checkbox name to extract day and meal information
                    const nameParts = name.match(/meals\[([^\]]+)\]\[([^\]]+)\](?:\[([^\]]+)\])?/);
                    if (!nameParts) return;

                    const dayKey = nameParts[1];
                    const mealKey = nameParts[2];
                    const mealId = nameParts[3];

                    if (!savedMealDataGlobal.meals[dayKey]) {
                        savedMealDataGlobal.meals[dayKey] = {};
                    }

                    // Store in the correct format based on whether we have mealId
                    if (mealId) {
                        // New format: meals[dayKey][mealKey][id]
                        if (!savedMealDataGlobal.meals[dayKey][mealKey]) {
                            savedMealDataGlobal.meals[dayKey][mealKey] = {};
                        }
                        
                        // If unchecking (value === 0), remove from saved data
                        if (value === 0) {
                            delete savedMealDataGlobal.meals[dayKey][mealKey][mealId];
                            
                            // If the mealKey object is now empty, remove it
                            if (Object.keys(savedMealDataGlobal.meals[dayKey][mealKey]).length === 0) {
                                delete savedMealDataGlobal.meals[dayKey][mealKey];
                            }
                        } else {
                            // If checking, add to saved data
                            savedMealDataGlobal.meals[dayKey][mealKey][mealId] = value;
                        }
                        
                        // If the dayKey object is now empty, remove it
                        if (Object.keys(savedMealDataGlobal.meals[dayKey]).length === 0) {
                            delete savedMealDataGlobal.meals[dayKey];
                        }
                    } else {
                        // Old format: meals[dayKey][mealKey]
                        if (value === 0) {
                            // Remove if unchecked
                            delete savedMealDataGlobal.meals[dayKey][mealKey];
                            
                            // If the dayKey object is now empty, remove it
                            if (Object.keys(savedMealDataGlobal.meals[dayKey]).length === 0) {
                                delete savedMealDataGlobal.meals[dayKey];
                            }
