                    handleAirportPickDrop(currentVal);

                    $("input[name='hotel'][value='yes']").prop("checked", true).trigger("click");

                    $("input[name='4_star_room_type[]']").prop("checked", false);
                    if (totalGuests >= 3) {
                        $("input[name='4_star_room_type[]'][value='1(A)']").prop("checked", true);
                        $("input[name='4_star_room_type[]'][value='2(A)']").prop("checked", true);
                        $("input[name='4_star_room_type[]'][value='3(A)']").prop("checked", true);
                    } else if (totalGuests === 2) {
                        $("input[name='4_star_room_type[]'][value='1(A)']").prop("checked", true);
                        $("input[name='4_star_room_type[]'][value='2(A)']").prop("checked", true);
                        $("input[name='4_star_room_type[]'][value='3(A)']").prop("disabled", true).prop("checked", false);
                    } else if (totalGuests === 1) {
                        $("input[name='4_star_room_type[]'][value='1(A)']").prop("checked", true);
                        $("input[name='4_star_room_type[]'][value='2(A)']").prop("disabled", true).prop("checked", false);
                        $("input[name='4_star_room_type[]'][value='3(A)']").prop("disabled", true).prop("checked", false);
                    }
                    
                    if(qdata.enquiry_abbr ==='FGE' || qdata.enquiry_abbr ==='IGE' || qdata.enquiry_abbr ==='GGE' || qdata.enquiry_abbr ==='FAZ' || qdata.enquiry_abbr ==='GAZ' || qdata.enquiry_abbr ==='IAZ')
                    {
                        $('#div_driver_cum_guide label:first').addClass("hide");
                        $("input[name='driver_cum_guide'][value='guide']").prop("checked", true).trigger("change");
                    }else{
                        if (totalGuests < 5) {
                            $("input[name='driver_cum_guide'][value='driver_guide']").prop("checked", true).trigger("change");
                        } else {
                            $("input[name='driver_cum_guide'][value='guide']").prop("checked", true).trigger("change");
                        }
                    }
                });
