            function calculateTotalCapacity() {
                let total = 0;

                // Loop through all checked vehicles
                $("input[name='chk_vehicle[]']:checked").each(function () {
                    let capacity = parseInt($(this).data("capacity")) || 0;
                    // Find related quantity input inside the same row
                    let quantity = parseInt($(this).closest(".row").find("input[name='vehicle_quantity[]']").val()) || 1;
                    total += capacity * quantity;
                });

                if (total < totalGuests) {
                    $("#btn_hotel").addClass("blocked");
                } else {
                    $("#btn_hotel").removeClass("blocked");
                }

                return total;
            }

            // On checkbox change
            $(document).on("change", "input[name='chk_vehicle[]']", function () {
                calculateTotalCapacity();
            });

            // On quantity change
            $(document).on("input change", "input[name='vehicle_quantity[]']", function () {
                // Only recalc if its checkbox is checked
                let chk = $(this).closest(".row").find("input[name='chk_vehicle[]']");
                if (chk.is(":checked")) {
                    calculateTotalCapacity();
                }
            });
            
