                                            let formattedDate = '';

                                            /*
                                            * Quotation creation date formatting.
                                            */
                                            if (val.created) {
                                                const createdDate = new Date(val.created);

                                                if (!isNaN(createdDate.getTime())) {
                                                    const monthNames = [
                                                        'Jan', 'Feb', 'Mar', 'Apr',
                                                        'May', 'Jun', 'Jul', 'Aug',
                                                        'Sep', 'Oct', 'Nov', 'Dec'
                                                    ];

