                                                        class="btn btn-link open-quote-popup"
                                                        data-id="${val.id || ''}"
                                                        data-enquiry-id="${$('#enquiry_id').val() || ''}"
                                                        data-quote-no="${quoteNumber}"
                                                        data-date="${formattedDate}"
                                                        data-final="${val.quot_final || ''}"
                                                        data-created-by="${val.created_by_name || ''}"
                                                        style="${quoteStyle}"
                                                    >
                                                        Quote ${quoteNumber}

                                                        ${
                                                            isFinalQuote
                                                                ? `
                                                                    <span
                                                                        class="badge bg-success"
                                                                        style="
                                                                            font-size: 10px;
                                                                            padding: 3px 6px;
                                                                            margin-left: 5px;
                                                                        "
