                                                        }
                                                    </button>
                                                </div>
                                            `;
                                        });

                                        quotation_html += `
                                            </div>
                                        `;

                                        /*
                                        * html() use karo, append() nahi.
                                        * Isse previous enquiry ke quotations repeat nahi honge.
                                        */
                                        $('#show-quotations').html(quotation_html);

                                    } else {

                                        /*
                                        * Ek bhi quotation nahi hai.
                                        */
                                        $('#show-quotations').empty();

                                        $('#btn_final_quote')
                                            .hide()
                                            .prop('disabled', true)
                                            .removeAttr('title')
                                            .removeAttr('data-bs-toggle')
                                            .removeAttr('data-bs-target');
                                    }
                            } 
                        }
                    });
                
                    $("input[name='qt_arrival_date']").val(qdata.checkin).trigger("change");
                    $("input[name='qt_departure_date']").val(qdata.checkout).trigger("change");
                    var num_guests = qdata.adult_child.split(" ")[0];
                    if(num_guests > 5){
                        $('input[name="guide"][value="yes"]').prop('checked', 'checked').trigger("click");
                    }else{
                        $('input[name="guide"][value="no"]').prop('checked', 'checked').trigger("click");
                    }
                    var total_pax = parseInt(qdata.adults)+parseInt(qdata.child);
                    if(qdata.enquiry_abbr ==='FGE' || qdata.enquiry_abbr ==='IGE' || qdata.enquiry_abbr ==='GGE' || qdata.enquiry_abbr ==='FAZ' || qdata.enquiry_abbr ==='GAZ' || qdata.enquiry_abbr ==='IAZ')
                    {
                                $('#div_driver_cum_guide span:first-child').addClass("hide");
                                $("input[name='driver_cum_guide'][value='guide']").prop("checked", true).trigger("change");
                                // console.log(qdata.enquiry_abbr, "HIDE driver cum guide for FGE/IGE/GGE");
                    }else{ 
                        if(total_pax > 5){
                            $('#div_driver_cum_guide label:first').addClass("hide");
                        }else{
                            $('#div_driver_cum_guide label:first').removeClass("hide");                
                        }
                    }
                });
        
            
             $(document).on('click', '.itinerary_data', function (e) {
                e.preventDefault();

                var firstDay = localStorage.getItem('firstDay') || "";
                var lastDay = localStorage.getItem('lastDay') || "";
                const selectedAirport = $('input[name="airport_pick_drop"]:checked').val();
                const arrival_time = $("#initial-airline-departure-time").val() || "00:00";
                const departure_time = $(".airline-search-depart-time").val() || "23:59";

                // ✅ collect all cities
                var all_cities = $(".qtn-city").map(function () {
                    return $(this).val();
                }).get();

                if (selectedAirport === 'yes' || selectedAirport === 'no') {
                    $("#spinnerOverlay").css("display", "block");

                    $.ajax({
                        url: "<?php echo site_url('admin/quotation/generate_itinerary'); ?>",
                        type: "POST",
                        data: {
                            'enquiry_num': qdata.qno,
                            'check_in': qdata.checkin,
                            'check_out': qdata.checkout,
                            'arrival_time': arrival_time,
                            'departure_time': departure_time,
                            'all_cities': all_cities,
                            'arrival_city': $('.flight-city-initial').eq(1).val(),
                        },
                        dataType: 'json',
                        success: function (itinerary) {
                            // ✅ remove first city (base city, always skip)
                            var mappedCities = all_cities.slice(1);
                            var itineraryLen = mappedCities.length;
                            var baseCity = all_cities[0];

                            // ✅ build skipDays
                            var skipDays = [];
                            skipDays.push(0);                   // always skip first
                            skipDays.push(itineraryLen - 1);    // always skip last

                            for (var i = 0; i < itineraryLen; i++) {
                                if (mappedCities[i] !== baseCity) {
                                    skipDays.push(i); // skip all non-base city days
                                    // also skip the first base city day right after change
                                    if (i + 1 < itineraryLen && mappedCities[i + 1] === baseCity) {
                                        skipDays.push(i + 1);
                                    }
                                }
                            }

                            // Debug
                            console.log("all_cities:", all_cities);
                            console.log("mappedCities:", mappedCities);
                            console.log("skipDays:", skipDays);

                            // ✅ clear only non-skipped days
                            for (var i = 0; i < itineraryLen; i++) {
                                var ul = $(".itinerary_ul").eq(i);
                                if (skipDays.includes(i)) {
                                    console.log("SKIP clear: Day", i, "City:", mappedCities[i]);
                                    continue;
                                }
                                console.log("CLEAR: Day", i, "City:", mappedCities[i]);
                                ul.html("");
                            }

                            // ✅ append itinerary data
                            for (var i = 0; i < itineraryLen; i++) {
                                var ul = $(".itinerary_ul").eq(i);
                                var dayPlan = itinerary[i];
                                if (skipDays.includes(i)) {
                                    console.log("SKIP append: Day", i, "City:", mappedCities[i]);
                                    continue;
                                }
                                console.log("APPEND: Day", i, "City:", mappedCities[i], "Activities:", dayPlan.activities.length);

                                dayPlan.activities.forEach(function (activity) {
                                    var act =
                                        'Entry Fee : ' + (activity.entry_ticket_fee || '0') + ' (A) ' +
                                        (activity.child_entry_ticket_fee || '0') + ' (C)  | ' +
                                        'Start Time: ' + (activity.departing_time_from_hotel || '0') + ' | ' +
                                        'Duration: ' + (activity.duration_hours || '0') + 'h ' +
                                        '<button type="button" data-site-id="' + activity.id + '" class="btn btn-sm btn-link activities" style="padding:0;">Add Activities</button>';

                                    var html = "<li style='display:inline-flex;'>"
                                        + "<input type='hidden' name='hdn_site_id[" + (i) + "][]' value='" + activity.id + "'>"
                                        + "<i class='fa fa-circle-o' style='margin:6px;'></i>"
                                        + "<input type='hidden' name='hdn_itinerary_content[" + (i) + "][]' value='" + activity.site_name + "'>"
                                        + "<div>" + activity.site_name + " <br>(" + act + ")</div>"
                                        + "<i title='Remove' class='bi bi-x-lg edit-remove' style='color:red;cursor: pointer;float: right;margin-top: 5px;position:relative;'></i>"
                                        + "<input type='hidden' class='activities-list' name='hdn_activities[" + (i) + "][]' value=''>"
                                        + "</li>";

                                    ul.append(html);
                                });
                            }
                        },
                        error: function (xhr) {
                            console.error("Failed to fetch itinerary", xhr.responseText);
                        },
                        complete: function () {
                            $("#spinnerOverlay").css("display", "none");
                        }
                    });
                }
            });
        
        function validateFormFields() 
        {
            var errors = [];
            
            // ROE validation
            var roe = $("#roe").val().trim();
            var enquiry_abbr = $("#enquiry_abbr").val().trim();
            var flightDetails = $("input[name='fligt_details']:checked").val();
            
            if (flightDetails === "yes") {
                var originCity = $("#origin_city").val().trim();
                var arrival_city = $("#flight-city-initial-arrival").val().trim();
                var arrival_time = $("#initial-airline-departure-time").val();
                var departing_time = $(".airline-search-depart-time").val();
            } 
            else if (flightDetails === "no") {
                var originCity = $("input[name='origin_city_on']").val().trim();
                var arrival_city = $("#flight-city-initial-arrival_no").val().trim();
                var arrival_time = $("#arrival_time_selection").val();
                var departing_time = $("#departing_time_selection").val();
            }
            
            var adults_num = $("#number_of_adults").val();
            var child_num = $("#number_of_child").val();
            if (!adults_num || adults_num <= 0) {
                errors.push("Number of adults is required and must be greater than 0");
            }
            if (!child_num) child_num = 0; 
            
            var no_of_nights = parseInt($("#number_of_nights").val()) || 1;
            if (no_of_nights <= 0) {
                errors.push("Number of nights is required");
            }
            
            var cityNames = [];
            var hasCity = false;
            $('input[name="arrival_cities[]"]').each(function() {
                var city = $(this).val().trim();
                if (city) {
                    cityNames.push(city);
                    hasCity = true;
                }
            });
            if (!hasCity) {
                errors.push("At least one arrival city is required");
            }
            
            return {
                isValid: errors.length === 0,
                errors: errors,
                data: {
                    enquiry_abbr: enquiry_abbr,
                    roe: roe,
                    flightDetails: flightDetails,
                    originCity: originCity,
                    arrival_city: arrival_city,
                    arrival_time: arrival_time,
                    departing_time: departing_time,
                    early_checkin: $("#initial_early_checkin").is(":checked") ? "on" : "no",
                    late_checkout: $("#initial_late_checkout").is(":checked") ? "on" : "no",
                    adults_num: adults_num,
                    child_num: child_num,
                    no_of_nights: no_of_nights,
                    cityNames: cityNames,
                }
            };
        }
    
        $("#similar_quote").on("click", function() 
        {
            var validation = validateFormFields();
            
            if (!validation.isValid) {
                var errorMessage = "Please fill in all required fields:<br><br>";
                validation.errors.forEach(function(error) {
                    errorMessage += "• " + error + "<br>";
                });
                
                Swal.fire({
                    icon: 'error',
                    title: 'Validation Error',
                    html: errorMessage,
                    confirmButtonText: 'OK',
                    width: '500px'
                });
                return;
            }
            
            var data = validation.data;
            
            $("#similarQuoteModal").modal('show');
            $("#similarQuotesTable tbody").html(
                '<tr><td colspan="8" class="text-center">' +
                '<div class="spinner-border text-primary" role="status">' +
                '<span class="sr-only">Loading...</span>' +
                '</div> Loading similar quotes...</td></tr>'
            );
            
            // Use data from validation object
            $.ajax({
                url: "<?php echo base_url('quotes/fetch_similar'); ?>",
                type: "POST",
                dataType: "json",
                data: {
                    enquiry_abbr: data.enquiry_abbr,
                    roe: data.roe,
                    origin_city: data.originCity,
                    arrival_city: data.arrival_city,
                    arrival_time: data.arrival_time,
                    departing_time: data.departing_time,
                    early_checkin: data.early_checkin,
                    late_checkout: data.late_checkout,
                    adults_num: data.adults_num,
                    child_num: data.child_num,
                    no_of_nights: data.no_of_nights,
                    city_names: JSON.stringify(data.cityNames),
                },
                success: function(response) {
                    if (response.status === "success") {
                        populateSimilarQuotesTable(response.data);
                    } else {
                        $("#similarQuotesTable tbody").html(
                            '<tr><td colspan="8" class="text-center text-danger">' + 
                            response.message + 
                            '</td></tr>'
                        );
                    }
                },
                error: function(xhr, status, error) {
                    console.error("Error:", error);
                    $("#similarQuotesTable tbody").html(
                        '<tr><td colspan="8" class="text-center text-danger">' +
                        'Error loading similar quotes. Please try again.' +
                        '</td></tr>'
                    );
                }
            });
        });
        
        function populateSimilarQuotesTable(quotes) {
            var tbody = $("#similarQuotesTable tbody");
            tbody.empty();
            
            if (quotes.length === 0) {
                tbody.html(
                    '<tr><td colspan="7" class="text-center text-warning">' +
                    'No similar quotes found' +
                    '</td></tr>'
                );
                return;
            }
            
            $.each(quotes, function(index, quote) {
                var safeHtml = '';
                var itineraryHtml = '';
                if (quote.cost_table_html) {
                    safeHtml = quote.cost_table_html
                        .replace(/'/g, "&#39;")
                        .replace(/"/g, "&quot;");
                }
                
                if (quote.itinerary_html) {
                    itineraryHtml = quote.itinerary_html
                        .replace(/'/g, "&#39;")
                        .replace(/"/g, "&quot;");
                }
                
                var enquiryNo = quote.enquiry_no || 'N/A';
                
                var row = '<tr>' +
                    '<td>' + (quote.enquiry_no || 'N/A') + '</td>' +
                    // '<td>' + (quote.city_of_origin || 'N/A') + '</td>' +
                    // '<td>' + (quote.city_of_arrival || 'N/A') + '</td>' +
                    '<td>' + (quote.number_persons + 'A+' + quote.number_child + 'C') + '</td>' +
                    '<td>' + (quote.number_of_nights || 'N/A') + '</td>' +
                    '<td>' + (quote.check_in_date 
                    ? new Date(quote.check_in_date).toLocaleDateString('en-GB', {
                        day: '2-digit',
                        month: 'short',
                        year: 'numeric'
                    }).replace(/ /g, '-') 
                    : 'N/A') + '</td>' +
                    '<td>' + (quote.check_out_date 
                    ? new Date(quote.check_out_date).toLocaleDateString('en-GB', {
                        day: '2-digit',
                        month: 'short',
                        year: 'numeric'
                    }).replace(/ /g, '-') 
                    : 'N/A') + '</td>' +
                    '<td>' + (quote.created 
                    ? new Date(quote.created).toLocaleDateString('en-GB', {
                        day: '2-digit',
                        month: 'short',
                        year: 'numeric'
                    }).replace(/ /g, '-') 
                    : 'N/A') + '</td>' +
                    '<td>' +
                    '<button class="btn btn-sm btn-info cost-preview-btn mr-1" ' +
                        'data-id="' + quote.id + '" ' +
                        'data-enquiry_no="' + enquiryNo + '" ' +
                        'data-itinerary_html="' + itineraryHtml + '" ' +
                        'data-html="' + safeHtml + '">' +
                        '<i class="fa fa-eye"></i> Preview' +
                    '</button>&nbsp;' +
                    '<button class="btn btn-sm btn-success quotations-made" data-id="' + quote.id + '">' +
                    '<i class="fa fa-check"></i> Use' +
                    '</button>' +
                    '</td>' +
                    '</tr>';
                
                tbody.append(row);
            });
        }
        $(document).on('click', '.cost-preview-btn', function() 
        {
            var quoteId = $(this).data('id');
            var enquiry_no = $(this).data('enquiry_no');
            var costHtml = $(this).data('html');
            var itineraryHtml = $(this).data('itinerary_html');
            
            console.log("Preview clicked for quote:", quoteId);
            console.log("HTML length:", costHtml ? costHtml.length : 0);
            
            if (costHtml && costHtml.trim() !== '') {
                showCostPreview(costHtml, quoteId, enquiry_no, itineraryHtml);
            } else {
                Swal.fire({
                    icon: 'warning',
                    title: 'No Cost Data',
                    text: 'No cost table HTML available for this quote.',
                    confirmButtonText: 'OK'
                });
            }
        });

        function showCostPreview(costHtml, quoteId, enquiry_no, itineraryHtml) 
        {
            console.log("Opening cost preview for quote:", quoteId);
            
            var decodedHtml = costHtml
                .replace(/&#39;/g, "'")
                .replace(/&quot;/g, '"')
                .replace(/\\"/g, '"')
                .replace(/\\'/g, "'");
            
            $("#previewQuoteId").text(enquiry_no);
    
            $("#formattedPreviewContent").html(decodedHtml);
            $("#formattedItineraryPreviewContent").html(itineraryHtml);
            
            var costPreviewModal = new bootstrap.Modal(document.getElementById('costPreviewModal'));
            costPreviewModal.show();
            
            $("#useThisCostBtn").off('click').on('click', function() {
                costPreviewModal.hide();
            });
        }
    
