                        /**
                         * Multiple encoded JSON ko safely actual array mein convert karega.
                         *
                         * Examples:
                         * []
                         * "[]"
                         * "\"[]\""
                         * "\"\\\"[]\\\"\""
                         */
                        function parseJsonArraySafely(value) {
                            let parsedValue = value;

                            for (let i = 0; i < 5; i++) {
                                if (typeof parsedValue !== 'string') {
                                    break;
                                }

                                const trimmedValue = parsedValue.trim();

                                if (
                                    trimmedValue === '' ||
                                    trimmedValue === 'null' ||
                                    trimmedValue === 'undefined'
                                ) {
                                    return [];
                                }

                                try {
                                    parsedValue = JSON.parse(trimmedValue);
                                } catch (error) {
                                    console.warn('Invalid city transfer JSON:', value);
                                    return [];
                                }
                            }

                            return Array.isArray(parsedValue) ? parsedValue : [];
                        }

                        /**
                         * Sabhi days ke transfer-related sections ko reset aur hide karega.
                         */

                        function getFieldColumn(field) {
                            if (!field) {
                                return null;
                            }

                            return field.closest(
                                'div[class*="col-md-"], div[class*="col-sm-"], div[class*="col-lg-"]'
                            ) || field.parentElement;
                        }

                        function resetAllCityTransferRows() {
                            const allDayRows = document.querySelectorAll('.city-details .row.mt-2');

                            allDayRows.forEach(parentRow => {
                                /*
                                * Transfer mode column
                                * :has selector ke badle direct select closest use kar rahe hain.
                                */
                                const transferSelect = parentRow.querySelector('.qtn-transfer');
                                const transferDiv = getFieldColumn(transferSelect);

                                if (transferDiv) {
                                    transferDiv.classList.add('hide');
                                    transferDiv.style.setProperty('display', 'none', 'important');
                                }

                                if (transferSelect) {
                                    transferSelect.value = '';
                                }

                                // Transfer date column
                                const transferDate = parentRow.querySelector('.qtn-transfer-date');
                                const dateDiv = transferDate
                                    ? transferDate.closest('.col-md-6')
                                    : null;

                                if (dateDiv) {
                                    dateDiv.classList.add('hide');
                                    dateDiv.style.setProperty('display', 'none', 'important');
                                }

                                if (transferDate) {
                                    transferDate.value = '';
                                }

                                // Route change section
                                const routeChangeDiv = parentRow.querySelector('.route-change');

                                if (routeChangeDiv) {
                                    routeChangeDiv.classList.add('hide');
                                    routeChangeDiv.style.setProperty('display', 'none', 'important');

                                    routeChangeDiv
                                        .querySelectorAll('input[type="radio"]')
                                        .forEach(radio => {
                                            radio.checked =
                                                String(radio.value).toLowerCase() === 'no';
                                        });
                                }

                                // Overnight section
                                const overnightDiv = parentRow.querySelector('.overnight-type');

                                if (overnightDiv) {
                                    overnightDiv.classList.add('hide');
                                    overnightDiv.style.setProperty('display', 'none', 'important');

                                    overnightDiv
                                        .querySelectorAll('input[type="radio"]')
                                        .forEach(radio => {
                                            radio.checked = false;
                                            radio.disabled = false;

                                            const label = radio.closest('label');
                                            if (label) {
                                                label.style.display = '';
                                            }
                                        });
                                }

                                // Guide section
                                const guideDiv = parentRow.querySelector('.with-train');

                                if (guideDiv) {
                                    guideDiv.style.setProperty('display', 'none', 'important');

                                    guideDiv
                                        .querySelectorAll('input[type="radio"]')
                                        .forEach(radio => {
                                            radio.checked = false;
                                        });
                                }

                                // Day trip section reset
                                const dayTripDiv = parentRow.querySelector('.day_trip');

                                if (dayTripDiv) {
                                    dayTripDiv
                                        .querySelectorAll('input[type="radio"]')
                                        .forEach(radio => {
                                            radio.checked =
                                                String(radio.value).toLowerCase() === 'no';
                                        });
                                }
                            });
                        }

                        const quotationData =
                            data.details &&
                            Array.isArray(data.details.quotation) &&
                            data.details.quotation.length
                                ? data.details.quotation[0]
                                : null;

                        const cityTransferData1 = quotationData
                            ? parseJsonArraySafely(quotationData.city_transfer)
                            : [];

                        /*
                        * localStorage mein ab clean array hi save hogi.
                        * Empty data ke liye value simply "[]" hogi.
                        */
                        localStorage.setItem(
                            'city_transfer_details',
                            JSON.stringify(cityTransferData1)
                        );

                        setTimeout(function () {
                            /*
                            * Sabse pehle all days reset honge.
                            * Isse first day ki default transfer mode aur overnight section hide ho jayegi.
                            */
                            resetAllCityTransferRows();

                            console.log('City Transfer Data:', cityTransferData1);

                            /*
                            * Empty array hai to aage koi section show nahi karna.
                            */
                            if (!cityTransferData1.length) {
                                console.log(
                                    'No city transfer data found. All transfer sections are hidden.'
                                );

                                return;
                            }

                            const daysWithData = cityTransferData1
                                .map(item => parseInt(item.day, 10))
                                .filter(day => !Number.isNaN(day));

                            console.log('Days with transfer data:', daysWithData);

                            cityTransferData1.forEach(item => {
                                const day = parseInt(item.day, 10);

                                if (Number.isNaN(day)) {
                                    return;
                                }

                                const allDaySpans = document.querySelectorAll(
                                    '.city-details span.bold'
                                );

                                allDaySpans.forEach(span => {
                                    const dayMatch = span.textContent
                                        .trim()
                                        .match(new RegExp(`Day\\s+${day}\\s+City`, 'i'));

                                    if (!dayMatch) {
                                        return;
                                    }

                                    const parentRow = span.closest('.row.mt-2');

                                    if (!parentRow) {
                                        return;
                                    }

                                    console.log(`Processing saved transfer for Day ${day}:`, item);

                                    // Transfer mode column show
                                    const transferSelect =
                                        parentRow.querySelector('.qtn-transfer');

                                    const transferDiv = getFieldColumn(transferSelect);

                                    if (transferDiv) {
                                        transferDiv.classList.remove('hide');
                                        transferDiv.style.removeProperty('display');
                                    }

                                    // Transfer date column show
                                    const transferDate =
                                        parentRow.querySelector('.qtn-transfer-date');

                                    const dateDiv = transferDate
                                        ? transferDate.closest('.col-md-6')
                                        : null;

                                    if (dateDiv) {
                                        dateDiv.classList.remove('hide');
                                        dateDiv.style.removeProperty('display');
                                    }

                                    // Route change show
                                    const routeChangeDiv =
                                        parentRow.querySelector('.route-change');

                                    if (routeChangeDiv) {
                                        routeChangeDiv.classList.remove('hide');
                                        routeChangeDiv.style.removeProperty('display');
                                    }

                                    // Route change radio
                                    const routeChangeValue =
                                        item.route_change === 'yes' ? 'yes' : 'no';

                                    parentRow
                                        .querySelectorAll('input[name^="route_change"]')
                                        .forEach(radio => {
                                            radio.checked =
                                                radio.value === routeChangeValue;
                                        });

                                    // Day trip radio
                                    if (
                                        Object.prototype.hasOwnProperty.call(item, 'daytrip') &&
                                        item.daytrip !== null &&
                                        item.daytrip !== undefined
                                    ) {
                                        parentRow
                                            .querySelectorAll(
                                                '.day_trip input[type="radio"]'
                                            )
                                            .forEach(radio => {
                                                radio.checked =
                                                    radio.value === item.daytrip;
                                            });
                                    }

                                    // Transfer mode set
                                    if (transferSelect && item.transfer_mode) {
                                        transferSelect.value = item.transfer_mode;

                                        transferSelect.dispatchEvent(
                                            new Event('change', {
                                                bubbles: true
                                            })
                                        );

                                        applyOvernightState(
                                            $(parentRow),
                                            item.transfer_mode,
                                            item.overnight_type || ''
                                        );
                                    }

                                    // Guide section
                                    const guideDiv =
                                        parentRow.querySelector('.with-train');

                                    if (guideDiv) {
                                        const hasGuideData =
                                            Object.prototype.hasOwnProperty.call(
                                                item,
                                                'travel_with_guide'
                                            ) &&
                                            item.travel_with_guide !== null &&
                                            item.travel_with_guide !== undefined &&
                                            item.travel_with_guide !== '';

                                        if (hasGuideData) {
                                            guideDiv.style.removeProperty('display');

                                            guideDiv
                                                .querySelectorAll('input[type="radio"]')
                                                .forEach(radio => {
                                                    radio.checked =
                                                        radio.value ===
                                                        item.travel_with_guide;
                                                });
                                        } else {
                                            guideDiv.style.setProperty(
                                                'display',
                                                'none',
                                                'important'
                                            );

                                            guideDiv
                                                .querySelectorAll('input[type="radio"]')
                                                .forEach(radio => {
                                                    radio.checked = false;
                                                });
                                        }
                                    }

                                    /*
                                    * Aapka existing train-specific AJAX code
                                    * isi jagah continue rahega.
                                    */

                                    // Transfer mode set
                                    if (transferSelect && item.transfer_mode) {

                                        transferSelect.value = item.transfer_mode;

                                        transferSelect.dispatchEvent(
                                            new Event('change', {
                                                bubbles: true
                                            })
                                        );

                                        applyOvernightState(
                                            $(parentRow),
                                            item.transfer_mode,
                                            item.overnight_type || '',
                                            day
                                        );

                                        // Saved train details restore
                                        if (item.transfer_mode === 'train') {
                                            restoreSavedTrainData(
                                                parentRow,
                                                item,
                                                day
                                            );
                                        }
                                    }
                                });
                            });
                        }, 500);


                            function applyOvernightState(
                                $row,
                                transferMode,
                                overnightType,
                                dayNo
                            ) {
                                const $overnightContainer =
                                    $row.find('.overnight-type');

                                if (!$overnightContainer.length) {
                                    return;
                                }

                                const $overnightRadio =
                                    $overnightContainer.find(
                                        'input[value="overnight"]'
                                    );

                                const $dropoffRadio =
                                    $overnightContainer.find(
                                        'input[value="drop_off"]'
                                    );

                                /*
                                * Complete reset
                                */
                                $overnightContainer
                                    .addClass('hide')
                                    .css('display', 'none');

                                $overnightContainer
                                    .find('input[type="radio"]')
                                    .prop('checked', false)
                                    .prop('disabled', false);

                                $overnightContainer
                                    .find('label')
                                    .show();

                                /*
                                * Overnight type sirf Road ke liye
                                */
                                if (transferMode !== 'road') {
                                    return;
                                }

                                $overnightContainer
                                    .removeClass('hide')
                                    .css('display', '');

                                /*
                                * Saved Overnight
                                */
                                if (overnightType === 'overnight') {

                                    $overnightRadio
                                        .prop('checked', true)
                                        .prop('disabled', false);

                                    $dropoffRadio
                                        .prop('checked', false)
                                        .prop('disabled', true);

                                    return;
                                }

                                /*
                                * Saved Drop Off
                                */
                                if (overnightType === 'drop_off') {

                                    $overnightRadio
                                        .prop('checked', false)
                                        .prop('disabled', true)
                                        .closest('label')
                                        .hide();

                                    $dropoffRadio
                                        .prop('checked', true)
                                        .prop('disabled', true)
                                        .closest('label')
                                        .show();

                                    return;
                                }

                                /*
                                * Edit data mein overnight_type saved nahi hai.
                                * Existing country/city rules se default selection lagao.
                                */
                                const cityVal = String(
                                    $row.find('.qtn-city').val() || ''
                                ).trim();

                                const arrivalCity = String(
                                    $('#flight-city-initial-arrival').val() || ''
                                ).trim();

                                const countryName =
                                    getCountryFromEnquiry(qdata.enquiry_abbr);

                                applyRoadTransferRules(
                                    $row,
                                    countryName,
                                    cityVal,
                                    arrivalCity,
                                    dayNo
                                );
                            }
            
                        // --- NEW: Load city_route_transfer (route‑change sections) ---
                        if (data.details.quotation[0].city_route_transfer) {
                            const routeTransferRaw = data.details.quotation[0].city_route_transfer;
                            let routeTransferData = routeTransferRaw;
                            try {
                                if (typeof routeTransferRaw === 'string') {
                                    routeTransferData = JSON.parse(routeTransferRaw);
                                    if (typeof routeTransferData === 'string') {
                                        routeTransferData = JSON.parse(routeTransferData);
                                    }
                                }
                                console.log('Route Change Data:', routeTransferData);
                            } catch (e) {
                                console.error('Error parsing city_route_transfer:', e);
                                routeTransferData = [];
                            }

                            // Group sections by day
                            const sectionsByDay = {};
                            routeTransferData.forEach(section => {
                                const day = section.day;
                                if (!sectionsByDay[day]) sectionsByDay[day] = [];
                                sectionsByDay[day].push(section);
                            });

                            // Helper: add a new section for a given day (clones the first one and updates indices)
                           function addRouteChangeSection(dayNumber, newIndex) {
                            // console.log('1111111');
                                // Find the first existing section for this day
                                const existingSections = document.querySelectorAll(`.route-change-section[data-day="${dayNumber-1}"]`);
                                const templateSection = existingSections[0];
                                if (!templateSection) {
                                    console.error(`No existing section to clone for day ${dayNumber}`);
                                    return null;
                                }

                                const newSection = templateSection.cloneNode(true);
                                newSection.setAttribute('data-section', newIndex);

                                // Remove the old "Add" button from the cloned section (to avoid duplicates)
                                const oldAddBtn = newSection.querySelector('.add-route');
                                if (oldAddBtn) oldAddBtn.remove();

                                // Update input names to reflect the new section index
                                newSection.querySelectorAll('input, select').forEach(field => {
                                    const name = field.getAttribute('name');
                                    if (name) {
                                        const newName = name.replace(/\[(\d+)\]\[(\d+)\]/, `[${dayNumber-1}][${newIndex}]`);
                                        field.setAttribute('name', newName);
                                    }
                                });

                                // Reset values
                                newSection.querySelectorAll('input, select').forEach(field => {
                                    if (field.type !== 'radio' && field.type !== 'checkbox') {
                                        field.value = '';
                                    }
                                });
                                newSection.querySelectorAll('input[type="radio"]').forEach(radio => {
                                    radio.checked = false;
                                });

                                // Find the container that holds the action buttons (the div with the old "Add" button)
                                const buttonContainer = newSection.querySelector('.col-md-12');
                                if (buttonContainer) {
                                    // Clear the container
                                    buttonContainer.innerHTML = '';

                                    if (newIndex === 0) {
                                        // Only the first section gets the Add button
                                        const addBtn = document.createElement('button');
                                        addBtn.type = 'button';
                                        addBtn.className = 'btn btn-sm btn-success add-route';
                                        addBtn.textContent = '+';
                                        buttonContainer.appendChild(addBtn);
                                    } else {
                                        // All additional sections get only a Remove button
                                        const removeBtn = document.createElement('button');
                                        removeBtn.type = 'button';
                                        removeBtn.className = 'btn btn-sm btn-danger remove-route';
                                        removeBtn.textContent = '-';
                                        buttonContainer.appendChild(removeBtn);
                                    }
                                }

                                // Insert the new section after the last section for this day
                                const lastSection = existingSections[existingSections.length - 1];
                                lastSection.parentNode.insertBefore(newSection, lastSection.nextSibling);

                                return newSection;
                            }

                            // For each day that has saved sections
                            Object.keys(sectionsByDay).forEach(day => {
                                const dayNumber = parseInt(day);
                                const daySections = sectionsByDay[dayNumber];

                                // Find the day row
                                const daySpans = document.querySelectorAll('.city-details span.bold[style*="text-transform:capitalize"]');
                                let targetRow = null;
                                daySpans.forEach(span => {
                                    if (span.textContent.includes(`Day ${dayNumber} City`)) {
                                        targetRow = span.closest('.row.mt-2');
                                    }
                                });
                                if (!targetRow) return;

                                // Set route_change radio to "yes" and trigger change
                                const routeChangeRadios = targetRow.querySelectorAll('input[name^="route_change"]');
                                routeChangeRadios.forEach(radio => {
                                    if (radio.value === 'yes') radio.checked = true;
                                });
                                const changeEvent = new Event('change', { bubbles: true });
                                const checkedRadio = targetRow.querySelector('input[name^="route_change"]:checked');
                                if (checkedRadio) checkedRadio.dispatchEvent(changeEvent);

                                // Wait for the slide‑down effect and for sections to become visible
                                setTimeout(() => {
                                    // Get all existing sections for this day (they are hidden initially)
                                    let existingSections = Array.from(document.querySelectorAll(`.route-change-section[data-day="${dayNumber-1}"]`));

                                    // Make them visible (remove any inline style or hide class)
                                    existingSections.forEach(section => {
                                        section.style.display = '';
                                        section.classList.remove('hide');
                                    });

                                    // Ensure we have enough sections
                                    for (let i = 0; i < daySections.length; i++) {
                                        let sectionDiv = existingSections.find(sec => parseInt(sec.getAttribute('data-section')) === i);
                                        if (!sectionDiv) {
                                            sectionDiv = addRouteChangeSection(dayNumber, i);
                                            if (sectionDiv) {
                                                existingSections = Array.from(document.querySelectorAll(`.route-change-section[data-day="${dayNumber-1}"]`));
                                            } else {
                                                continue;
                                            }
                                        }
                                        // Populate this section with saved data
                                        populateRouteChangeSection(sectionDiv, daySections[i], dayNumber);
                                    }

                                    // Remove any extra sections beyond the saved count
                                    for (let i = existingSections.length - 1; i >= daySections.length; i--) {
                                        existingSections[i].remove();
                                    }
                                }, 1000);
                            });
                        }

                        // Helper: populate a route-change section with saved data
                        function populateRouteChangeSection(sectionDiv, savedSection, dayNumber) {
                            // console.log(savedSection,'savedSectionsavedSection');
                            // Fill from_city and to_city
                            const fromCityInput = sectionDiv.querySelector('.from-city');
                            const toCityInput = sectionDiv.querySelector('.to-city');
                            
                            if (fromCityInput) fromCityInput.value = savedSection.from_city || '';
                            if (toCityInput) toCityInput.value = savedSection.to_city || '';

                            // Set transfer mode and trigger change to show/hide train block
                            const transferModeSelect = sectionDiv.querySelector('.transfer-mode');
                            if (transferModeSelect) {
                                transferModeSelect.value = savedSection.transfer_mode || 'road';
                                $(transferModeSelect).trigger('change');
                            }

                            // Set overnight type radios
                            const overnightRadios = sectionDiv.querySelectorAll('input[name$="[overnight_type]"]');
                            overnightRadios.forEach(radio => {
                                radio.checked = (radio.value === savedSection.overnight_type);
                            });

                            // Set travel_with_guide radios
                            const guideRadios = sectionDiv.querySelectorAll('input[name$="[travelling_with_guide]"]');
                            guideRadios.forEach(radio => {
                                radio.checked = (radio.value === savedSection.travel_with_guide);
                            });

                            // If train mode, populate train details
                            if (savedSection.transfer_mode === 'train' && savedSection.train_id) {
                                // console.log('fromCityInput',fromCityInput);
                                // console.log('toCityInput',toCityInput);
                                const localTrainDiv = sectionDiv.querySelector('.local-train');
                                if (localTrainDiv) {
                                    const trainInput = localTrainDiv.querySelector('.train-search');
                                    const trainIdHidden = localTrainDiv.querySelector('.train-id');
                                    const ticketSelect = localTrainDiv.querySelector('.ticket-type');
                                    const dayNoHidden = localTrainDiv.querySelector('.train-day-no');
                                    if (dayNoHidden) dayNoHidden.value = dayNumber;

                                    const fromCity = savedSection.from_city;
                                    const toCity = savedSection.to_city;
                                    // const trainId = savedSection.train_id;
                                    let selectedCountry = '';
                                    if (typeof getCountryFromEnquiry === 'function') {
                                        if (typeof qdata !== 'undefined' && qdata.enquiry_abbr) {
                                            selectedCountry = getCountryFromEnquiry(qdata.enquiry_abbr);
                                        }
                                    }

                                    $.ajax({
                                        url: "<?= base_url() ?>admin/quotation/get_train_by_id",
                                        type: "POST",
                                        dataType: "json",
                                        data: {
                                            schedule_id: savedSection.train_id,
                                            from_city: fromCity,
                                            to_city: toCity,
                                            country: selectedCountry
                                        },
                                        success: function(trainData) {
                                            if (trainData) {
                                                if (trainInput) trainInput.value = trainData.label;
                                                if (trainIdHidden) trainIdHidden.value = trainData.schedule_id;

                                                // Populate ticket types
                                                if (ticketSelect) {
                                                    ticketSelect.innerHTML = '';
                                                    ticketSelect.appendChild(new Option('Select Ticket Type', ''));
                                                    if (Array.isArray(trainData.types)) {
                                                        trainData.types.forEach(type => {
                                                            const label = type.replace(/_/g, ' ').toUpperCase();
                                                            ticketSelect.appendChild(new Option(label, type));
                                                        });
                                                        if (savedSection.ticket_type) {
                                                            ticketSelect.value = savedSection.ticket_type;
                                                        }
                                                    }
                                                }

                                                // Show timing
                                                if (savedSection.train_depart || savedSection.train_arrive) {
                                                    let $timingSpan = $(localTrainDiv).find('.train-timing');
                                                    if ($timingSpan.length === 0) {
                                                        $timingSpan = $('<span class="train-timing" style="margin-left:15px; font-size:12px; color:#333;"></span>');
                                                        $(ticketSelect).after($timingSpan);
                                                    }
                                                    let timeStr = '';
                                                    if (savedSection.train_depart && savedSection.train_arrive) {
                                                        timeStr = '🕒 Depart: ' + savedSection.train_depart + ' | Arrive: ' + savedSection.train_arrive;
                                                    } else if (savedSection.train_depart) {
                                                        timeStr = '🕒 Depart: ' + savedSection.train_depart;
                                                    } else if (savedSection.train_arrive) {
                                                        timeStr = '🕒 Arrive: ' + savedSection.train_arrive;
                                                    }
                                                    $timingSpan.html(timeStr);
                                                }
                                            }
                                        },
                                        error: function(xhr, status, error) {
                                            console.error('Error loading train for route‑change section:', error);
                                        }
                                    });
                                }
                            }
                        }

                        function restoreSavedTrainData(parentRow, item, day)
                        {
                            if (
                                item.transfer_mode !== 'train' ||
                                !item.train_id
                            ) {
                                return;
                            }

                            const $dayRow = $(parentRow);
                            const $trainRow = $dayRow.next('.local-train');

                            if (!$trainRow.length) {
                                console.warn('Train row not found for Day ' + day);
                                return;
                            }

                            const toCity = $.trim(
                                $dayRow.find('.qtn-city').val() || ''
                            );

                            /*
                            * Previous normal day row find karo.
                            * local-train row ko skip karna zaroori hai.
                            */
                            const $previousDayRow = $dayRow
                                .prevAll('.row.mt-2')
                                .not('.local-train')
                                .first();

                            let fromCity = $.trim(
                                $previousDayRow.find('.qtn-city').val() || ''
                            );

                            /*
                            * First applicable day ke liye arrival city fallback.
                            */
                            if (!fromCity) {
                                fromCity = $.trim(
                                    $('#flight-city-initial-arrival').val() || ''
                                );
                            }

                            if (!fromCity || !toCity) {
                                console.warn(
                                    'Train cities missing for Day ' + day,
                                    {
                                        from_city: fromCity,
                                        to_city: toCity
                                    }
                                );

                                return;
                            }

                            const $trainInput = $trainRow.find('.train-search');
                            const $ticketSelect = $trainRow.find('.ticket-type');
                            const $timingSpan = $trainRow.find('.train-timing');

                            /*
                            * Hidden train ID field create karo.
                            */
                            if (!$trainRow.find('.train-id').length) {
                                $trainInput.after(
                                    '<input type="hidden" ' +
                                    'class="train-id" ' +
                                    'name="train_id[]">'
                                );
                            }

                            /*
                            * Hidden day number field create karo.
                            */
                            if (!$trainRow.find('.train-day-no').length) {
                                $trainInput.after(
                                    '<input type="hidden" ' +
                                    'class="train-day-no" ' +
                                    'name="train_day_no[]">'
                                );
                            }

                            /*
                            * Saved values immediately set karo.
                            */
                            $trainRow.find('.train-id').val(item.train_id);
                            $trainRow.find('.train-day-no').val(day);

                            /*
                            * Train section visible karo.
                            */
                            $trainRow
                                .stop(true, true)
                                .show();

                            $.ajax({
                                url: "<?= base_url('admin/quotation/get_train_by_id') ?>",
                                type: "POST",
                                dataType: "json",

                                data: {
                                    schedule_id: item.train_id,
                                    from_city: fromCity,
                                    to_city: toCity,
                                    country: getCountryFromEnquiry(qdata.enquiry_abbr)
                                },

                                success: function(response)
                                {
                                    /*
                                    * API array ya object dono return kar sakti hai.
                                    */
                                    const trainData = Array.isArray(response)
                                        ? response[0]
                                        : response;

                                    if (!trainData) {
                                        console.warn(
                                            'Train API returned empty data for Day ' + day
                                        );

                                        return;
                                    }

                                    /*
                                    * Train name restore.
                                    */
                                    $trainInput.val(
                                        trainData.label ||
                                        trainData.name ||
                                        trainData.train_name ||
                                        ''
                                    );

                                    /*
                                    * Correct saved train ID preserve.
                                    */
                                    $trainRow.find('.train-id').val(
                                        trainData.schedule_id ||
                                        trainData.train_id ||
                                        item.train_id
                                    );

                                    /*
                                    * Ticket types populate.
                                    */
                                    $ticketSelect.empty().append(
                                        '<option value="">Select Ticket Type</option>'
                                    );

                                    if (Array.isArray(trainData.types)) {
                                        trainData.types.forEach(function(type) {
                                            const label = String(type)
                                                .replace(/_/g, ' ')
                                                .toUpperCase();

                                            $ticketSelect.append(
                                                $('<option>', {
                                                    value: type,
                                                    text: label
                                                })
                                            );
                                        });
                                    }

                                    /*
                                    * Saved ticket type list mein nahi ho tab bhi add karo.
                                    */
                                    if (
                                        item.type &&
                                        !$ticketSelect.find(
                                            'option[value="' + item.type + '"]'
                                        ).length
                                    ) {
                                        $ticketSelect.append(
                                            $('<option>', {
                                                value: item.type,
                                                text: String(item.type)
                                                    .replace(/_/g, ' ')
                                                    .toUpperCase()
                                            })
                                        );
                                    }

                                    $ticketSelect.val(item.type || '');

                                    /*
                                    * Saved timings restore.
                                    */
                                    let timingText = '';

                                    if (item.train_depart && item.train_arrive) {
                                        timingText =
                                            '🕒 Depart: ' +
                                            item.train_depart +
                                            ' | Arrive: ' +
                                            item.train_arrive;
                                    } else if (item.train_depart) {
                                        timingText =
                                            '🕒 Depart: ' +
                                            item.train_depart;
                                    } else if (item.train_arrive) {
                                        timingText =
                                            '🕒 Arrive: ' +
                                            item.train_arrive;
                                    }

                                    $timingSpan.html(timingText);

                                    /*
                                    * Saved travelling with guide restore.
                                    */
                                    if (item.travel_with_guide) {
                                        $dayRow
                                            .find(
                                                '.with-train input[value="' +
                                                item.travel_with_guide +
                                                '"]'
                                            )
                                            .prop('checked', true);
                                    }

                                    updateItineraryTrainTimes();

                                    console.log(
                                        'Saved train restored for Day ' + day,
                                        {
                                            train_id: item.train_id,
                                            train_name: $trainInput.val(),
                                            ticket_type: item.type,
                                            timing: timingText
                                        }
                                    );
                                },

                                error: function(xhr, status, error)
                                {
                                    console.error(
                                        'Unable to restore train for Day ' + day,
                                        error,
                                        xhr.responseText
                                    );
                                }
                            });
                        }
                    
