                    $("#btn_proceed_to_hotels_new").on("click", function () {
                        // 1️⃣ Validate family details
                        var total_adults_num = parseInt($("#number_of_adults").val() || 0, 10);
                        var adult_num = 0;
                        var total_child_num = parseInt($("#number_of_child").val() || 0, 10);
                        var child_num = 0;

                        $(".family-adults").each(function () { adult_num += parseInt($(this).val() || 0, 10); });
                        $(".family-child").each(function () { child_num += parseInt($(this).val() || 0, 10); });

                        if (adult_num != total_adults_num || child_num != total_child_num) {
                            alert("Please Enter Complete Family Details. Total Adults: " + total_adults_num + " Total Child: " + total_child_num);
                            return false;
                        }

                        $("#quotation-make-1, #quotation-make-2, #quotation-make-3").hide();
                        $("#quotation-make-4").css("display", "flex");
                        $("#create_quotation").fadeIn(1000);
                        $("#hotel-categories, #hotel-categories-individual").html("");

                        var div_ids_arr = [];
                        var nights = $("#chk_all_hotels").is(':checked') ? 1 : qdata.nights;

                        // --- Helpers ---
                        const findSavedRooms = (hotelId, categoryName) => {
                            if (!savedHotelRoomDetails || !savedHotelRoomDetails[hotelId]) return [];
                            let roomsObj = savedHotelRoomDetails[hotelId].rooms;
                            try {
                                const parsed = JSON.parse(roomsObj);
                                for (const key in parsed) {
                                    const keyCategory = key.split("_").slice(1).join("_").trim().toLowerCase();
                                    if (keyCategory === categoryName.trim().toLowerCase()) {
                                        return parsed[key];
                                    }
                                }
                            } catch (e) {
                                console.warn("Error parsing rooms for hotel", hotelId, e);
                            }
                            return [];
                        };

                        // 3️⃣ Build hotel category columns (first night)
                        var previous_category = '';
                        for (var j = 1; j <= 1; j++) {
                            $("input[name='hotel_category[]']:checked").each(function () {
                                var category = this.value;
                                $("input[name='hdn_night_" + j + "_" + category.replaceAll(" ", "_").toLowerCase() + "_ids[]']").each(function (index) {
                                    var h = (previous_category && previous_category !== category) ? 
                                            '<div class="w-100 d-none d-md-block mb-4" style="border: 1px solid;"></div>' : '';
                                    var div_html = h + '<div class="col-md-6 scrollbar" style="padding:0px 25px;height: 500px; overflow-y: auto;width:675px;" id="' + category.replaceAll(" ", "_").toLowerCase() + '_' + index + '"><span class="bold mt-4">' + category + ' (Hotel Option ' + (index + 1) + ')</span></div>';
                                    $("#hotel-categories").append(div_html);
                                    previous_category = category;
                                    div_ids_arr.push(category.replaceAll(" ", "_").toLowerCase() + '_' + index);
                                });
                            });
                        }

                        // 4️⃣ Fetch hotel prices & render ALL categories first
                        for (var j = 1; j <= nights; j++) {
                            $("input[name='hotel_category[]']:checked").each(function () {
                                var category = this.value;
                                $("input[name='hdn_night_" + j + "_" + category.replaceAll(" ", "_").toLowerCase() + "_ids[]']").each(function (ids_index) {
                                    var hotel_id = $(this).val();
                                    var div_to_append_id = category.replaceAll(" ", "_").toLowerCase() + '_' + ids_index;
                                    let hotelName = (savedHotelRoomDetails[hotel_id] && savedHotelRoomDetails[hotel_id].name) || "Hotel";

                                    $.ajax({
                                        url: "<?php echo site_url('admin/quotation/get_family_hotel_prices'); ?>",
                                        type: "post",
                                        data: { hotel_id, check_in: qdata.checkin, check_out: qdata.checkout, type: category, room_type: '' },
                                        dataType: 'JSON',
                                        async: false,
                                        success: function (data) {
                                            if (data.response === "s" && data.details.result.length > 0) {
                                                var html = '<div class="row" style="color:#FFF;background-color:#49a6f5;font-size:14px;font-weight:600;border-radius:10px;">' +
                                                        '<div class="col-md-12">' + hotelName + '</div></div>';
                                                html += '<div class="row"><div class="offset-9 col-md-2" style="text-align:right;">Rooms</div></div>';

                                                // Group by category
                                                var categories = {};
                                                $.each(data.details.result, function(i, val) {
                                                    if (!categories[val.category_name]) {
                                                        categories[val.category_name] = [];
                                                    }
                                                    categories[val.category_name].push(val);
                                                });

                                                // FIRST: Show ALL categories from database
                                                $.each(categories, function(categoryName, categoryRooms) {
                                                    // Get saved rooms for this category
                                                    let savedCatRooms = findSavedRooms(hotel_id, categoryName);
                                                    
                                                    // Create one default row for every category
                                                    html += createRoomRow(categoryRooms, categoryName, hotel_id, j, null, true, 0);
                                                    
                                                    // THEN: If there are saved rooms, create additional rows for them
                                                    if (savedCatRooms.length > 0) {
                                                        $.each(savedCatRooms, function(savedIndex, savedRoom) {
                                                            // Skip the first one as we already created a default row
                                                            if (savedIndex > 0) {
                                                                html += createRoomRow(categoryRooms, categoryName, hotel_id, j, savedRoom, false, savedIndex);
                                                            }
                                                        });
                                                    }
                                                });

                                                $("#" + div_to_append_id).append(html);
                                                
                                                // NOW: Apply saved data to check the appropriate checkboxes
                                                applySavedDataToCategories(hotel_id, categories, j);
                                            }
                                        }
                                    });
                                });
                            });
                        }

                        // If no saved data exists, run the auto-selection logic
                        if (!savedHotelRoomDetails || Object.keys(savedHotelRoomDetails).length === 0) {
                            setTimeout(function() {
                                processOccupancyAutoSelection(div_ids_arr);
                            }, 100);
                        }
                    });

                    // Function to apply saved data to the displayed categories
                    function applySavedDataToCategories(hotel_id, categories, night) {
                        if (!savedHotelRoomDetails || !savedHotelRoomDetails[hotel_id]) return;
                        
                        try {
                            const savedRoomsObj = JSON.parse(savedHotelRoomDetails[hotel_id].rooms || '{}');
                            
                            // Loop through all saved categories
                            for (const savedKey in savedRoomsObj) {
                                const savedCategoryName = savedKey.split("_").slice(1).join("_").trim();
                                const savedRooms = savedRoomsObj[savedKey];
                                
                                // Find if this category exists in our displayed categories
                                let categoryExists = false;
                                for (const categoryName in categories) {
                                    if (categoryName.trim().toLowerCase() === savedCategoryName.toLowerCase()) {
                                        categoryExists = true;
                                        
                                        // Apply saved data to this category
                                        applySavedRoomSelections(hotel_id, categoryName, savedRooms, night);
                                        break;
                                    }
                                }
                                
                                if (!categoryExists) {
                                    console.log("Saved category not found in database:", savedCategoryName);
                                }
                            }
                        } catch (e) {
                            console.warn("Error applying saved data:", e);
                        }
                    }

                    // Function to apply specific saved room selections
                    function applySavedRoomSelections(hotel_id, categoryName, savedRooms, night) {
                        // Find all rows for this category - FIXED SELECTOR
                        const categoryRows = $(`div[data-category="${categoryName}"]`).closest('.row.mt-2');
                        
                        if (categoryRows.length === 0) {
                            console.log(`No rows found for category: ${categoryName}`);
                            return;
                        }
                        
                        console.group(`Applying saved data for ${categoryName}`);
                        console.log('Saved rooms:', savedRooms);
                        console.log('Found rows:', categoryRows.length);
                        
                        categoryRows.each(function(rowIndex) {
                            const $row = $(this);
                            const savedRoom = savedRooms[rowIndex];
                            
                            console.log(`Processing row ${rowIndex}:`, savedRoom);
                            
                            if (savedRoom && savedRoom.room_type) {
                                // Set room count
                                $row.find('input.rooms-cnt').val(savedRoom.room_count || 1);
                                console.log(`Set room count: ${savedRoom.room_count}`);
                                
                                // Reset checkboxes
                                $row.find('.chk-prices').prop('checked', false);
                                
                                // Match each saved room type
                                savedRoom.room_type.forEach(function(savedRoomType) {
                                    const savedType = savedRoomType.trim();
                                    console.log(`Matching saved type: "${savedType}"`);
                                    
                                    let matched = false;
                                    
                                    // Try to find matching checkbox
                                    $row.find('.chk-prices').each(function() {
                                        const $cb = $(this);
                                        const cbValue = $cb.val().trim();
                                        const cbPerson = $cb.data('person');
                                        
                                        // Extract basic type from saved room type (e.g., "1(A)" from "1(A) 65000")
                                        const savedBasicType = savedType.split(' ')[0];
                                        
                                        // Check for match
                                        if (cbPerson === savedBasicType) {
                                            // Additional checks for child types
                                            if (savedType.includes('CNB') && cbValue.includes('CNB')) {
                                                $cb.prop('checked', true);
                                                matched = true;
                                                console.log(`✓ CNB match: "${cbValue}"`);
                                                return false;
                                            } else if (savedType.includes('CWB') && cbValue.includes('CWB')) {
                                                $cb.prop('checked', true);
                                                matched = true;
                                                console.log(`✓ CWB match: "${cbValue}"`);
                                                return false;
                                            } else if (!savedType.includes('CNB') && !savedType.includes('CWB') && 
                                                    !cbValue.includes('CNB') && !cbValue.includes('CWB')) {
                                                // Adult or basic child match
                                                $cb.prop('checked', true);
                                                matched = true;
                                                console.log(`✓ Basic match: "${cbValue}"`);
                                                return false;
                                            }
                                        }
                                    });
                                    
                                    if (!matched) {
                                        console.log(`✗ No direct match for: "${savedType}"`);
                                        
                                        // Fallback: match by person type only
                                        const savedBasicType = savedType.split(' ')[0];
                                        const fallbackCheckbox = $row.find(`.chk-prices[data-person="${savedBasicType}"]`).first();
                                        if (fallbackCheckbox.length > 0) {
                                            fallbackCheckbox.prop('checked', true);
                                            console.log(`✓ Fallback match for: "${savedBasicType}"`);
                                        } else {
                                            console.log(`✗ No fallback checkbox found for: "${savedBasicType}"`);
                                        }
                                    }
                                });
                                
                                // Check category checkbox
                                const categoryCheckbox = $row.find('input[type="checkbox"][class^="chk_"]');
                                if (categoryCheckbox.length > 0) {
                                    categoryCheckbox.prop('checked', true);
                                    console.log(`✓ Category checkbox checked`);
                                } else {
                                    console.log(`✗ Category checkbox not found`);
                                }
                                
                            } else if (rowIndex === 0) {
                                // Default selection for first row
                                $row.find('.chk-prices').first().prop('checked', true);
                                const categoryCheckbox = $row.find('input[type="checkbox"][class^="chk_"]');
                                if (categoryCheckbox.length > 0) {
                                    categoryCheckbox.prop('checked', true);
