                                    /*
                                    * Country-wise default "Breakfast at your hotel" site ID.
                                    */
                                    function getDefaultBreakfastSiteId(enquiryAbbr) {
                                        const code = String(enquiryAbbr || '')
                                            .trim()
                                            .toUpperCase();

                                        // Georgia
                                        if (['FGE', 'IGE', 'GGE'].includes(code)) {
                                            return '178';
                                        }

                                        // Kazakhstan
                                        if (['FKZ', 'IKZ', 'GKZ'].includes(code)) {
                                            return '15';
                                        }

                                        // Azerbaijan
                                        if (['FAZ', 'IAZ', 'GAZ'].includes(code)) {
                                            return '61';
                                        }

                                        // Uzbekistan
                                        if (['FUZ', 'IUZ', 'GUZ'].includes(code)) {
                                            return '429';
                                        }

                                        return null;
                                    }

                                    const breakfastSiteId = getDefaultBreakfastSiteId(
                                        qdata.enquiry_abbr
                                    );

