                            function getSavedActivitiesForSiteAndDay(siteId, dayNumber) {
                                var savedActivities = [];
                                
                                if (!activity_cost || !activity_cost.activity_data || !Array.isArray(activity_cost.activity_data)) {
                                    return savedActivities;
                                }
                                var dayActivities = activity_cost.activity_data.find(function(dayData) {
                                    return parseInt(dayData.day) === parseInt(dayNumber);
                                });
                                
                                if (dayActivities && dayActivities.activities && Array.isArray(dayActivities.activities)) {
                                    dayActivities.activities.forEach(function(activity) {
                                        if (parseInt(activity.site_id) === parseInt(siteId)) {
                                            var activityStr = activity.activity_name + '__' + activity.adult_price + '__' + activity.child_price + 
                                                            '_|_' + activity.adult_count + '__' + activity.child_count;
                                            savedActivities.push(activityStr);
                                        }
                                    });
                                }
                                
                                return savedActivities;
                            }

                            function getSavedEntrancesForSiteAndDay(siteId, dayNumber) {
                                var savedEntrances = [];
                                if (!entrance_cost || !Array.isArray(entrance_cost)) return savedEntrances;
                                
                                // Convert 1‑based itinerary day to 0‑based stored day
                                var storedDay = parseInt(dayNumber) - 1;
                                
                                var dayEntrances = entrance_cost.find(function(item) {
                                    return parseInt(item.day) === storedDay;
                                });
                                
                                if (dayEntrances && dayEntrances.entrances && Array.isArray(dayEntrances.entrances)) {
                                    savedEntrances = dayEntrances.entrances.filter(function(entrance) {
                                        return parseInt(entrance.site_id) === parseInt(siteId);
                                    });
                                }
                                return savedEntrances;
                            }
                            

