                                                            //  itinerary_html2 += "<li style='list-style:none; padding-left:25px; font-weight:bold; color:#333;'>Activity:</li>";
                                                            itinerary_html2 += "<li style='display:inline-flex; padding-left: 30px; font-size: 12px; color: #2e2e2e;'>"
