                                }

                                if (isLastDay) {
                                    itinerary_html2 += "<li style='list-style-type: circle'>" + lastDay +"</li>";
                                }

                                itinerary_html2 += '</ul>';
                                itinerary_html2 += '<input type="text" class="form-control add-itinerary mt-2" ' +
                                                'placeholder="Search & Add Itinerary in ' + cityName + '" ' +       
                                                'data-dayname="' + dayName + '" ' +
                                                'data-day="' + dayNumber + '" ' +
                                                'data-dayindex="' + dayNumber + '">';
                                itinerary_html2 += '</div>';
                            }
                            
                            
                        }
                        else 
                            { 
                            html = 'No Prices Found';
                        }
                    } 
                }
            });
