        $(document).on('click', '.quotations-made-view', function () {

            setQuotationMode('view');

            const quotationId = $(this).data('id');

            if (!quotationId) {
                alert('Quotation ID not found');
                return;
            }

            // Preview Quote me email/cost modal open nahi hona chahiye
            $("#savedQuotationPreviewModal").modal('hide');

            $('.file_status').val('view');

            $.ajax({
                url: "<?= site_url('admin/quotation/fetch_quotation_by_id') ?>",
                type: "POST",
                dataType: "json",
                data: {
                    quotation_id: quotationId
                },
                success: function (res) {

                    if (res.status) {

                        window.currentQuotationData = res.data;

                        $(document).trigger('quotationDataLoaded', [res.data]);

                        localStorage.removeItem('db_night');
                        localStorage.setItem('db_night', res.data.no_of_nights);

                        $('#number_of_nights').val(res.data.no_of_nights);
                        $('.checkin_date').val(res.data.checkin_date);
                        $('.checkout_date').val(res.data.checkout_date);

                        if (typeof generateItineraryHTML === 'function') {
                            generateItineraryHTML(res.data.no_of_nights);
                        }

                        if (typeof generatesavedhotelHTMl === 'function') {
                            generatesavedhotelHTMl(res.data.no_of_nights);
                        }

                        // Existing saved quotation load logic ko trigger karo
                        setTimeout(function () {
                            triggerQuotationMadeForPreview(quotationId);
                        }, 200);

                        // Readonly/disabled force apply
                        setTimeout(function () {
                            if (quotationMode === 'view') {
                                $('.file_status').val('view');
                                makeQuotationReadOnly();
                            }
                        }, 700);

                        setTimeout(function () {
                            if (quotationMode === 'view') {
                                $('.file_status').val('view');
                                makeQuotationReadOnly();
                            }
                        }, 1800);

                        setTimeout(function () {
                            if (quotationMode === 'view') {
                                $('.file_status').val('view');
                                makeQuotationReadOnly();
                            }
                        }, 2800);

                    } else {
                        alert(res.message || 'Quotation data not found');
                    }
                },
                error: function (xhr, status, error) {
                    console.error("AJAX Error:", error);
                    alert("Failed to fetch quotation data");
                }
            });
        });

