        function makeQuotationReadOnly() {
            const excludedIds = [
                'create_quotation',
                'previous-to-hotels-details',
                'btn_proceed_to_itinerary',
                'previous-to-hotels',
                'previous',
                'btn_restaurants_new',
                'btn_hotel',
                'quotations-made',
                'quotations-made-view',
                'individual-previous-to-hotels',
                'individual_btn_proceed_to_itinerary',
                'similar_quote',
                'modal_quote_preview_btn',
                'modal_quote_edit_btn',
            ];

            const excludedClasses = [
                'open-quote-popup',
                'quotations-made',
                'quotations-made-view',
                'quotations-made-email-preview',
                'swal2-close',
                'swal2-confirm',
                'swal2-cancel',
                'saved-preview-close-btn'
            ];

            function isExcluded(element) {
                if (element.id && excludedIds.includes(element.id)) return true;

                for (let cls of excludedClasses) {
                    if ($(element).hasClass(cls)) return true;
                }

                if ($(element).hasClass('btn-close')) return true;

                return false;
            }

            // Get current mode
            const mode = $('.file_status').val(); // 'view' or 'edit'
            const isView = (mode === 'view');

            // ---- Helper to apply or remove restrictions ----
            function applyRestrictions(enable) {
                // 1. Inputs, selects, textareas
                $('input, select, textarea').each(function () {
                    if (isExcluded(this)) return;

                    const type = $(this).attr('type');
                    const tag = this.tagName.toLowerCase();

                    if (type === 'checkbox' || type === 'radio') {
                        if (enable) {
                            $(this).addClass('readonly-check');
                            $(this).closest('.checkbox-group, label, td').addClass('readonly-check');
                        } else {
                            $(this).removeClass('readonly-check');
                            $(this).closest('.checkbox-group, label, td').removeClass('readonly-check');
                        }
                    }
                    else if (type === 'date') {
                        if (enable) {
                            $(this).prop('disabled', true);
                        } else {
                            $(this).prop('disabled', false);
                        }
                    }
                    else if (tag === 'select') {
                        if (enable) {
                            $(this).addClass('readonly-select');
                        } else {
                            $(this).removeClass('readonly-select');
                        }
                    }
                    else {
                        // text, number, email, etc.
                        if (enable) {
                            $(this).prop('readonly', true);
                        } else {
                            $(this).prop('readonly', false);
                        }
                    }
                });

                // 2. Buttons
                $('button, .btn').each(function () {
                    if (isExcluded(this)) return;
                    if (enable) {
                        $(this).prop('disabled', true).addClass('disabled');
                    } else {
                        $(this).prop('disabled', false).removeClass('disabled');
                    }
                });

                $('.edit-remove').each(function () {
                    if (enable) {
                        $(this).css('pointer-events', 'none').addClass('disabled-remove');
                    } else {
                        $(this).css('pointer-events', '').removeClass('disabled-remove');
                    }
                });
            }

            // Apply based on current mode
            applyRestrictions(isView);
        }

