        let saved_last_meal_quotation_date = localStorage.getItem('first_quotation_date');

        if (saved_last_meal_quotation_date === '' || new Date(saved_last_meal_quotation_date) >= new Date(cutoff_meal_sitescene)) {

            document.addEventListener('DOMContentLoaded', function() {      
                let savedMealDataGlobal = null;
                let hasUserMadeChanges = false;
                const urlParams = new URLSearchParams(window.location.search);
                const quotationId = urlParams.get('id');
                
                if (quotationId) {
                    const savedData = localStorage.getItem(`meal_type_${quotationId}`);
                    
                    if (savedData && savedData !== "null" && savedData !== "undefined") {
                        try {
                            const parsedData = JSON.parse(savedData);
                            
                            if (parsedData && 
                                (parsedData.cusine || parsedData.days || parsedData.meals)) {
                                
                                const yesCheckbox = document.getElementById('yesOption');
                                const noCheckbox = document.getElementById('noOption');
                                
                                if (yesCheckbox && noCheckbox) {
                                    yesCheckbox.checked = true;
                                    noCheckbox.checked = false;
                                    
                                    setTimeout(() => {
                                        loadSavedMealData(parsedData);
                                    }, 500);
                                }
                            }
                        } catch (e) {
                            console.error('Error parsing saved meal data:', e);
                        }
                    }
                }
            });

            function loadSavedMealData(savedMealData) {
                const mealTypeSelect = $('#mealType');
                const daySelectEl = document.getElementById('daySelect');
                // Normalize meals structure before using
                if (savedMealData.meals) {
                    savedMealData.meals = normalizeMealsStructure(savedMealData.meals);
                }

                savedMealDataGlobal = savedMealData;
                hasUserMadeChanges = false;

                // Set days first (if any)
                if (savedMealData.days) {
                    daySelectEl.value = savedMealData.days;
                    daySelectEl.dispatchEvent(new Event('change'));
                }

                // Set cuisine values and wait for meals to load
                if (savedMealData.cusine) {
                    let cusineArray = Array.isArray(savedMealData.cusine) 
                        ? savedMealData.cusine 
                        : (savedMealData.cusine ? [savedMealData.cusine] : []);
                    
                    // Store the values to be set after AJAX completes
                    mealTypeSelect.val(cusineArray);
                    
                    // Use a one-time event listener to apply meals after the AJAX success
                    $(document).one('mealsLoaded', function() {
                        setTimeout(() => {
                            applySavedMeals(savedMealData);
                        }, 200);
                    });
                    
                    mealTypeSelect.trigger('change');
                } else {
                    // No cuisine – apply meals directly
                    setTimeout(() => {
                        applySavedMeals(savedMealData);
                    }, 800);
                }
            }

            function normalizeMealsStructure(meals) {
                if (!meals) return meals;
                const normalized = {};
                for (const [dayKey, cuisines] of Object.entries(meals)) {
                    normalized[dayKey] = {};
                    for (const [cuisine, value] of Object.entries(cuisines)) {
                        // Case 1: value is an array (e.g., local: [{"31":"1"}])
                        if (Array.isArray(value)) {
                            const merged = {};
                            value.forEach(item => {
                                Object.assign(merged, item);
                            });
                            // Wrap with a default buffetKey "other"
                            normalized[dayKey][cuisine] = { other: merged };
                        }
                        // Case 2: value is an object but first level keys are mealIds (no buffetKey)
                        else if (typeof value === 'object' && value !== null) {
                            const firstKey = Object.keys(value)[0];
                            if (firstKey && !isNaN(parseInt(firstKey))) {
                                // e.g., { "31": "1" } → wrap with "other"
                                normalized[dayKey][cuisine] = { other: value };
                            } else {
                                // Already has buffetKey level (e.g., { "lunch": {"1":"1"} })
                                normalized[dayKey][cuisine] = value;
                            }
                        } else {
                            normalized[dayKey][cuisine] = value;
                        }
                    }
                }
                return normalized;
            }
        }else{
            
            document.addEventListener('DOMContentLoaded', function() {      
                let savedMealDataGlobal = null;
                let hasUserMadeChanges = false;
                const urlParams = new URLSearchParams(window.location.search);
                const quotationId = urlParams.get('id');
                
                if (quotationId) {
                    const savedData = localStorage.getItem(`meal_type_${quotationId}`);
                    
                    if (savedData && savedData !== "null" && savedData !== "undefined") {
                        try {
                            const parsedData = JSON.parse(savedData);
                            
                            if (parsedData && 
                                (parsedData.cusine || parsedData.days || parsedData.meals)) {
                                
                                const yesCheckbox = document.getElementById('yesOption');
                                const noCheckbox = document.getElementById('noOption');
                                
                                if (yesCheckbox && noCheckbox) {
                                    yesCheckbox.checked = true;
                                    noCheckbox.checked = false;
                                    
                                    setTimeout(() => {
                                        loadSavedMealData(parsedData);
                                    }, 500);
                                }
                            }
                        } catch (e) {
                            console.error('Error parsing saved meal data:', e);
                        }
                    }
                }
            });

            function loadSavedMealData(savedMealData) {
                const mealType = document.getElementById('mealType');
                const daySelect = document.getElementById('daySelect');

                if (!mealType || !daySelect) return;

                savedMealDataGlobal = savedMealData;
                hasUserMadeChanges = false;

                mealType.value = savedMealData.cusine;
                mealType.dispatchEvent(new Event('change'));

                setTimeout(() => {
                    daySelect.value = savedMealData.days;
                    daySelect.dispatchEvent(new Event('change'));
                }, 300);
                
                // Apply saved meals after a delay to ensure DOM is ready
                setTimeout(() => {
                    applySavedMeals(savedMealData);
                }, 800);
            }

        }
        
