        // Function to set markup value (prioritizes saved value)
        function setMarkupValue(defaultValue) {
            if(saved_land_markup !== null && saved_land_markup !== undefined && saved_land_markup !== "") {
                $("#markup_percentage").val(saved_land_markup);
                console.log("Using saved land markup:", saved_land_markup);
                return true;
            } else {
                $("#markup_percentage").val(defaultValue);
                console.log("Using default markup:", defaultValue);
                return false;
            }
        }
        function setHotelMarkupValue(defaultValue) {
            if(saved_hotel_markup !== null && saved_hotel_markup !== undefined && saved_hotel_markup !== "") {
                $("#hotel_markup_percentage").val(saved_hotel_markup);
                console.log("Using saved hotel markup:", saved_hotel_markup);
