        function handleMarkupSplit(isSplit) {
            if(isSplit) {
                $(".markup-label").text("Land Markup (%)");
                $(".hotel-markup").slideDown(1000);
                
                // Set land markup (saved value takes priority)
                if(saved_land_markup) {
