                // Set hotel markup (saved value takes priority)
                setHotelMarkupValue(15);
            } else {
                $(".markup-label").text("Markup (%)");
                $(".hotel-markup").slideUp(1000);
                
                // Set land markup (saved value takes priority)
                if(saved_land_markup) {
                    $("#markup_percentage").val(saved_land_markup);
                } else {
                    $("#markup_percentage").val(15); // Default for split=no
                }
            }
