        // ================= COMMON ERROR FUNCTION =================
        function showError(input, message) {
            let errorDiv = input.siblings('.custom-error');

            if (errorDiv.length === 0) {
                errorDiv = $('<div class="custom-error" style="color:red; font-size:12px; margin-top:5px;"></div>');
                input.after(errorDiv);
            }

            errorDiv.text(message);
            input.css('border', '1px solid red').focus();

            setTimeout(() => {
                errorDiv.remove();
                input.css('border', '');
            }, 3000);
        }

        // ================= VALIDATION FUNCTION =================
        function validateFlightDetails() {

            let isValid = true;
            let firstErrorInput = null;

            if ($('#fligt_details_yes').is(':checked')) {

                let origin = $("#flight_details_block #origin_city");
                let arrival = $("#flight-city-initial-arrival");
                let airline = $("#flight-city-initial-airline");
                let arrivalTime = $("#initial-airline-departure-time");

                // ✅ NEW (Departure fields)
                let departureCity = $("#flight_details_block .departure-city");
                let departureAirline = $("#flight_details_block input[name='departing_airline']");
                let departureTime = $("#flight_details_block input[name='departing_time']");

                if (!origin.val().trim()) {
                    showError(origin, "Please enter City of Origin");
                    if (!firstErrorInput) firstErrorInput = origin;
                    isValid = false;
                }

                if (!arrival.val().trim()) {
                    showError(arrival, "Please enter Arrival City");
                    if (!firstErrorInput) firstErrorInput = arrival;
                    isValid = false;
                }

                if (!airline.val().trim()) {
                    showError(airline, "Please enter Arrival Airline");
                    if (!firstErrorInput) firstErrorInput = airline;
                    isValid = false;
                }

                if (!arrivalTime.val().trim()) {
                    showError(arrivalTime, "Please select Arrival Time");
                    if (!firstErrorInput) firstErrorInput = arrivalTime;
                    isValid = false;
                }

                // ✅ DEPARTURE VALIDATION
                if (!departureCity.val().trim()) {
                    showError(departureCity, "Please enter Departure City");
                    if (!firstErrorInput) firstErrorInput = departureCity;
                    isValid = false;
                }

                if (!departureAirline.val().trim()) {
                    showError(departureAirline, "Please enter Departing Airline");
                    if (!firstErrorInput) firstErrorInput = departureAirline;
                    isValid = false;
                }

                if (!departureTime.val().trim()) {
                    showError(departureTime, "Please select Departing Time");
                    if (!firstErrorInput) firstErrorInput = departureTime;
                    isValid = false;
                }

            } else {

                let origin = $("#time_selection_block .origin_city");
                let arrival = $("#flight-city-initial-arrival_no");
                let arrivalTime = $("#arrival_time_selection");

                // ✅ NEW (Departure fields)
                let departureCity = $("#time_selection_block input[name='departure_city_no']");
                let departureTime = $("#departing_time_selection");

                if (!origin.val().trim()) {
                    showError(origin, "Please enter City of Origin");
                    if (!firstErrorInput) firstErrorInput = origin;
                    isValid = false;
                }

                if (!arrival.val().trim()) {
                    showError(arrival, "Please enter Arrival City");
                    if (!firstErrorInput) firstErrorInput = arrival;
                    isValid = false;
                }

                if (!arrivalTime.val()) {
                    showError(arrivalTime, "Please select Arrival Time");
                    if (!firstErrorInput) firstErrorInput = arrivalTime;
                    isValid = false;
                }

                // ✅ DEPARTURE VALIDATION (NO FLIGHT CASE)
                if (!departureCity.val().trim()) {
                    showError(departureCity, "Please enter Departure City");
                    if (!firstErrorInput) firstErrorInput = departureCity;
                    isValid = false;
                }

                if (!departureTime.val()) {
                    showError(departureTime, "Please select Departing Time");
                    if (!firstErrorInput) firstErrorInput = departureTime;
                    isValid = false;
                }
            }

            // ✅ Scroll to first error
            if (!isValid && firstErrorInput) {
                $('html, body').animate({
                    scrollTop: firstErrorInput.offset().top - 100
                }, 500);
            }

            return isValid;
        }

        // ================= TOGGLE FLIGHT DETAILS =================
        function toggleFlightDetails() {
            if ($('#fligt_details_yes').is(':checked')) {

                $('#time_selection_block').hide();
                $('#flight_details_block').show();

                $('.flight_arrival_div, .flight_departure_div').show();
                $('.time_arrival_div, .time_departure_div').hide();

                $('#initial_early_checkin, #initial_late_checkout')
                    .prop('disabled', true)
                    .prop('checked', false);

            } else {

                $('#time_selection_block').show();
                $('#flight_details_block').hide();

                $('.flight_arrival_div, .flight_departure_div').hide();
                $('.time_arrival_div, .time_departure_div').show();

                updateCheckboxStates(); // your existing function
            }

            updateSummary(); // your existing function
        }

        function validateDayWiseTransferData() {
            let isValid = true;
            let firstInvalidDay = null;
            let errorMessages = [];
            let countryname = getCountryFromEnquiry(qdata.enquiry_abbr);

            let $cityInputs = $(".qtn-city");
            if ($cityInputs.length < 2) return true;

            for (let idx = 1; idx < $cityInputs.length; idx++) {
                let $cityInput = $cityInputs.eq(idx);
                let $row = $cityInput.closest(".row.mt-2");
                let daySpan = $row.find("span.bold").first();
                let dayText = daySpan.text().trim();
                let dayMatch = dayText.match(/Day\s+(\d+)/i);
                if (!dayMatch) continue;
                let dayNum = parseInt(dayMatch[1]);

                let cityValue = $cityInput.val().trim();
                if (cityValue === "") {
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}: Please enter a city.`);
                    continue;
                }

                let isCityValid = $cityInput.attr('data-city-valid') !== 'false';
                if (!isCityValid) { 
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}: Please select a valid city from the list (do not type manually).`);
                    continue;
                }

                let currentCity = $cityInput.val().trim().toLowerCase();
                let prevCity = $cityInputs.eq(idx - 1).val().trim().toLowerCase();

                if (currentCity === prevCity) continue;

                let $routeChangeDiv = $row.find(".route-change");
                let $routeChangeRadio = $row.find('input[name^="route_change"]:checked');
                let routeChangeValue = $routeChangeRadio.val();

                if (!$routeChangeDiv.is(":visible")) {
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}: City changed, but Route Change options are not visible.`);
                    continue;
                }

                if (routeChangeValue === "yes") continue;

                // Transfer Mode validation
                let $transferDiv = $row.find(".qtn-transfer").closest(".col-md-2");
                let transferMode = $row.find(".qtn-transfer").val();

                if (!$transferDiv.is(":visible") || !transferMode || (transferMode !== "road" && transferMode !== "train")) {
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}: Please select Transfer Mode (Road or Train).`);
                    continue;
                }

                // ----- Common: Travelling with Guide (if visible) -----
                let $guideDiv = $row.find(".with-train");
                if ($guideDiv.is(":visible")) {
                    let $guideChecked = $guideDiv.find('input[type="radio"]:checked');
                    if ($guideChecked.length === 0) {
                        isValid = false;
                        if (!firstInvalidDay) firstInvalidDay = dayNum;
                        errorMessages.push(`Day ${dayNum}: Please select whether Travelling with Guide (Yes/No).`);
                    }
                }

                // ----- Train-specific validation -----
                if (transferMode === "train") {
                    let $trainRow = $row.nextAll(".local-train").first();  // ✅ fixed selector
                    let isTrainVisible = $trainRow.is(":visible");
                    let trainId = $trainRow.find(".train-id").val();
                    let ticketType = $trainRow.find(".ticket-type").val();

                    if (!isTrainVisible || !trainId || trainId.trim() === "") {
                        isValid = false;
                        if (!firstInvalidDay) firstInvalidDay = dayNum;
                        errorMessages.push(`Day ${dayNum}: Please select a Train.`);
                    }

                    if (!ticketType || ticketType.trim() === "") {
                        isValid = false;
                        if (!firstInvalidDay) firstInvalidDay = dayNum;
                        errorMessages.push(`Day ${dayNum}: Please select Ticket Type for the train.`);
                    }
                } 
                // ----- Road-specific validation (Overnight Type) -----
                // else if (transferMode === "road") {
                //     let $prevRow = $row.prevAll(".row.mt-2").not(".local-train").first();
                //     let prevOvernightType = $prevRow.find('.overnight-type input:checked').val();
                //     let isReturnTrip = (prevOvernightType && prevOvernightType !== '');

                //     let requireOvernight = false;
                //     if (countryname === 'uzbekistan') {
                //         requireOvernight = true;
                //     } else {
                //         requireOvernight = !isReturnTrip;
                //     }

                //     if (requireOvernight) {
                //         let $overnightDiv = $row.find(".overnight-type");
                //         let overnightType = $overnightDiv.find('input[type="radio"]:checked').val();

                //         if (!$overnightDiv.is(":visible") || !overnightType) {
                //             isValid = false;
                //             if (!firstInvalidDay) firstInvalidDay = dayNum;
                //             errorMessages.push(`Day ${dayNum}: Please select Vehicle Type (Overnight or Drop Off).`);
                //         }
                //     }
                // }

                else if (transferMode === "road") {

                    const normalizedCountry = String(
                        countryname || ""
                    ).trim().toLowerCase();

                    const $overnightDiv = $row.find(".overnight-type");

                    const $overnightRadio = $overnightDiv.find(
                        'input[type="radio"][value="overnight"]'
                    );

                    const $dropoffRadio = $overnightDiv.find(
                        'input[type="radio"][value="drop_off"]'
                    );

                    /*
                    * Current day city.
                    */
                    const currentCity = String(
                        $row.find(".qtn-city").val() || ""
                    ).trim().toLowerCase();

                    /*
                    * Flight details Yes/No dono cases se arrival city lo.
                    */
                    const arrivalCityWithFlight = String(
                        $("#flight-city-initial-arrival").val() || ""
                    ).trim();

                    const arrivalCityWithoutFlight = String(
                        $("#flight-city-initial-arrival_no").val() || ""
                    ).trim();

                    const arrivalCity = String(
                        arrivalCityWithFlight || arrivalCityWithoutFlight
                    ).trim().toLowerCase();

                    const sameAsArrivalCity =
                        currentCity !== "" &&
                        arrivalCity !== "" &&
                        currentCity === arrivalCity;

                    /*
                    * Georgia/Kazakhstan me same arrival city hone par:
                    *
                    * Drop Off sirf information ke liye show hota hai.
                    * Woh disabled aur unchecked hi rahega.
                    * Isliye Vehicle Type validation nahi lagani hai.
                    */
                    const isAutomaticDropoffCase =
                        (
                            normalizedCountry === "georgia" ||
                            normalizedCountry === "kazakhstan"
                        ) &&
                        sameAsArrivalCity &&
                        $dropoffRadio.length > 0 &&
                        $dropoffRadio.is(":disabled");

                    /*
                    * Automatic Drop Off case hai to validation skip.
                    */
                    if (!isAutomaticDropoffCase) {

                        const $prevRow = $row
                            .prevAll(".row.mt-2")
                            .not(".local-train")
                            .first();

                        const prevOvernightType = $prevRow
                            .find('.overnight-type input[type="radio"]:checked')
                            .val();

                        const isReturnTrip =
                            prevOvernightType !== undefined &&
                            prevOvernightType !== null &&
                            prevOvernightType !== "";

                        let requireOvernight = false;

                        if (normalizedCountry === "uzbekistan") {
                            requireOvernight = true;
                        } else {
                            requireOvernight = !isReturnTrip;
                        }

                        if (requireOvernight) {

                            const overnightType = $overnightDiv
                                .find('input[type="radio"]:checked')
                                .val();

                            if (
                                !$overnightDiv.is(":visible") ||
                                !overnightType
                            ) {
                                isValid = false;

                                if (!firstInvalidDay) {
                                    firstInvalidDay = dayNum;
                                }

                                errorMessages.push(
                                    `Day ${dayNum}: Please select Vehicle Type (Overnight or Drop Off).`
                                );
                            }
                        }
                    }
                }
            }
            
            // ----- Validate route-change sections (day_trip or route_change) -----
            $('.route-change-section:visible').each(function() {
                let $section = $(this);
                let dayIndex = $section.data('day');          // 0‑based
                let sectionIdx = $section.data('section');    // 0‑based
                let dayNum = dayIndex + 1;
                let fromCity = $section.find('.from-city').val().trim();
                let toCity = $section.find('.to-city').val().trim();
                let transferMode = $section.find('.transfer-mode').val();
                let travelWithGuide = $section.find('input[name$="[travelling_with_guide]"]:checked').val();
                let isDayTripYes = $(`input[name="day_trip${dayIndex}"]:checked`).val() === 'yes';
                let mainCity = $(`.qtn-city[data-dayindex="${dayNum}"]`).val().trim();

                // Mandatory fields for every section
                if (!fromCity) {
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}, Section ${sectionIdx+1}: From City is required.`);
                }
                if (!toCity) {
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}, Section ${sectionIdx+1}: To City is required.`);
                }
                if (!transferMode) {
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}, Section ${sectionIdx+1}: Transfer Mode is required.`);
                }
                if (!travelWithGuide) {
                    isValid = false;
                    if (!firstInvalidDay) firstInvalidDay = dayNum;
                    errorMessages.push(`Day ${dayNum}, Section ${sectionIdx+1}: Travelling with Guide selection is required.`);
                }

                // Round‑trip rule for day_trip = yes
                if (isDayTripYes) {
                    let $allSections = $(`.route-change-section[data-day="${dayIndex}"]:visible`);
                    let lastIndex = $allSections.length - 1;
                    if (sectionIdx == lastIndex) {
                        if (toCity.toLowerCase() !== mainCity.toLowerCase()) {
                            isValid = false;
                            if (!firstInvalidDay) firstInvalidDay = dayNum;
                            errorMessages.push(`Day ${dayNum}, Section ${sectionIdx+1}: For Day Trip, the last section's To City must be the same as the day's main city (${mainCity}).`);
                        }
                    }
                }

                // Train‑specific validation
                if (transferMode === 'train') {
                    let trainId = $section.find('.train-id').val();
                    let ticketType = $section.find('.ticket-type').val();
                    if (!trainId || trainId.trim() === '') {
                        isValid = false;
                        if (!firstInvalidDay) firstInvalidDay = dayNum;
                        errorMessages.push(`Day ${dayNum}, Section ${sectionIdx+1}: Please select a Train.`);
                    }
                    if (!ticketType || ticketType.trim() === '') {
                        isValid = false;
                        if (!firstInvalidDay) firstInvalidDay = dayNum;
                        errorMessages.push(`Day ${dayNum}, Section ${sectionIdx+1}: Please select Ticket Type for the train.`);
                    }
                }
            });

            if (!isValid) {
                Swal.fire({
                    title: "Validation Error",
                    html: errorMessages.join("<br>"),
                    icon: "error",
                    confirmButtonText: "OK"
                });

                if (firstInvalidDay !== null) {
                    let $targetRow = $(`.row.mt-2`).filter(function() {
                        return $(this).find("span.bold").first().text().includes(`Day ${firstInvalidDay}`);
                    }).first();
                }
            }

            return isValid;
        }
        
    function validateVehicleSelection() {
        // Check Suggested Vehicles (class .suggested_vehicle)
        let suggestedChecked = $('#suggessted_vehicles').find('.suggested_vehicle:checked').length > 0;
        // Check Alternate Vehicles (class .vehicles)
        let alternateChecked = $('#add_vehicles').find('.vehicles:checked').length > 0;

        if (!suggestedChecked && !alternateChecked) {
            Swal.fire({
                title: 'Validation Error',
                text: 'Please select at least one vehicle (Suggested or Alternate) before proceeding.',
                icon: 'error',
                confirmButtonText: 'OK'
            });
            return false;
        }

        // Optional: Validate that every selected vehicle has a quantity ≥ 1
        let allQuantitiesValid = true;
        $('#suggessted_vehicles .suggested_vehicle:checked, #add_vehicles .vehicles:checked').each(function() {
            let $qtyInput = $(this).closest('.row').find('input[name="vehicle_quantity[]"]');
            let qty = $qtyInput.val();
            if (!qty || parseInt(qty) < 1) {
                allQuantitiesValid = false;
                return false; // break loop
            }
        });

        if (!allQuantitiesValid) {
            Swal.fire({
                title: 'Validation Error',
                text: 'Vehicle quantity must be at least 1 for all selected vehicles.',
                icon: 'error',
                confirmButtonText: 'OK'
            });
            return false;
        }

        return true;
    }
        
