                                                        html += '<div class="row mt-2" style="border-bottom:2px solid #000;">';
                                                        html += '<div class="col-md-12 row prices-div-'+categoryRooms[0].id+r_num+'" id="prices-div_'+categoryRooms[0].id+r_num+'">';
                                                        html += '<div class="col-md-4 div-category"><label class="bold"><input type="checkbox" class="'+class_chk+'" id="chk_'+categoryRooms[0].id+'_'+hotel_id+'" value="'+categoryRooms[0].id+'_'+categoryName+'" name="night_'+j+'_category_ids_'+hotel_id+'[]"> '+categoryName+'</label></div>';
                                                        html += '<div class="col-md-6 mb-1"><div class="row">';
                                                        
                                                        var persons_arr = [];
