                                                        $.each(categoryRooms, function(i, val) {
                                                            var price_with_breakfast = val.price_with_breakfast || '0';
                                                            
                                                            if(val.person_count && price_with_breakfast > 0) {
                                                                var person_text = val.person_count + '(A)';
                                                                persons_arr.push(person_text);
                                                                
                                                                is_chk = '';
