                                                                html += '<input type="checkbox" class="chk-prices" data-person="'+person_text+'" data-id="'+val.id+'_'+hotel_id+'" value="'+person_text+' '+price_with_breakfast+'" name="night_'+j+'_'+val.id+'_'+hotel_id+'_hotel_prices[0][]" '+is_chk+'>';
                                                                html += ' <span>'+person_text+'</span>';
                                                                html += '<input type="textbox" style="width:100%;" class="chk-prices-input" name="'+val.id+'_'+hotel_id+'_hotel_prices_input[][]" value="'+price_with_breakfast+'">';
                                                                html += '</div>';
                                                            }
                                                        });
                                                        
                                                        // Free breakfast as selectable option (like child)
