                                                            html += ' <span>'+child_text+'</span>';
                                                            html += '<input type="textbox" style="width:100%;" class="chk-prices-input" name="'+categoryRooms[0].id+'_'+hotel_id+'_hotel_prices_input[][]" value="'+categoryRooms[0].chid3_price+'">';
                                                            html += '<small style="display:block; text-align:center; font-size:10px;">'+categoryRooms[0].child_type3+' | Age: '+categoryRooms[0].child3_age_from+'-'+categoryRooms[0].child3_age_to+'</small>';
                                                            html += '</div>';
                                                        }
                                                        
                                                        // Child 4
                                                        if(categoryRooms[0].child_type4 && categoryRooms[0].child_type4 !== "" && categoryRooms[0].chid4_price && categoryRooms[0].chid4_price > 0) {
