                                                            var child_text ='1(C)';
                                                            persons_arr.push(child_text);
                                                            
                                                            html += '<div class="col-md-3 p-1">';
                                                            html += '<input type="checkbox" class="chk-prices chk-child-prices" data-person="'+child_text+'" data-id="'+categoryRooms[0].id+'_'+hotel_id+'" value="'+child_text+' '+categoryRooms[0].chid4_price+' '+categoryRooms[0].child_type4+'" name="night_'+j+'_'+categoryRooms[0].id+'_'+hotel_id+'_hotel_prices[0][]">';
                                                            html += ' <span>'+child_text+'</span>';
                                                            html += '<input type="textbox" style="width:100%;" class="chk-prices-input" name="'+categoryRooms[0].id+'_'+hotel_id+'_hotel_prices_input[][]" value="'+categoryRooms[0].chid4_price+'">';
                                                            html += '<small style="display:block; text-align:center; font-size:10px;">'+categoryRooms[0].child_type4+' | Age: '+categoryRooms[0].child4_age_from+'-'+categoryRooms[0].child4_age_to+'</small>';
                                                            html += '</div>';
                                                        }
                                                        
                                                        html += '</div></div>'; // Close pricing div
                                                        
                                                        // Rooms count - maintain same structure as original
                                                        html += '<div class="col-md-2" style="display:flex; align-items: center;">';
                                                        html += '<input type="number" min="1" class="ss rooms-cnt rooms_cnt_'+categoryRooms[0].id+r_num+'" style="width:65%;height: 27px;" value="1" name="'+categoryRooms[0].id+'_room_cnt[]">';
                                                        html += '<span class="span_btn" style="margin-left:3px;">';
                                                        html += '<button type="button" data-id="'+categoryRooms[0].id+r_num+'" style="background-color: #0a87f5;color: #FFF;height:25px;cursor:pointer;float:right;padding: 0px 5px;" class="add btn-primary">+</button>';
                                                        html += '</span>';
                                                        html += '</div>';
                                                        
                                                        // Hidden field with all persons - same as original
                                                        html += '<input type="hidden" class="chk-prices-all-night-'+j+'" value="'+persons_arr.join(",")+'" data-chkid="'+categoryRooms[0].id+'_'+hotel_id+'">';
                                                        html += '</div></div>'; // Close main row
                                                    });
                                                    
                                                    $("#"+div_to_append_id).append(html);
                                                } else { 
                                                    // Handle no results
                                                } 
                                            } 
                                        }
                                    });
                                ajaxPromises.push(ajaxPromise);
                            });
                        }
                    });   
                    k++;
                }
            
            var rdo_guide = $("#quotation-make-1 input[name='guide']:checked").val();
            var rdo_airport_pick_drop = $("#quotation-make-1 input[name='airport_pick_drop']:checked").val();
            var class_arr = [".guides", ".guides-shift", ".guides-prices", ".guides-add", ".hdn-guides"];
            $("#show-guides input, #show-guides select, #show-guides button").prop("disabled", false);
            if(rdo_guide==="no"){
                $("#show-guides input, #show-guides select, #show-guides button").prop("disabled", true);
            }else if($("#quotation-make-1 #div_driver_cum_guide").css("display") !== "none" && $("input[name='driver_cum_guide']:checked").val() === "driver_guide") {
                $("#show-guides input, #show-guides select, #show-guides button").prop("disabled", true);
                $.each(class_arr, function(index, value) {
                    $(value).eq(0).prop("disabled", false);
                });
            }
    
            // Wait for all AJAX calls to complete before processing occupancy
            $.when.apply($, ajaxPromises).then(function() {
                    // Small delay to ensure DOM is fully updated
                    setTimeout(function() {
                        processOccupancyAutoSelection(div_ids_arr);
                    }, 100);
                });
        });

        function processOccupancyAutoSelection(div_ids_arr) {
            // Process each hotel category container independently
            $.each(div_ids_arr, function(index, id) {
                console.log("Processing container:", id);
        
                // Get expected room occupancies from family details WITH CHILD AGES
                var rooms_arr = [];
                var rooms_with_ages = []; // Store room data with ages for matching
                
                $("input[name='family_adults[]']").each(function (index, obj) {
                    $("input[name='family_" + (index + 1) + "_adults[]']").each(function (idx, ob) {
                        var room_adults = $(this).val();
                        var room_child = $("input[name='family_" + (index + 1) + "_child[]']").eq(idx).val();
                        var room_persons = room_adults + "(A)";
                        
                        var roomData = {
                            adults: room_adults,
                            children: room_child,
                            childAges: [],
                            originalIndex: idx
                        };
                        
                        if (room_child != "" && room_child != "0") {
                            // Get child ages for this specific room
                            var childAges = [];
                            var room_cnt = $("input[name='family_" + (index + 1) + "_child[]']").eq(idx).attr('data-room-cnt');
                            var childAgeSelects = $("select[name='family_" + (index + 1) + "_room_" + room_cnt + "_child_age[]']");
                            
                            childAgeSelects.each(function() {
                                var age = $(this).val();
                                if (age) {
                                    childAges.push(parseInt(age));
                                    roomData.childAges.push(parseInt(age));
                                }
                            });
                            
                            room_persons = room_persons + "," + room_child + "(C)";
                            
                            // Add child ages to the occupancy string if available
                            if (childAges.length > 0) {
                                room_persons = room_persons + "[" + childAges.join(",") + "]";
                            }
                        }
                        rooms_arr.push(room_persons);
                        rooms_with_ages.push(roomData);
                    });
                });
                rooms_arr.sort();
        
                console.log("Expected Rooms Array with Child Ages:", rooms_arr);
                console.log("Room Data with Ages:", rooms_with_ages);
                
                // Count occurrences of each occupancy type
                let occupancyCounts = {};
                rooms_arr.forEach(val => {
                    occupancyCounts[val] = (occupancyCounts[val] || 0) + 1;
                });
                
                console.log("Occupancy Counts:", occupancyCounts);
                
                // Reset all checkboxes first for this container
                $("#" + id + " .row.mt-2").each(function() {
                    var $roomRow = $(this);
                    $roomRow.find('.chk-prices').prop('checked', false);
                    $roomRow.find('input[type="checkbox"][class^="chk_"]').prop('checked', false);
                    $roomRow.find('input.rooms-cnt').val(1);
                });
        
                // Process each night separately within this container
                for (let night = 1; night <= qdata.nights; night++) {
                    console.log("=== PROCESSING NIGHT", night, "in container:", id, "===");
                    
                    // Track assigned occupancy types for this night ONLY
                    var nightAssignedOccupancies = [];
                    // Track which specific rooms have been assigned for this night
                    var nightAssignedRoomIds = [];
                    
                    // PHASE 1: Try to assign each occupancy type to existing rooms for this night
                    Object.keys(occupancyCounts).forEach((occupancy, occupancyIndex) => {
                        // SKIP if occupancy is already assigned for this night
                        if (nightAssignedOccupancies.includes(occupancy)) {
                            console.log("SKIPPING - Occupancy already assigned for night", night, ":", occupancy);
                            return;
                        }
                        
                        var countNeeded = occupancyCounts[occupancy];
                        console.log("NIGHT", night, "- PHASE 1 - Processing occupancy:", occupancy, "count needed:", countNeeded);
                        
                        // Get child ages for this specific occupancy
                        var roomData = rooms_with_ages.find((room, idx) => {
                            var roomStr = room.adults + "(A)";
                            if (room.children && room.children != "0") {
                                roomStr += "," + room.children + "(C)";
                                if (room.childAges.length > 0) {
                                    roomStr += "[" + room.childAges.join(",") + "]";
                                }
                            }
                            return roomStr === occupancy;
                        });
                        
                        var childAges = roomData ? roomData.childAges : [];
                        console.log("NIGHT", night, "- Child ages for occupancy", occupancy, ":", childAges);
                        
                        var occupancyParts = splitOccupancyType(occupancy);
                        
                        var bestRoomOption = null;
                        var bestTotalPrice = Infinity;
                        var bestOccupancyOptions = [];
                        var bestRoomId = null;
                        
                        // Look for rooms that can accommodate this occupancy type for CURRENT NIGHT
                        $("#" + id + " .row.mt-2").each(function() {
                            var $roomRow = $(this);
                            
                            // Check if this room belongs to the current night
                            var roomNight = getRoomNight($roomRow);
                            if (roomNight !== night) return; // Skip rooms from other nights
                            
                            // Get unique identifier for this room
                            var roomId = getRoomUniqueId($roomRow);
                            
                            // Skip rooms that already have assigned occupancies OR have been assigned any occupancy for this night
                            var hasExistingAssignment = $roomRow.find('.chk-prices:checked').length > 0;
                            var isRoomAlreadyAssigned = nightAssignedRoomIds.includes(roomId);
                            
                            if (hasExistingAssignment || isRoomAlreadyAssigned) return;
                            
                            var $roomCheckbox = $roomRow.find('input[type="checkbox"][class^="chk_"]');
                            
                            // Check if this room has ALL required occupancy parts WITH AGE MATCHING
                            var hasAllOccupancies = true;
                            var totalPrice = 0;
                            var foundOptions = [];
                            
                            for (var i = 0; i < occupancyParts.length; i++) {
                                var occupancyPart = occupancyParts[i];
                                var foundOption = null;
                                var minPriceForPart = Infinity;
                                
                                // Find the minimum price option for this occupancy part WITH AGE MATCHING
                                $roomRow.find('.chk-prices').each(function() {
                                    var $checkbox = $(this);
                                    var personType = $checkbox.data('person');
                                    var priceText = $checkbox.val();
                                    var priceValue = parseFloat(priceText.split(" ")[1].replace(/[^\d.]/g, '')) || 0;
                                    
                                    // Check if this checkbox matches the occupancy part
                                    if (personType === occupancyPart) {
                                        // If it's a child occupancy, check age matching
                                        if (personType.includes('(C)') && childAges.length > 0) {
                                            console.log("NIGHT", night, "- Checking child age matching for", personType, "with ages:", childAges);
                                            
                                            // Get child age policy from the checkbox (from the small text)
                                            var $smallText = $checkbox.closest('.p-1').find('small');
                                            if ($smallText.length > 0) {
                                                var smallText = $smallText.text();
                                                console.log("NIGHT", night, "- Child policy text:", smallText);
                                                
                                                var ageMatch = smallText.match(/Age:\s*(\d+)-(\d+)/);
                                                
                                                if (ageMatch) {
                                                    var minAge = parseInt(ageMatch[1]);
                                                    var maxAge = parseInt(ageMatch[2]);
                                                    console.log("NIGHT", night, "- Age range found:", minAge, "-", maxAge);
                                                    
                                                    // Check if ANY child age falls within this range
                                                    var hasMatchingAge = childAges.some(age => age >= minAge && age <= maxAge);
                                                    
                                                    if (hasMatchingAge) {
                                                        console.log("NIGHT", night, "- ✓ Age match found for child age:", childAges);
                                                        if (priceValue < minPriceForPart) {
                                                            minPriceForPart = priceValue;
                                                            foundOption = $checkbox;
                                                        }
                                                    } else {
                                                        console.log("NIGHT", night, "- ✗ No age match for child ages:", childAges, "in range:", minAge, "-", maxAge);
                                                    }
                                                } else {
                                                    // If no age range specified, check for free breakfast or other child types
                                                    var freeBreakfastMatch = smallText.match(/Free\s*\|\s*Age:\s*(\d+)/);
                                                    if (freeBreakfastMatch) {
                                                        var freeAge = parseInt(freeBreakfastMatch[1]);
                                                        var hasMatchingAge = childAges.some(age => age <= freeAge);
                                                        
                                                        if (hasMatchingAge) {
                                                            console.log("NIGHT", night, "- ✓ Free breakfast age match for child age:", childAges);
                                                            if (priceValue < minPriceForPart) {
                                                                minPriceForPart = priceValue;
                                                                foundOption = $checkbox;
                                                            }
                                                        }
                                                    } else {
                                                        // If no age info available, use it as fallback
                                                        console.log("NIGHT", night, "- No age range specified, using as fallback");
                                                        if (priceValue < minPriceForPart) {
                                                            minPriceForPart = priceValue;
                                                            foundOption = $checkbox;
                                                        }
                                                    }
                                                }
                                            } else {
                                                // If no age info available, use it as fallback
                                                console.log("NIGHT", night, "- No age info available, using as fallback");
                                                if (priceValue < minPriceForPart) {
                                                    minPriceForPart = priceValue;
                                                    foundOption = $checkbox;
                                                }
                                            }
                                        } else {
                                            // For adults or when no child ages, just check price
                                            if (priceValue < minPriceForPart) {
                                                minPriceForPart = priceValue;
                                                foundOption = $checkbox;
                                            }
                                        }
                                    }
                                });
                                
                                if (foundOption) {
                                    totalPrice += minPriceForPart;
                                    foundOptions.push(foundOption);
                                    console.log("NIGHT", night, "- Found option for", occupancyPart, "with price:", minPriceForPart);
                                } else {
                                    console.log("NIGHT", night, "- No option found for", occupancyPart);
                                    hasAllOccupancies = false;
                                    break;
                                }
                            }
                            
                            // If this room has all required occupancies and has lower total price
                            if (hasAllOccupancies && totalPrice < bestTotalPrice) {
                                bestTotalPrice = totalPrice;
                                bestRoomOption = $roomRow;
                                bestOccupancyOptions = foundOptions;
                                bestRoomId = roomId;
                            }
                        });
                        
                        // If found, assign to this room for this night
                        if (bestRoomOption && bestOccupancyOptions.length > 0) {
                            console.log("✓ NIGHT", night, "- Assigned occupancy", occupancy, "to room", bestRoomId, "with price:", bestTotalPrice, "in container:", id);
                            
                            var $roomCheckbox = bestRoomOption.find('input[type="checkbox"][class^="chk_"]');
                            var $roomCountInput = bestRoomOption.find('input.rooms-cnt');
                            
                            // Check ALL occupancy parts and main room checkbox
                            bestOccupancyOptions.forEach(function(option) {
                                option.prop('checked', true);
                            });
                            $roomCheckbox.prop('checked', true);
                            
                            // Set room count
                            $roomCountInput.val(countNeeded);
                            
                            nightAssignedOccupancies.push(occupancy);
                            nightAssignedRoomIds.push(bestRoomId); // Mark this specific room as assigned for this night
                            
                            // NEW LOGIC: If first occupancy assigned, immediately process remaining in same category for this night
                            if (nightAssignedOccupancies.length === 1) {
                                console.log("NIGHT", night, "- First occupancy assigned, processing remaining occupancies in same category...");
                                
                                var assignedCategory = bestRoomOption.find(".div-category label").text().trim();
                                console.log("NIGHT", night, "- Assigned category:", assignedCategory);
                                
                                // Process remaining unassigned occupancies for THIS NIGHT
                                var remainingOccupancies = Object.keys(occupancyCounts).filter(occ => 
                                    !nightAssignedOccupancies.includes(occ)
                                );
                                
                                remainingOccupancies.forEach(function(remainingOccupancy, remIndex) {
                                    // DOUBLE CHECK: Skip if already assigned for this night (safety check)
                                    if (nightAssignedOccupancies.includes(remainingOccupancy)) {
                                        console.log("NIGHT", night, "- SKIPPING - Remaining occupancy already assigned:", remainingOccupancy);
                                        return;
                                    }
                                    
                                    var remainingCount = occupancyCounts[remainingOccupancy];
                                    
                                    // Get child ages for remaining occupancy
                                    var remainingRoomData = rooms_with_ages.find((room, idx) => {
                                        var roomStr = room.adults + "(A)";
                                        if (room.children && room.children != "0") {
                                            roomStr += "," + room.children + "(C)";
                                            if (room.childAges.length > 0) {
                                                roomStr += "[" + room.childAges.join(",") + "]";
                                            }
                                        }
                                        return roomStr === remainingOccupancy;
                                    });
                                    
                                    var remainingChildAges = remainingRoomData ? remainingRoomData.childAges : [];
                                    var remainingParts = splitOccupancyType(remainingOccupancy);
                                    
                                    console.log("NIGHT", night, "- Processing remaining occupancy in same category:", remainingOccupancy, "with child ages:", remainingChildAges, "in container:", id);
                                    
                                    // Check if this occupancy can be accommodated in the same category for this night WITH AGE MATCHING
                                    var canAccommodateInSameCategory = true;
                                    var sameCategoryTotalPrice = 0;
                                    var sameCategoryOptions = [];
                                    
                                    for (var i = 0; i < remainingParts.length; i++) {
                                        var occupancyPart = remainingParts[i];
                                        var foundOption = null;
                                        var minPriceForPart = Infinity;
                                        
                                        bestRoomOption.find('.chk-prices').each(function() {
                                            var $checkbox = $(this);
                                            var personType = $checkbox.data('person');
                                            var priceText = $checkbox.val();
                                            var priceValue = parseFloat(priceText.split(" ")[1].replace(/[^\d.]/g, '')) || 0;
                                            
                                            if (personType === occupancyPart) {
                                                // If it's a child occupancy, check age matching
                                                if (personType.includes('(C)') && remainingChildAges.length > 0) {
                                                    var $smallText = $checkbox.closest('.p-1').find('small');
                                                    if ($smallText.length > 0) {
                                                        var smallText = $smallText.text();
                                                        var ageMatch = smallText.match(/Age:\s*(\d+)-(\d+)/);
                                                        
                                                        if (ageMatch) {
                                                            var minAge = parseInt(ageMatch[1]);
                                                            var maxAge = parseInt(ageMatch[2]);
                                                            
                                                            var hasMatchingAge = remainingChildAges.some(age => age >= minAge && age <= maxAge);
                                                            
                                                            if (hasMatchingAge && priceValue < minPriceForPart) {
                                                                minPriceForPart = priceValue;
                                                                foundOption = $checkbox;
                                                            }
                                                        } else {
                                                            // Check for free breakfast
                                                            var freeBreakfastMatch = smallText.match(/Free\s*\|\s*Age:\s*(\d+)/);
                                                            if (freeBreakfastMatch) {
                                                                var freeAge = parseInt(freeBreakfastMatch[1]);
                                                                var hasMatchingAge = remainingChildAges.some(age => age <= freeAge);
                                                                
                                                                if (hasMatchingAge && priceValue < minPriceForPart) {
                                                                    minPriceForPart = priceValue;
                                                                    foundOption = $checkbox;
                                                                }
                                                            } else {
                                                                if (priceValue < minPriceForPart) {
                                                                    minPriceForPart = priceValue;
                                                                    foundOption = $checkbox;
                                                                }
                                                            }
                                                        }
                                                    } else {
                                                        if (priceValue < minPriceForPart) {
                                                            minPriceForPart = priceValue;
                                                            foundOption = $checkbox;
                                                        }
                                                    }
                                                } else {
                                                    if (priceValue < minPriceForPart) {
                                                        minPriceForPart = priceValue;
                                                        foundOption = $checkbox;
                                                    }
                                                }
                                            }
                                        });
                                        
                                        if (foundOption) {
                                            sameCategoryTotalPrice += minPriceForPart;
                                            sameCategoryOptions.push(foundOption);
                                        } else {
                                            canAccommodateInSameCategory = false;
                                            break;
                                        }
                                    }
                                    
                                    if (canAccommodateInSameCategory) {
                                        console.log("✓ NIGHT", night, "- Same category can accommodate", remainingOccupancy, "with price:", sameCategoryTotalPrice, "in container:", id);
                                        
                                        // Clone the row for this occupancy for this night - FOLLOWING THE + BUTTON PATTERN
                                        var $clonedRow = bestRoomOption.clone(true, true);
                                        
                                        // Generate unique ID following the pattern
                                        var randomId = Math.floor(Math.random() * 1000000);
                                        var newId = 'prices-div_' + randomId;
                                        $clonedRow.attr('id', newId);
                                        $clonedRow.find('.prices-div').attr('id', newId);
                                        
                                        // Clear the category label (following cloned row pattern)
                                        $clonedRow.find('.div-category').html('');
                                        
                                        // Reset all checkboxes in cloned row
                                        $clonedRow.find('.chk-prices').prop('checked', false);
                                        $clonedRow.find('input[type="checkbox"][class^="chk_"]').prop('checked', false);
                                        
                                        // Check only the specific occupancy parts that were found
                                        sameCategoryOptions.forEach(function(option) {
                                            var optionPersonType = option.data('person');
                                            var optionValue = option.val();
                                            
                                            // Find and check the matching checkbox in cloned row
                                            $clonedRow.find('.chk-prices').each(function() {
                                                var $clonedCheckbox = $(this);
                                                if ($clonedCheckbox.data('person') === optionPersonType && 
                                                    $clonedCheckbox.val() === optionValue) {
                                                    $clonedCheckbox.prop('checked', true);
                                                }
                                            });
                                        });
                                        
                                        // Check the main room checkbox
                                        $clonedRow.find('input[type="checkbox"][class^="chk_"]').prop('checked', true);
                                        
                                        // Set room count
                                        $clonedRow.find('input.rooms-cnt').val(remainingCount);
                                        
                                        // Replace add button with remove button (following cloned row pattern)
                                        $clonedRow.find(".span_btn").html('<i title="Remove" class="bi bi-x-lg div_remove" style="color:red;cursor: pointer;padding:6px 4px;"></i>');
                                        
                                        // Update night-specific attributes with proper indexing
                                        preserveNightAttributes($clonedRow, night, true); // true = isCloned
                                        
                                        // Generate unique ID for the cloned room and mark it as assigned for this night
                                        var clonedRoomId = 'cloned_night_' + night + '_' + newId;
                                        nightAssignedRoomIds.push(clonedRoomId);
                                        
                                        // Insert after the original row
                                        bestRoomOption.after($clonedRow);
                                        
                                        // MARK THE OCCUPANCY AS ASSIGNED FOR THIS NIGHT
                                        nightAssignedOccupancies.push(remainingOccupancy);
                                        console.log("✓ NIGHT", night, "- Created cloned row in same category for occupancy:", remainingOccupancy, "in container:", id);
                                    } else {
                                        console.log("NIGHT", night, "- Same category cannot accommodate", remainingOccupancy, "- will be processed in phase 2");
                                    }
                                });
                                
                                // BREAK OUT OF THE LOOP after processing remaining occupancies for this night
                                console.log("NIGHT", night, "- All occupancies processed in first assignment. Breaking out of occupancy loop.");
                                return false; // This breaks the Object.keys(occupancyCounts).forEach loop for this night
                            }
                        } else {
                            console.log("NIGHT", night, "- No suitable room found for occupancy:", occupancy);
                        }
                    });
        
                    // PHASE 2: Handle unassigned occupancy types for this night WITH AGE MATCHING
                    var unassignedOccupanciesForNight = Object.keys(occupancyCounts).filter(occupancy => 
                        !nightAssignedOccupancies.includes(occupancy)
                    );
        
                    console.log("NIGHT", night, "- PHASE 2 - Unassigned occupancies:", unassignedOccupanciesForNight);
                    console.log("NIGHT", night, "- Assigned room IDs:", nightAssignedRoomIds);
        
                    if (unassignedOccupanciesForNight.length > 0) {
                        // Find the best available room (minimum price) to use as template for THIS NIGHT - only from unassigned rooms for this night
                        var $bestTemplateRow = null;
                        var bestTemplatePrice = Infinity;
                        
                        $("#" + id + " .row.mt-2").each(function() {
                            var $roomRow = $(this);
                            
                            // Check if this room belongs to the current night
                            var roomNight = getRoomNight($roomRow);
                            if (roomNight !== night) return; // Skip rooms from other nights
                            
                            var roomId = getRoomUniqueId($roomRow);
                            
                            // Skip already assigned rooms for this night
                            if (nightAssignedRoomIds.includes(roomId)) return;
                            
                            var $firstPriceCheckbox = $roomRow.find('.chk-prices').first();
                            if ($firstPriceCheckbox.length > 0) {
                                var priceText = $firstPriceCheckbox.val();
                                var priceValue = parseFloat(priceText.split(" ")[1].replace(/[^\d.]/g, '')) || 0;
                                
                                if (priceValue < bestTemplatePrice) {
                                    bestTemplatePrice = priceValue;
                                    $bestTemplateRow = $roomRow;
                                }
                            }
                        });
                        
                        if (!$bestTemplateRow) {
                            // If no unassigned rooms found for this night, use the first available room for this night
                            $("#" + id + " .row.mt-2").each(function() {
                                var $roomRow = $(this);
                                var roomNight = getRoomNight($roomRow);
                                if (roomNight !== night) return; // Skip rooms from other nights
                                
                                var roomId = getRoomUniqueId($roomRow);
                                if (!nightAssignedRoomIds.includes(roomId)) {
                                    $bestTemplateRow = $roomRow;
                                    return false; // break loop
                                }
                            });
                        }
                        
                        if (!$bestTemplateRow) {
                            console.log("NIGHT", night, "- No available template room found for cloning");
                            continue; // Move to next night
                        }
                        
                        unassignedOccupanciesForNight.forEach(function(occupancy) {
                            var countNeeded = occupancyCounts[occupancy];
                            
                            // Get child ages for this occupancy
                            var roomData = rooms_with_ages.find((room, idx) => {
                                var roomStr = room.adults + "(A)";
                                if (room.children && room.children != "0") {
                                    roomStr += "," + room.children + "(C)";
                                    if (room.childAges.length > 0) {
                                        roomStr += "[" + room.childAges.join(",") + "]";
                                    }
                                }
                                return roomStr === occupancy;
                            });
                            
                            var childAges = roomData ? roomData.childAges : [];
                            var occupancyParts = splitOccupancyType(occupancy);
                            
                            console.log("NIGHT", night, "- Creating row for unassigned occupancy:", occupancy, "with child ages:", childAges, "using minimum price template");
                            
                            // Create a cloned row - FOLLOWING THE + BUTTON PATTERN
                            var $newRow = $bestTemplateRow.clone(true, true);
                            
                            // Generate unique ID following the pattern
                            var randomId = Math.floor(Math.random() * 1000000);
                            var newId = 'prices-div_' + randomId;
                            $newRow.attr('id', newId);
                            $newRow.find('.prices-div').attr('id', newId);
                            
                            // Clear the category label (following cloned row pattern)
                            $newRow.find('.div-category').html('');
                            
                            // Reset all checkboxes
                            $newRow.find('.chk-prices').prop('checked', false);
                            $newRow.find('input[type="checkbox"][class^="chk_"]').prop('checked', false);
                            
                            // Check the specific occupancy parts WITH AGE MATCHING
                            occupancyParts.forEach(function(occupancyPart) {
                                var foundOption = null;
                                var minPriceForPart = Infinity;
                                
                                $newRow.find('.chk-prices').each(function() {
                                    var $checkbox = $(this);
                                    var personType = $checkbox.data('person');
                                    var priceText = $checkbox.val();
                                    var priceValue = parseFloat(priceText.split(" ")[1].replace(/[^\d.]/g, '')) || 0;
                                    
                                    if (personType === occupancyPart) {
                                        // If it's a child occupancy, check age matching
                                        if (personType.includes('(C)') && childAges.length > 0) {
                                            var $smallText = $checkbox.closest('.p-1').find('small');
                                            if ($smallText.length > 0) {
                                                var smallText = $smallText.text();
                                                var ageMatch = smallText.match(/Age:\s*(\d+)-(\d+)/);
                                                
                                                if (ageMatch) {
                                                    var minAge = parseInt(ageMatch[1]);
                                                    var maxAge = parseInt(ageMatch[2]);
                                                    
                                                    var hasMatchingAge = childAges.some(age => age >= minAge && age <= maxAge);
                                                    
                                                    if (hasMatchingAge && priceValue < minPriceForPart) {
                                                        minPriceForPart = priceValue;
                                                        foundOption = $checkbox;
                                                    }
                                                } else {
                                                    // Check for free breakfast
                                                    var freeBreakfastMatch = smallText.match(/Free\s*\|\s*Age:\s*(\d+)/);
                                                    if (freeBreakfastMatch) {
                                                        var freeAge = parseInt(freeBreakfastMatch[1]);
                                                        var hasMatchingAge = childAges.some(age => age <= freeAge);
                                                        
                                                        if (hasMatchingAge && priceValue < minPriceForPart) {
                                                            minPriceForPart = priceValue;
                                                            foundOption = $checkbox;
                                                        }
                                                    } else {
                                                        if (priceValue < minPriceForPart) {
                                                            minPriceForPart = priceValue;
                                                            foundOption = $checkbox;
                                                        }
                                                    }
                                                }
                                            } else {
                                                if (priceValue < minPriceForPart) {
                                                    minPriceForPart = priceValue;
                                                    foundOption = $checkbox;
                                                }
                                            }
                                        } else {
                                            // For adults or when no child ages, just check price
                                            if (priceValue < minPriceForPart) {
                                                minPriceForPart = priceValue;
                                                foundOption = $checkbox;
                                            }
                                        }
                                    }
                                });
                                
                                if (foundOption) {
                                    foundOption.prop('checked', true);
                                }
                            });
                            
                            // Check the main room checkbox
                            $newRow.find('input[type="checkbox"][class^="chk_"]').prop('checked', true);
                            
                            // Set room count
                            $newRow.find('input.rooms-cnt').val(countNeeded);
                            
                            // Replace add button with remove button (following cloned row pattern)
                            $newRow.find(".span_btn").html('<i title="Remove" class="bi bi-x-lg div_remove" style="color:red;cursor: pointer;padding:6px 4px;"></i>');
                            
                            // Update night-specific attributes with proper indexing
                            preserveNightAttributes($newRow, night, true); // true = isCloned
                            
                            // Generate unique ID for the new room and mark it as assigned for this night
                            var newRoomId = 'new_night_' + night + '_' + newId;
                            nightAssignedRoomIds.push(newRoomId);
                            
                            // Insert at the end of the container
                            $("#" + id).append($newRow);
                            
                            nightAssignedOccupancies.push(occupancy);
                            
                            console.log("✓ NIGHT", night, "- Created row for occupancy:", occupancy, "with count:", countNeeded, "in container:", id);
                        });
                    }
                    
                    console.log("=== NIGHT", night, "COMPLETED in container:", id, "===");
                    console.log("NIGHT", night, "- Assigned occupancies:", nightAssignedOccupancies);
                    console.log("NIGHT", night, "- Assigned room IDs:", nightAssignedRoomIds);
                }
        
                // Final verification for this container (all nights combined)
                console.log("=== FINAL ROOM ASSIGNMENT for " + id + " (ALL NIGHTS) ===");
                var totalAssigned = 0;
                $("#" + id + " .row.mt-2").each(function() {
                    var $roomRow = $(this);
                    var checkedOccupancies = $roomRow.find('.chk-prices:checked');
                    if (checkedOccupancies.length > 0) {
                        var persons = checkedOccupancies.map(function() { 
                            return $(this).data('person'); 
                        }).get().join(', ');
                        var roomCount = $roomRow.find('input.rooms-cnt').val();
                        var roomNight = getRoomNight($roomRow);
                        console.log("Room:", persons, "Count:", roomCount, "Night:", roomNight, "in container:", id);
                        totalAssigned += parseInt(roomCount);
                    }
                });
                console.log("Total rooms assigned in " + id + ":", totalAssigned);
                console.log("Expected rooms:", rooms_arr.length);
            });
        }
        
        // UPDATED preserveNightAttributes function to handle cloned rows properly
        function preserveNightAttributes($clonedRow, night, isCloned = false) {
            // Get the current highest index for this room type and night
            var currentMaxIndex = 0;
            var roomType = '';
            
            // Find the room type from the first checkbox
            var $firstCheckbox = $clonedRow.find('.chk-prices').first();
            if ($firstCheckbox.length > 0) {
                var name = $firstCheckbox.attr('name');
                if (name) {
                    var match = name.match(/night_\d+_(\d+)_\d+_hotel_prices\[(\d+)\]/);
                    if (match) {
                        roomType = match[1];
                        currentMaxIndex = parseInt(match[2]);
                    }
                }
            }
            
            // For cloned rows, we need to increment the index
            var newIndex = isCloned ? currentMaxIndex + 1 : currentMaxIndex;
            
            // Update all checkbox names to maintain night-specific structure with proper indexing
            $clonedRow.find('.chk-prices').each(function() {
                var $checkbox = $(this);
                var currentName = $checkbox.attr('name');
                if (currentName && currentName.includes('night_')) {
                    // Replace the night number and index in the name attribute
                    var newName = currentName
                        .replace(/night_\d+_/, 'night_' + night + '_')
                        .replace(/\[(\d+)\]/, '[' + newIndex + ']');
                    $checkbox.attr('name', newName);
                }
            });
            
            // Update hidden input classes for night tracking
            $clonedRow.find('[class*="chk-prices-all-night"]').each(function() {
                var $hiddenInput = $(this);
                var currentClass = $hiddenInput.attr('class');
                if (currentClass && currentClass.includes('chk-prices-all-night-')) {
                    // Replace the night number in the class
                    var newClass = currentClass.replace(/chk-prices-all-night-\d+/, 'chk-prices-all-night-' + night);
                    $hiddenInput.attr('class', newClass);
                }
            });
            
            // Update main checkbox names if they contain night info
            $clonedRow.find('input[type="checkbox"][class^="chk_"]').each(function() {
                var $mainCheckbox = $(this);
                var currentName = $mainCheckbox.attr('name');
                if (currentName && currentName.includes('night_')) {
                    var newName = currentName.replace(/night_\d+_/, 'night_' + night + '_');
                    $mainCheckbox.attr('name', newName);
                }
            });
            
            // Update room count input names if they contain night info
            $clonedRow.find('input.rooms-cnt').each(function() {
                var $roomCount = $(this);
                var currentName = $roomCount.attr('name');
                if (currentName && currentName.includes('night_')) {
                    var newName = currentName.replace(/night_\d+_/, 'night_' + night + '_');
                    $roomCount.attr('name', newName);
                }
            });
        }
        
        // Helper function to split combined occupancy types like "2(A),1(C)[5]" into ["2(A)", "1(C)"]
        function splitOccupancyType(occupancy) {
            // Remove child age brackets and their contents before splitting
            var cleanOccupancy = occupancy.replace(/\[.*?\]/g, '');
            
            if (cleanOccupancy.includes(',')) {
                return cleanOccupancy.split(',').map(function(part) {
                    return part.trim();
                });
            } else {
                return [cleanOccupancy];
            }
        }
        
        // Helper function to determine which night a room belongs to
        function getRoomNight($roomRow) {
            var $firstCheckbox = $roomRow.find('.chk-prices').first();
            if ($firstCheckbox.length > 0) {
                var name = $firstCheckbox.attr('name');
                if (name && name.includes('night_')) {
                    var nightMatch = name.match(/night_(\d+)_/);
                    if (nightMatch && nightMatch[1]) {
                        return parseInt(nightMatch[1]);
                    }
                }
            }
            
            var $hiddenInput = $roomRow.find('[class*="chk-prices-all-night"]');
            if ($hiddenInput.length > 0) {
                var className = $hiddenInput.attr('class');
                if (className && className.includes('chk-prices-all-night-')) {
                    var nightMatch = className.match(/chk-prices-all-night-(\d+)/);
                    if (nightMatch && nightMatch[1]) {
                        return parseInt(nightMatch[1]);
                    }
                }
            }
            
            return 1; // Default to night 1
        }
        
        // Get unique identifier for a room
        function getRoomUniqueId($roomRow) {
            // Try to get ID from the main container
            var containerId = $roomRow.attr('id');
            if (containerId) return containerId;
            
            // Try to get ID from prices-div
            var pricesDivId = $roomRow.find('.prices-div').attr('id');
            if (pricesDivId) return pricesDivId;
            
            // Try to get from main checkbox
            var mainCheckboxId = $roomRow.find('input[type="checkbox"][class^="chk_"]').attr('id');
            if (mainCheckboxId) return mainCheckboxId;
            
            // Fallback: generate from content
            var categoryText = $roomRow.find(".div-category label").text().trim();
            var night = getRoomNight($roomRow);
            return 'room_' + night + '_' + categoryText.replace(/[^a-zA-Z0-9]/g, '_');
        }    

