    // New 03 Feb 2026 Night Wise hotel Cost updated 
    function individual_hotels_categories_new() 
    {
        $("#hotel-categories-individual").html("");
        $("#hotel-categories").html("");
        var html = '';
        
        var daywise_hotels_cnt = 0;
        $('.daywise-hotels').each(function() {
            if (!$(this).hasClass('hide')) {
                daywise_hotels_cnt++;
            }
        });
        
        let allHotelsArr = [];
        for (let i = 1; i <= qdata.nights; i++) {
            let nightHotels = [];
            $("input[name^='night_"+i+"_'][type='text']").each(function () {
                let val = $(this).val().trim().toLowerCase();
                if (val !== "") nightHotels.push(val);
            });
            allHotelsArr.push(nightHotels.join("|"));
        }
        let allSameHotels = allHotelsArr.every((v, i, a) => v === a[0]);
        var l = qdata.nights;

        var previous_category = '';
        var div_ids_arr = [];
        let displayedHotels = new Set();

        // Create container divs for each category
        for(var j=1;j<=1;j++) 
        {
            $("input[name='hotel_category[]']").map(function () {
                if (this.checked) {
                    var category = this.value;
                    $("input[name='hdn_night_"+j+"_"+category.replaceAll(" ","_").toLowerCase()+"_ids[]']").map(function (index) {
                        var h = '';
                        if(previous_category !== "" && previous_category !== category){
                            h = '<div class="w-100 d-none d-md-block mb-4" style="border: 1px solid;"></div>';
                        }
                        var div_html = h+'<div class="col-md-6 scrollbar" style="padding:0px 25px;height: 500px; overflow-y: auto;width:670px;" id="'+category.replaceAll(" ","_").toLowerCase()+'_'+index+'"><span class="bold mt-4">'+category+' (Hotel Option '+(index+1)+')</span></div>';
                        $("#hotel-categories-individual").append(div_html);
                        previous_category = category;
                        div_ids_arr.push(category.replaceAll(" ","_").toLowerCase()+'_'+index);
                    });
                }
            });
        }

        // First, collect all hotel data for all nights
        let allNightsPromises = [];
        let allNightsData = [];
        
        // Hotel name cache for consistency
        let hotelNamesCache = {};
        
        for(var j=1; j<=l; j++) 
        {
            // Iterate through checked categories for each night
            $("input[name='hotel_category[]']:checked").each(function (index) {
                var category = $(this).val();
                var categoryKey = category.replaceAll(" ","_").toLowerCase();
                
                // Find all hotel IDs for this category and night
                $("input[name='hdn_night_"+j+"_"+categoryKey+"_ids[]']").each(function (ids_index) {
                    var hotel_id = $(this).val();
                    
                    // FIX 1: Handle hotel_id = 0 or empty
                    if (!hotel_id || hotel_id === '0' || hotel_id == 0) {
                        console.log(`Night ${j}: Hotel ID is 0 or empty - creating placeholder for category ${category}`);
                        
                        // Create placeholder data for hotel_id = 0
                        let nightDate = new Date(qdata.checkin);
                        nightDate.setDate(nightDate.getDate() + (j - 1));
                        let checkinDate = nightDate.toISOString().split('T')[0];
                        let displayDate = nightDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
                        
                        let placeholderData = {
                            response: "s",
                            details: { result: [] },
                            night_number: j,
                            nightNumber: j,
                            checkinDate: checkinDate,
                            displayDate: displayDate,
                            hotelId: '0',
                            category: category,
                            divToAppendId: categoryKey+'_'+ids_index,
                            roomType: [], // Empty room type
                            idsIndex: ids_index,
                            hotelName: 'Proceed with same hotel',
                            priceSignature: 'empty_hotel_0',
                            isNoHotel: true,
                            hasPricing: true, // No hotel doesn't need pricing
                            errorMessage: ''
                        };
                        
                        allNightsData.push(placeholderData);
                        return; // Skip AJAX call
                    }
                    
                    var room_type = $("input[name='"+categoryKey+"_room_type[]']:checked").map(function () {
                        return this.value;
                    }).get();
                    
                    var div_to_append_id = categoryKey+'_'+ids_index;
                    
                    // Calculate date for SPECIFIC NIGHT (j)
                    let nightDate = new Date(qdata.checkin);
                    nightDate.setDate(nightDate.getDate() + (j - 1));
                    let checkinDate = nightDate.toISOString().split('T')[0];
                    
                    // Format date for display
                    let displayDate = nightDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
                    
                    // Next day for checkout
                    let checkoutDate = new Date(nightDate);
                    checkoutDate.setDate(checkoutDate.getDate() + 1);
                    checkoutDate = checkoutDate.toISOString().split('T')[0];
                    
                    // ========== FIX: Calculate correct night number ==========
                    // Calculate ACTUAL night number - यह सबसे important fix है
                    // qdata.checkin से calculate करें कि यह actual कौन सी night है
                    let actualNightNumber = j; // FIXED: Use j directly, not j-1
                    
                    // Create and store promise for AJAX call
                    var promise = $.ajax({
                        url: "<?php echo site_url('admin/quotation/get_hotel_prices'); ?>",
                        type: "post",
                        data: {
                            'hotel_id': hotel_id,
                            'check_in': checkinDate,
                            'check_out': checkoutDate,
                            'type': category,
                            'room_type': '',
                            'night_number': j
                        },
                        dataType: 'JSON'
                    }).then(function(data) {
                        // ========== ADDED: Apply tourist tax ==========
                        if (data.hotel_info && data.hotel_info.per_person_cost === 'yes' && data.hotel_info.tourist_tax_cost) {
                            applyTouristTax(data, data.hotel_info.tourist_tax_cost);
                        }
                        // =============================================
                        console.log(`AJAX Response for Night ${j}:`, data);
                        
                        // Function to get hotel name
                        function getHotelName(hotelId, data) {
                            if (hotelNamesCache[hotelId]) {
                                return hotelNamesCache[hotelId];
                            }
                            
                            // Try to get from current response
                            if (data.hotel_info && data.hotel_info.name) {
                                hotelNamesCache[hotelId] = data.hotel_info.name;
                                return hotelNamesCache[hotelId];
                            }
                            
                            // Try from details result
                            if (data.details && data.details.result && data.details.result.length > 0 && data.details.result[0].name) {
                                hotelNamesCache[hotelId] = data.details.result[0].name;
                                return hotelNamesCache[hotelId];
                            }
                            
                            // If not found, return formatted ID
                            return 'Hotel #' + hotelId;
                        }
                        
                        // Get hotel name
                        let hotelName = getHotelName(hotel_id, data);
                        
                        // ========== IMPLEMENTED: HOTEL COST NOT EXIST LOGIC ==========
                        // Check has_pricing_for_date flag
                        if (data.response === "s" && data.has_pricing_for_date === true && data.details && data.details.result && data.details.result.length > 0) {
                            // Sort room_type array for consistent comparison
                            let sortedRoomType = [...room_type].sort();
                            
                            console.log(`Night ${actualNightNumber} - Hotel: ${hotel_id} (${hotelName}), Room Types:`, room_type, 'Sorted:', sortedRoomType);
                            
                            // FIX: Use the correct night number calculation
                            let nightNum = data.night_number || actualNightNumber;
                            
                            // Add night info to data
                            data.nightNumber = parseInt(nightNum);
                            data.checkinDate = checkinDate;
                            data.displayDate = displayDate;
                            data.hotelId = hotel_id;
                            data.category = category;
                            data.divToAppendId = div_to_append_id;
                            data.roomType = sortedRoomType;
                            data.idsIndex = ids_index;
                            data.hotelName = hotelName;
                            data.priceSignature = getPriceSignature(data);
                            data.isNoHotel = false;
                            data.hasPricing = true;
                            data.errorMessage = '';
                            
                            console.log(`✓ Night ${data.nightNumber} - ${hotelName} - Date: ${displayDate} - PRICING AVAILABLE`);
                            
                            allNightsData.push(data);
                        } else {
                            // Create error data when no pricing
                            console.log(`✗ Night ${actualNightNumber} - No pricing for date ${displayDate} for hotel ${hotel_id} (${hotelName})`);
                            
                            // ========== CRITICAL FIX: Use actualNightNumber, not j ==========
                            let errorData = {
                                response: "e",
                                details: { result: [] },
                                nightNumber: actualNightNumber, // FIXED: Use actualNightNumber, not j
                                checkinDate: checkinDate,
                                displayDate: displayDate,
                                hotelId: hotel_id,
                                category: category,
                                divToAppendId: div_to_append_id,
                                roomType: room_type,
                                idsIndex: ids_index,
                                hotelName: hotelName,
                                priceSignature: 'no_pricing',
                                isNoHotel: false,
                                hasPricing: false,
                                errorMessage: 'Hotel cost not available for date: ' + displayDate
                            };
                            allNightsData.push(errorData);
                        }
                        // ========== END: ADDED HOTEL COST NOT EXIST LOGIC ==========
                        
                        return data;
                    }).catch(function(xhr, status, error) {
                        console.log(`Night ${j} - AJAX Error:`, error);
                        // Create placeholder on error
                        let placeholderData = {
                            response: "e",
                            details: { result: [] },
                            nightNumber: actualNightNumber, // FIXED: Use actualNightNumber
                            checkinDate: checkinDate,
                            displayDate: displayDate,
                            hotelId: hotel_id,
                            category: category,
                            divToAppendId: div_to_append_id,
                            roomType: room_type,
                            idsIndex: ids_index,
                            hotelName: 'Hotel #' + hotel_id + ' (Error)',
                            priceSignature: 'error',
                            isNoHotel: false,
                            hasPricing: false,
                            errorMessage: 'Error fetching hotel cost for date: ' + displayDate
                        };
                        allNightsData.push(placeholderData);
                        return null;
                    });
                    
                    allNightsPromises.push(promise);
                });
            });
        }
        
        // ========== ADDED: Tourist tax helper ==========
        function applyTouristTax(data, tax) {
            if (!data.details || !data.details.result) return;
            tax = parseFloat(tax);
            if (isNaN(tax) || tax <= 0) return;

            $.each(data.details.result, function(idx, cat) {
                // Adjust adult prices in 'details' string
                if (cat.details) {
                    let parts = cat.details.split(',');
                    let newParts = [];
                    $.each(parts, function(i, part) {
                        part = part.trim();
                        let match = part.match(/^(\d+)\(A\)\s+([\d.]+)(.*)$/);
                        if (match) {
                            let numAdults = parseInt(match[1]);
                            let basePrice = parseFloat(match[2]);
                            let suffix = match[3] || '';
                            let newPrice = basePrice + (tax * numAdults);
                            newParts.push(numAdults + '(A) ' + newPrice.toFixed(2) + suffix);
                        } else {
                            // Keep non-adult entries unchanged (should not occur)
                            newParts.push(part);
                        }
                    });
                    cat.details = newParts.join(',');
                }

                // Adjust child prices (1 to 4)
                for (let i = 1; i <= 4; i++) {
                    let childField = 'chid' + i + '_price';
                    let childTypeField = 'child_type' + i;
                    if (cat[childField] && cat[childField] > 0) {
                        // cat[childField] = parseFloat(cat[childField]) + tax;
                        if (cat[childTypeField] !== 'CNB') {
                            cat[childField] = parseFloat(cat[childField]) + tax;
                        }
                    }
                }
            });
        }
        // ==============================================
        
        // Helper function to get price signature
        function getPriceSignature(nightData) 
        {
            let signature = '';
            if (nightData.details && nightData.details.result) {
                nightData.details.result.forEach(categoryData => {
                    if (categoryData && categoryData.details) {
                        try {
                            // Extract just the price numbers for comparison
                            let priceArray = categoryData.details.split(',').map(item => {
                                if (!item || !item.trim()) return 0;
                                let parts = item.trim().split(" ");
                                if (parts.length < 2) return 0;
                                
                                // Extract price - remove any non-numeric characters except decimal point
                                let priceStr = parts[1].replace(/[^\d.]/g, '');
                                return parseFloat(priceStr) || 0;
                            }).filter(price => price > 0).sort((a, b) => a - b);
                            
                            if (priceArray.length > 0) {
                                signature += categoryData.id + ':' + priceArray.join('|') + ';';
                            }
                        } catch (e) {
                            console.error('Error parsing price for category:', categoryData.id, e);
                        }
                    }
                });
            }
            return signature;
        }
        
        // Global variable to track checkboxes that should be checked
        var globalEleChk = [];
        
        // FIX 2: Initialize savedHotelRoomDetails if undefined
        if (typeof savedHotelRoomDetails === 'undefined') {
            savedHotelRoomDetails = {};
            console.log('savedHotelRoomDetails initialized to empty object');
        }
        
        // Wait for all AJAX calls to complete
        $.when.apply($, allNightsPromises).then(function() {
            // Filter out null responses
            allNightsData = allNightsData.filter(data => data !== null);
            
            // Sort all nights data by night number
            allNightsData.sort((a, b) => a.nightNumber - b.nightNumber);
            
            console.log('All Nights Data with Night Numbers:');
            allNightsData.forEach((data, index) => {
                console.log(`Index ${index}: Night ${data.nightNumber} - ${data.hotelName} (ID: ${data.hotelId}) - No Hotel: ${data.isNoHotel} - Has Pricing: ${data.hasPricing}`);
            });
            
            if (allNightsData.length === 0) {
                console.log('No hotel data found for any night!');
                return;
            }
            
            // Process and merge nights with price grouping
            processAndMergeNightsWithPriceGrouping(allNightsData);

            setTimeout(function() {
                console.log('Checking checkboxes from globalEleChk:', globalEleChk);
                globalEleChk.forEach((classChk) => {
                    $("." + classChk).prop("checked", true);
                    console.log('Checked checkbox with class:', classChk);
                });
                // Now disable after they are checked
                // if($('.file_status').val() === 'view'){
                    makeQuotationReadOnly();
                // }
            }, 100);
        });

        function processAndMergeNightsWithPriceGrouping(allNightsData) 
        {
            console.log('Processing nights with price grouping:');
            
            // First, organize data by hotel, category, and price signature
            let hotelGroups = {};
            
            allNightsData.forEach(nightData => {
                // Create a unique key for this hotel + category combination
                let key = nightData.divToAppendId + '_' + nightData.hotelId;
                
                console.log(`Night ${nightData.nightNumber} (${nightData.hotelName}) - Key:`, key, '- No Hotel:', nightData.isNoHotel, '- Has Pricing:', nightData.hasPricing);
                
                if (!hotelGroups[key]) {
                    hotelGroups[key] = {
                        hotelId: nightData.hotelId,
                        hotelName: nightData.hotelName,
                        category: nightData.category,
                        divToAppendId: nightData.divToAppendId,
                        idsIndex: nightData.idsIndex,
                        isNoHotel: nightData.isNoHotel || false,
                        priceGroups: [] // Array of price groups for this hotel
                    };
                }
                
                // For hotel_id = 0, we don't need price grouping
                if (nightData.isNoHotel) {
                    // Just add the night directly
                    let foundGroup = false;
                    for (let i = 0; i < hotelGroups[key].priceGroups.length; i++) {
                        if (hotelGroups[key].priceGroups[i].isNoHotel) {
                            hotelGroups[key].priceGroups[i].nights.push(nightData.nightNumber);
                            hotelGroups[key].priceGroups[i].displayDates.push(nightData.displayDate);
                            hotelGroups[key].priceGroups[i].checkinDates.push(nightData.checkinDate);
                            hotelGroups[key].priceGroups[i].nightData.push(nightData);
                            foundGroup = true;
                            break;
                        }
                    }
                    
                    if (!foundGroup) {
                        hotelGroups[key].priceGroups.push({
                            isNoHotel: true,
                            nights: [nightData.nightNumber],
                            displayDates: [nightData.displayDate],
                            checkinDates: [nightData.checkinDate],
                            nightData: [nightData],
                            roomType: nightData.roomType,
                            hasPricing: true // No hotel doesn't need pricing
                        });
                    }
                }
                else if (nightData.hasPricing === false) {
                    // Handle nights with no pricing
                    console.log(`Night ${nightData.nightNumber} has no pricing - creating no pricing group`);
                    
                    let foundGroup = false;
                    for (let i = 0; i < hotelGroups[key].priceGroups.length; i++) {
                        if (hotelGroups[key].priceGroups[i].priceSignature === 'no_pricing') {
                            hotelGroups[key].priceGroups[i].nights.push(nightData.nightNumber);
                            hotelGroups[key].priceGroups[i].displayDates.push(nightData.displayDate);
                            hotelGroups[key].priceGroups[i].checkinDates.push(nightData.checkinDate);
                            hotelGroups[key].priceGroups[i].nightData.push(nightData);
                            if (nightData.errorMessage) {
                                if (!hotelGroups[key].priceGroups[i].errorMessages) {
                                    hotelGroups[key].priceGroups[i].errorMessages = [];
                                }
                                hotelGroups[key].priceGroups[i].errorMessages.push({
                                    night: nightData.nightNumber,
                                    date: nightData.displayDate,
                                    message: nightData.errorMessage
                                });
                            }
                            foundGroup = true;
                            break;
                        }
                    }
                    
                    if (!foundGroup) {
                        hotelGroups[key].priceGroups.push({
                            priceSignature: 'no_pricing',
                            nights: [nightData.nightNumber],
                            displayDates: [nightData.displayDate],
                            checkinDates: [nightData.checkinDate],
                            nightData: [nightData],
                            roomType: nightData.roomType,
                            isNoHotel: false,
                            hasPricing: false,
                            errorMessages: nightData.errorMessage ? [{
                                night: nightData.nightNumber,
                                date: nightData.displayDate,
                                message: nightData.errorMessage
                            }] : []
                        });
                    }
                }
                else if (nightData.details && nightData.details.result && nightData.details.result.length > 0) {
                    // Group by price signature for regular hotels with pricing
                    let foundGroup = false;
                    
                    for (let i = 0; i < hotelGroups[key].priceGroups.length; i++) {
                        let group = hotelGroups[key].priceGroups[i];
                        
                        // Check if this night has the same price signature as the group
                        if (group.priceSignature === nightData.priceSignature) {
                            // Add to existing group
                            group.nights.push(nightData.nightNumber);
                            group.displayDates.push(nightData.displayDate);
                            group.checkinDates.push(nightData.checkinDate);
                            group.nightData.push(nightData);
                            foundGroup = true;
                            break;
                        }
                    }
                    
                    // If no matching price group found, create a new one
                    if (!foundGroup) {
                        hotelGroups[key].priceGroups.push({
                            priceSignature: nightData.priceSignature,
                            nights: [nightData.nightNumber],
                            displayDates: [nightData.displayDate],
                            checkinDates: [nightData.checkinDate],
                            nightData: [nightData],
                            roomType: nightData.roomType,
                            isNoHotel: false,
                            hasPricing: true
                        });
                    }
                } else {
                    console.log('Night', nightData.nightNumber, 'has no valid data');
                }
            });
            
            // Debug: Log grouped data
            console.log('Hotel Groups with Price Grouping:');
            Object.keys(hotelGroups).forEach(key => {
                console.log(`\nHotel Group: ${key}`);
                console.log(`  Hotel: ${hotelGroups[key].hotelName} (ID: ${hotelGroups[key].hotelId})`);
                console.log(`  Is No Hotel: ${hotelGroups[key].isNoHotel}`);
                console.log(`  Price Groups: ${hotelGroups[key].priceGroups.length}`);
                
                hotelGroups[key].priceGroups.forEach((group, index) => {
                    console.log(`  Price Group ${index + 1}:`);
                    console.log(`    Is No Hotel: ${group.isNoHotel || false}`);
                    console.log(`    Has Pricing: ${group.hasPricing !== false}`);
                    console.log(`    Nights: ${group.nights.join(', ')}`);
                    console.log(`    Dates: ${group.displayDates.join(', ')}`);
                    if (!group.isNoHotel) {
                        console.log(`    Price Signature: ${group.priceSignature}`);
                    }
                    if (group.errorMessages && group.errorMessages.length > 0) {
                        console.log(`    Error Messages: ${group.errorMessages.length}`);
                    }
                });
            });
            
            if (Object.keys(hotelGroups).length === 0) {
                console.log('No hotel groups created!');
                return;
            }
            
            // Reset globalEleChk array
            globalEleChk = [];
            
            // Display each hotel with its price groups
            Object.values(hotelGroups).forEach((hotel, hotelIndex) => {
                console.log(`\nProcessing Hotel ${hotelIndex + 1}:`, hotel.hotelName, '(ID:', hotel.hotelId, ')');
                console.log('Is No Hotel:', hotel.isNoHotel);

                // Get saved data for this hotel
                let savedHotelRows = [];
                if (savedHotelRoomDetails && savedHotelRoomDetails[hotel.hotelId]) {
                    savedHotelRows = savedHotelRoomDetails[hotel.hotelId];
                    console.log(`Hotel ${hotel.hotelName} has ${savedHotelRows.length} saved rows`);
                } else if (hotel.hotelId === '0' && savedHotelRoomDetails['0']) {
                    // Special case for hotel_id = 0
                    savedHotelRows = savedHotelRoomDetails['0'];
                    console.log(`Hotel ID 0 has ${savedHotelRows.length} saved rows`);
                }
                
                // Display each price group for this hotel
                hotel.priceGroups.forEach((priceGroup, groupIndex) => {
                    console.log(`\nDisplaying Price Group ${groupIndex + 1} for ${hotel.hotelName}`);
                    console.log(`  Is No Hotel: ${priceGroup.isNoHotel || false}`);
                    console.log(`  Has Pricing: ${priceGroup.hasPricing !== false}`);
                    console.log(`  Nights: ${priceGroup.nights.join(', ')}`);
                    console.log(`  Dates: ${priceGroup.displayDates.join(', ')}`);
                    
                    if (priceGroup.errorMessages && priceGroup.errorMessages.length > 0) {
                        console.log(`  Error Messages:`, priceGroup.errorMessages);
                    }
                    
                    // Sort nights and dates together
                    let combined = priceGroup.nights.map((night, index) => ({
                        night: night,
                        displayDate: priceGroup.displayDates[index],
                        checkinDate: priceGroup.checkinDates[index]
                    })).sort((a, b) => a.night - b.night);
                    
                    // Extract sorted arrays
                    let sortedNights = combined.map(item => item.night);
                    let sortedDates = combined.map(item => item.displayDate);
                    let sortedCheckinDates = combined.map(item => item.checkinDate);
                    
                    // Format nights display
                    let nightsText = '';
                    let datesText = '';
                    
                    if (sortedNights.length === 1) {
                        nightsText = 'Night ' + sortedNights[0];
                        datesText = '(' + sortedDates[0] + ')';
                    } else {
                        // Check if ALL nights are consecutive
                        let allConsecutive = true;
                        for (let i = 1; i < sortedNights.length; i++) {
                            if (sortedNights[i] !== sortedNights[i-1] + 1) {
                                allConsecutive = false;
                                break;
                            }
                        }
                        
                        if (allConsecutive) {
                            nightsText = 'Nights ' + sortedNights[0] + '-' + sortedNights[sortedNights.length - 1];
                            if (sortedDates.length > 1) {
                                datesText = '(' + sortedDates[0] + ' to ' + sortedDates[sortedDates.length - 1] + ')';
                            } else {
                                datesText = '(' + sortedDates[0] + ')';
                            }
                        } else {
                            nightsText = 'Nights ' + sortedNights.join(', ');
                            if (sortedDates.length > 1) {
                                datesText = '(' + sortedDates.join(', ') + ')';
                            } else {
                                datesText = '(' + sortedDates[0] + ')';
                            }
                        }
                    }
                    
                    // Find saved data for THIS specific night group (OLD CODE LOGIC)
                    let filteredSavedRoomsObj = {};
                    let hasSavedDataForThisGroup = false;
                    
                    if (!priceGroup.isNoHotel && priceGroup.hasPricing !== false && savedHotelRows.length > 0) {
                        console.log(`Looking for saved data matching nights ${sortedNights.join(',')}`);
                        
                        // OLD CODE LOGIC: Handle both single and multiple nights
                        if (sortedNights.length === 1) {
                            // Single night - find exact match
                            const savedRow = savedHotelRows.find(row => row.night == sortedNights[0]);
                            if (savedRow && savedRow.parsedRooms) {
                                filteredSavedRoomsObj = savedRow.parsedRooms;
                                hasSavedDataForThisGroup = true;
                                console.log(`Found saved data for Night ${sortedNights[0]}:`, filteredSavedRoomsObj);
                            }
                        } else if (sortedNights.length > 1) {
                            // Multiple nights - use first night's saved data
                            const firstNight = sortedNights[0];
                            const savedRow = savedHotelRows.find(row => row.night == firstNight);
                            
                            if (savedRow && savedRow.parsedRooms) {
                                filteredSavedRoomsObj = savedRow.parsedRooms;
                                hasSavedDataForThisGroup = true;
                                console.log(`Using saved data from Night ${firstNight} for nights ${sortedNights.join(',')}:`, filteredSavedRoomsObj);
                            }
                        }
                        
                        // If still no data found, try the first available saved row
                        if (!hasSavedDataForThisGroup && savedHotelRows.length > 0) {
                            const firstSavedRow = savedHotelRows[0];
                            if (firstSavedRow && firstSavedRow.parsedRooms) {
                                filteredSavedRoomsObj = firstSavedRow.parsedRooms;
                                hasSavedDataForThisGroup = true;
                                console.log(`Using first saved row as fallback:`, filteredSavedRoomsObj);
                            }
                        }
                    }
                    
                    // ========== NEW LOGIC IMPLEMENTATION ==========
                    // Handle nights with no pricing - similar to individual_hotels_categories()
                    let hasAnyPricingError = false;
                    let errorNights = [];
                    
                    // Check each night in this group for pricing errors
                    if (priceGroup.errorMessages && priceGroup.errorMessages.length > 0) {
                        hasAnyPricingError = true;
                        errorNights = priceGroup.errorMessages;
                    }
                    
                    // Determine which nights have pricing and which have errors
                    let nightsWithPricing = [];
                    let nightsWithErrors = [];
                    
                    if (hasAnyPricingError) {
                        // Filter out nights that have errors
                        nightsWithPricing = sortedNights.filter(nightNum => 
                            !errorNights.some(error => error.night === nightNum)
                        );
                        nightsWithErrors = sortedNights.filter(nightNum => 
                            errorNights.some(error => error.night === nightNum)
                        );
                    } else {
                        nightsWithPricing = sortedNights;
                    }
                    
                    console.log(`Nights with pricing: ${nightsWithPricing.join(', ')}`);
                    console.log(`Nights with errors: ${nightsWithErrors.join(', ')}`);
                    // ========== END NEW LOGIC ==========
                    
                    // Display this price group with the new logic
                    displayHotelPriceGroup({
                        hotelId: hotel.hotelId,
                        hotelName: hotel.hotelName,
                        category: hotel.category,
                        divToAppendId: hotel.divToAppendId,
                        idsIndex: hotel.idsIndex,
                        nights: sortedNights,
                        displayDates: sortedDates,
                        checkinDates: sortedCheckinDates,
                        nightsText: nightsText,
                        datesText: datesText,
                        nightData: priceGroup.nightData[0], // Use first night's data for display
                        roomType: priceGroup.roomType,
                        hasSavedData: hasSavedDataForThisGroup,
                        savedRoomsObj: filteredSavedRoomsObj,
                        isNoHotel: priceGroup.isNoHotel || false,
                        hasPricing: priceGroup.hasPricing !== false,
                        errorMessages: priceGroup.errorMessages || [],
                        // New parameters for error handling
                        hasAnyPricingError: hasAnyPricingError,
                        errorNights: errorNights,
                        nightsWithPricing: nightsWithPricing,
                        nightsWithErrors: nightsWithErrors,
                        // Pass the saved row for debugging
                        savedRowInfo: savedHotelRows.find(row => row.night == sortedNights[0]) || null
                    });
                });
            });
            
            // After all groups are displayed, check the checkboxes
            setTimeout(function() {
                console.log('Checking checkboxes from globalEleChk:', globalEleChk);
                globalEleChk.forEach((classChk) => {
                    $("." + classChk).prop("checked", true);
                    console.log('Checked checkbox with class:', classChk);
                });
            }, 100);
            
            // Enable/disable guide sections
            var rdo_guide = $("#quotation-make-1 input[name='guide']:checked").val();
            var rdo_airport_pick_drop = $("#quotation-make-1 input[name='airport_pick_drop']:checked").val();
            var class_arr = [".guides", ".guides-shift", ".guides-prices", ".guides-add", ".hdn-guides"];
            $("#show-guides input, #show-guides select, #show-guides button").prop("disabled", false);
            if(rdo_guide==="no"){
                $("#show-guides input, #show-guides select, #show-guides button").prop("disabled", true);
            }else if($("#quotation-make-1 #div_driver_cum_guide").css("display") !== "none" && $("input[name='driver_cum_guide']:checked").val() === "driver_guide") {
                $("#show-guides input, #show-guides select, #show-guides button").prop("disabled", true);
                        $.each(class_arr, function(index, value) {
                            $(value).eq(0).prop("disabled", false);
                        });
            }
        }

        function formatPrice(price) {
            // Convert to float, then format to 2 decimal places
            let num = parseFloat(price);
            if (isNaN(num)) return '0.00';
            return num.toFixed(2);
        }
        
        function displayHotelPriceGroup(group) 
        {
            console.log('\n=== DISPLAY HOTEL PRICE GROUP ===');
            console.log('Hotel:', group.hotelName);
            console.log('Hotel ID:', group.hotelId);
            console.log('Is No Hotel:', group.isNoHotel);
            console.log('Has Pricing:', group.hasPricing);
            console.log('All Nights:', group.nights);
            console.log('Nights with Pricing:', group.nightsWithPricing);
            console.log('Nights with Errors:', group.nightsWithErrors);
            console.log('Has Any Pricing Error:', group.hasAnyPricingError);
            console.log('Error Messages:', group.errorMessages);
            
            let html = '';
            let groupEleChk = []; // Local array for this group
            
            // ========== IMPLEMENTED: HOTEL COST NOT EXIST LOGIC ==========
            // SHOW RED HEADER IF ANY NIGHT HAS NO PRICING
            let headerColor = '#49a6f5'; // Default blue
            if (group.hasAnyPricingError) {
                headerColor = '#f56565'; // Red for error
            }
            // ========== END: ADDED HOTEL COST NOT EXIST LOGIC ==========
            
            // FIX 4: Special display for hotel_id = 0 (From New Code)
            if (group.isNoHotel) {
                // Show "No Hotel Selected" message
                html = '<div class="row" style="color: #FFF;background-color:' + headerColor + ';font-size: 14px;font-weight: 600;border-radius: 10px; margin-top: 15px;">' +
                    '<div class="col-md-12">Proceed with same hotel' +
                    '<span class="float-right"> - ' + group.nightsText + ' ' + group.datesText + '</span></div></div>';
                
                html += '<div class="row mt-2" style="border-bottom:2px solid #000; padding: 15px; background-color: #f8f9fa;">' +
                    '<div class="col-md-12 text-center">' +
                    '<p class="text-muted" style="margin:5px !important;" >Proceed with same hotel was selected for this option.</p>' +
                    '</div></div>';
                
                // Still need to create hidden inputs for backend
                group.nights.forEach(nightNum => {
                    html += '<input type="hidden" name="hdn_night_' + nightNum + '_ids[]" value="0" />';
                    html += '<input type="hidden" name="night_' + nightNum + '_category_ids_0[]" value="" />';
                });
            } else if (group.hasPricing === false) {
                // ========== IMPLEMENTED: NO PRICING ERROR DISPLAY ==========
                // Show hotel name with merged nights and dates with RED header
                html = '<div class="row" style="color: #FFF;background-color:' + headerColor + ';font-size: 14px;font-weight: 600;border-radius: 10px; margin-top: 15px;">' +
                    '<div class="col-md-12">' + group.hotelName +
                    '<span class="float-right"> - ' + group.nightsText + ' ' + group.datesText + '</span></div></div>';
                
                // SHOW ERROR MESSAGE FOR NO PRICING
                html += '<div class="row mt-2" style="border-bottom:2px solid #000; padding: 10px; background-color: #ffebee;">' +
                    '<div class="col-md-12">' +
                    '<p class="text-danger text-center" style="margin:5px !important;"><strong>⚠️ Hotel cost not available for:</strong></p>';
                
                // Show each night with date that has error
                group.errorMessages.forEach(item => {
                    html += '<p class="text-danger text-center" style="margin:2px !important; font-size:12px;">' +
                        'Night ' + item.night + ' (' + item.date + ')</p>';
                });
                
                html += '<p class="text-danger text-center" style="margin:5px !important; font-size:11px;"><i>Please select different hotel or date</i></p>';
                html += '</div></div>';
                
                // IMPORTANT: DON'T SHOW PRICING OPTIONS IF ANY NIGHT HAS ERROR
                console.log('✓ ERROR: No pricing available for', group.hotelName, 'for nights', group.nights);
                
                // Still create hidden inputs for the hotel_id for all nights (including error nights)
                group.nights.forEach(nightNum => {
                    html += '<input type="hidden" name="hdn_night_' + nightNum + '_ids[]" value="' + group.hotelId + '" />';
                });
                // ========== END: ADDED NO PRICING ERROR DISPLAY ==========
            } else {
                // Regular hotel display with pricing available
                // Show hotel name with merged nights and dates
                html = '<div class="row" style="color: #FFF;background-color:' + headerColor + ';font-size: 14px;font-weight: 600;border-radius: 10px; margin-top: 15px;">' +
                    '<div class="col-md-12">' + group.hotelName +
                    '<span class="float-right"> - ' + group.nightsText + ' ' + group.datesText + '</span></div></div>';

                // ========== IMPLEMENTED: PARTIAL PRICING HANDLING ==========
                // SHOW ERROR MESSAGE IF ANY NIGHT HAS NO PRICING (partial pricing case)
                if (group.hasAnyPricingError && group.errorNights.length > 0) {
                    html += '<div class="row mt-2" style="border-bottom:2px solid #000; padding: 10px; background-color: #ffebee;">' +
                        '<div class="col-md-12">' +
                        '<p class="text-danger text-center" style="margin:5px !important;"><strong>⚠️ Hotel cost not available for:</strong></p>';
                    
                    // Show each night with date that has error
                    group.errorNights.forEach(item => {
                        html += '<p class="text-danger text-center" style="margin:2px !important; font-size:12px;">' +
                            'Night ' + item.night + ' (' + item.date + ')</p>';
                    });
                    
                    html += '<p class="text-danger text-center" style="margin:5px !important; font-size:11px;"><i>Please select different hotel or date</i></p>';
                    html += '</div></div>';
                    
                    console.log('Partial pricing available for', group.hotelName, '- nights with errors:', group.errorNights.map(e => e.night));
                }
                // ========== END: ADDED PARTIAL PRICING HANDLING ==========

                // Create hidden inputs for the hotel_id for ALL nights (including error nights)
                group.nights.forEach(nightNum => {
                    html += '<input type="hidden" name="hdn_night_' + nightNum + '_ids[]" value="' + group.hotelId + '" />';
                });
                
                // Display hotel section for this price group
                if (group.nightData && group.nightData.details && group.nightData.details.result) {
                    html += displayHotelSection(group.nightData, group, groupEleChk, group.hasAnyPricingError, group.errorNights, group.nightsWithPricing);
                } else {
                    console.error('Invalid nightData for group:', group);
                    html += '<div class="alert alert-warning">No hotel data available for this group</div>';
                }
            }

            $("#"+group.divToAppendId).append(html);
            
            // Add group checkboxes to global array (only for regular hotels with pricing)
            if (!group.isNoHotel && group.hasPricing !== false) {
                groupEleChk.forEach(classChk => {
                    if (globalEleChk.indexOf(classChk) === -1) {
                        globalEleChk.push(classChk);
                    }
                });
            }
            
            console.log('✓ Hotel price group displayed for', group.hotelName || 'No Hotel', 'for', group.nightsText);
            if (!group.isNoHotel && group.hasPricing !== false) {
                console.log('Group checkboxes to check:', groupEleChk);
            }
        }

        function displayHotelSection(nightData, group, groupEleChk, hasAnyPricingError, errorNights, nightsWithPricing) 
        {
            let html = '';
            let minPriceMap = {};
            
            // Calculate minimum prices ONLY for NEW hotels (not saved ones)
            // OLD CODE LOGIC: Check if we have saved data
            if (!group.hasSavedData && nightData && nightData.details && nightData.details.result) {
                $.each(nightData.details.result, function(i, val) {
                    if (val && val.details) {
                        let hotel_prices = val.details.split(",");
                        $.each(hotel_prices, function(_, v) {
                            let parts = v.trim().split(" ");
                            let roomType = parts[0];
                            let price = parseFloat(parts[1].replace(/[^\d.]/g, ''));
                            if (price > 0) {
                                if (!minPriceMap[roomType] || price < minPriceMap[roomType].price) {
                                    minPriceMap[roomType] = { price: price, id: val.id };
                                }
                            }
                        });
                    }
                });
            }
            
            if (nightData && nightData.details && nightData.details.result) {
                $.each(nightData.details.result, function(i, val) {
                    if (!val || !val.details) return;
                    
                    var hotel_prices = val.details.split(",");
                    var r_num = Math.random().toString().split(".")[1];
                    var class_chk = 'chk_'+val.id+'_'+group.hotelId+r_num;
                    var hasCheckedOption = false;
                    
                    // ========== OLD CODE SAVED LOGIC ==========
                    let savedCatRooms = [];
                    let category_checked = "";

                    if (group.hasSavedData && group.savedRoomsObj) {
                        console.log('=== DEBUG SAVED DATA ===');
                        console.log('savedRoomsObj:', group.savedRoomsObj);
                        console.log('Category ID from AJAX:', val.id);
                        console.log('Category name from AJAX:', val.category_name);
                        
                        try {
                            // Parse the JSON string if needed
                            let parsedSavedData = group.savedRoomsObj;
                            
                            // If it's a string, parse it as JSON
                            if (typeof parsedSavedData === 'string') {
                                try {
                                    parsedSavedData = JSON.parse(parsedSavedData);
                                    console.log('Parsed JSON string:', parsedSavedData);
                                } catch (parseError) {
                                    console.error('Failed to parse saved data as JSON:', parseError);
                                    console.log('Raw string:', parsedSavedData);
                                    parsedSavedData = {};
                                }
                            }
                            
                            // OLD CODE LOGIC: Find matching category
                            let categoryKey = null;
                            
                            // Format 1: "id_categoryname" 
                            const keyWithId = val.id + '_' + val.category_name;
                            
                            // Format 2: Search for key containing the category name
                            for (const key in parsedSavedData) {
                                if (parsedSavedData.hasOwnProperty(key)) {
                                    console.log('Checking saved key:', key);
                                    
                                    // Check if key matches exactly with ID prefix
                                    if (key === keyWithId) {
                                        categoryKey = key;
                                        console.log('✓ Found exact match with ID:', keyWithId);
                                        break;
                                    }
                                    
                                    // Check if key contains category name (case insensitive)
                                    if (key.toLowerCase().includes(val.category_name.toLowerCase())) {
                                        categoryKey = key;
                                        console.log('✓ Found match by category name:', key);
                                        break;
                                    }
                                    
                                    // Check if key ends with category name
                                    if (key.endsWith(val.category_name)) {
                                        categoryKey = key;
                                        console.log('✓ Found match by ending with category name:', key);
                                        break;
                                    }
                                }
                            }
                            
                            // If no match found, try using just the ID part
                            if (!categoryKey) {
                                for (const key in parsedSavedData) {
                                    if (parsedSavedData.hasOwnProperty(key)) {
                                        const keyParts = key.split('_');
                                        if (keyParts.length > 0 && keyParts[0] == val.id) {
                                            categoryKey = key;
                                            console.log('✓ Found match by ID only:', key);
                                            break;
                                        }
                                    }
                                }
                            }
                            
                            // If we found a matching category key
                            if (categoryKey && parsedSavedData[categoryKey]) {
                                const categoryData = parsedSavedData[categoryKey];
                                console.log('Found category data for key', categoryKey, ':', categoryData);
                                
                                if (Array.isArray(categoryData) && categoryData.length > 0) {
                                    // OLD CODE: Get the first item in the array
                                    const savedItem = categoryData[0];
                                    
                                    if (savedItem && savedItem.room_type && Array.isArray(savedItem.room_type)) {
                                        savedCatRooms = savedItem.room_type;
                                        category_checked = 'checked="checked"';
                                        console.log('✓ Extracted room_type array:', savedCatRooms);
                                    } else if (Array.isArray(savedItem)) {
                                        // If savedItem is already an array
                                        savedCatRooms = savedItem;
                                        category_checked = 'checked="checked"';
                                        console.log('✓ Saved item is already array:', savedCatRooms);
                                    }
                                } else if (Array.isArray(categoryData)) {
                                    // If categoryData is directly an array
                                    savedCatRooms = categoryData;
                                    category_checked = 'checked="checked"';
                                    console.log('✓ Category data is array:', savedCatRooms);
                                }
                            } else {
                                console.log('No matching category found in saved data');
                            }
                            
                        } catch (error) {
                            console.error('Error processing saved data:', error);
                        }
                    }

                    // Ensure savedCatRooms is an array
                    if (!Array.isArray(savedCatRooms)) {
                        savedCatRooms = [];
                    }
                    
                    const hasSavedCategoryData = savedCatRooms.length > 0;
                    // ========== END OF OLD CODE SAVED LOGIC ==========

                    // ========== IMPLEMENTED: PARTIAL PRICING LOGIC ==========
                    // Create checkbox names for NIGHTS WITH PRICING ONLY
                    let checkboxNames = [];
                    let nightsToShow = nightsWithPricing; // Use the filtered nights with pricing
                    
                    if (nightsToShow.length === 0) {
                        console.log('No nights with pricing for category', val.category_name);
                        return; // Skip if no nights have pricing
                    }
                    
                    nightsToShow.forEach(nightNum => {
                        checkboxNames.push('night_'+nightNum+'_category_ids_'+group.hotelId+'[]');
                    });
                    // ========== END: ADDED PARTIAL PRICING LOGIC ==========
                    
                    // Add to groupEleChk if category has saved data
                    if (hasSavedCategoryData && groupEleChk.indexOf(class_chk) === -1) {
                        groupEleChk.push(class_chk);
                    }
                    
                    html += '<div class="row mt-2" style="border-bottom:2px solid #000;">';
                    html += '<div class="col-md-12 row prices-div-'+val.id+r_num+'" id="prices-div_'+val.id+r_num+'">';
                    html += '<div class="col-md-5 div-category"><label class="bold">' +
                            '<input type="checkbox" ' + category_checked + ' class="'+class_chk+'" id="chk_'+val.id+'_'+group.hotelId+'" ' +
                            'value="'+val.id+'_'+val.category_name+'" ' +
                            'name="'+checkboxNames.join(' ')+'"> ' + (val.category_name || '') + '</label></div>' +
                            '<div class="col-md-6 mb-1"><div class="row" style="">';

                    var valid_prices = hotel_prices.filter(function(v) {
                        let parts = v.trim().split(" ");
                        let price = parseFloat(parts[1].replace(/[^\d.]/g, ''));
                        return price > 0;
                    });
                    
                    // For NEW hotels (not saved): calculate room_type logic
                    let hasCNB = false;
                    let hasCWB = false;
                    let hasChildType = false;
                    
                    if (!group.hasSavedData) {
                        // Check if CNB or CWB is selected along with adult room types
                        hasCNB = group.roomType.includes('CNB');
                        hasCWB = group.roomType.includes('CWB');
                        hasChildType = hasCNB || hasCWB;
                    }
                    
                    // Display Adult Prices
                    $.each(valid_prices, function(_, v) {
                        let parts = v.trim().split(" ");
                        let roomType = parts[0];
                        let price = parseFloat(parts[1].replace(/[^\d.]/g, ''));

                        let is_chk = '';
                        let savedRoomValue = v;
                        
                        // ========== OLD CODE: Check saved room types ==========
                        if (hasSavedCategoryData) {
                            console.log('Checking saved room types for:', roomType);
                            console.log('Saved room types array:', savedCatRooms);
                            
                            savedCatRooms.forEach((savedRoom, index) => {
                                if (typeof savedRoom === 'string') {
                                    const savedRoomParts = savedRoom.trim().split(" ");
                                    const savedRoomType = savedRoomParts[0];
                                    
                                    console.log(`Comparing saved "${savedRoomType}" with AJAX "${roomType}"`);
                                    
                                    if (savedRoomType === roomType) {
                                        is_chk = 'checked="checked"';
                                        savedRoomValue = savedRoom; // Use the full saved string
                                        hasCheckedOption = true;
                                        
                                        if (groupEleChk.indexOf(class_chk) === -1) {
                                            groupEleChk.push(class_chk);
                                        }
                                        
                                        console.log(`✓ Matched saved room type: ${savedRoomType} = ${roomType}`);
                                    }
                                }
                            });
                        }
                        // For NEW hotels (not saved): use the cheapest price logic
                        else if (!group.hasSavedData && group.roomType.includes(roomType)) {   
                            if (minPriceMap[roomType] 
                                    && minPriceMap[roomType].price === price 
                                    && minPriceMap[roomType].id === val.id
                                    && price > 0) {   
                                    is_chk = 'checked="checked"';
                                    // Add to groupEleChk if not already added
                                    if (groupEleChk.indexOf(class_chk) === -1) {
                                        groupEleChk.push(class_chk);
                                    }
                                    hasCheckedOption = true;
                                    
                                    // If child type is selected, mark this adult room as checked
                                    if (hasChildType) {
                                        is_chk = 'checked="checked"';
                                        if (groupEleChk.indexOf(class_chk) === -1) {
                                            groupEleChk.push(class_chk);
                                        }
                                        hasCheckedOption = true;
                                    }
                            }
                        }
                        
                        // ========== CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        let inputNames = [];
                        nightsToShow.forEach(nightNum => {
                            inputNames.push('night_'+nightNum+'_'+val.id+'_'+group.hotelId+'_hotel_prices[0][]');
                        });
                        // ========== END: CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        
                        html += '<div class="col-md-3 p-1">' +
                                '<input '+is_chk+' type="checkbox" class="chk-prices" data-person="'+roomType+'" ' +
                                'data-id="'+val.id+'_'+group.hotelId+'" value="'+savedRoomValue+'" ' +
                                'name="'+inputNames.join(' ')+'"> <span>'+roomType+'</span>' +
                                '<input type="textbox" style="width:100%;" class="chk-prices-input" ' +
                                'name="'+val.id+'_'+group.hotelId+'_hotel_prices_input[][]" value="'+(savedRoomValue.split(" ")[1] || parts[1])+'" readonly>' +
                                '</div>';
                    });
                    
                    // ========== CHILD PRICE DISPLAY LOGIC ==========
                    // Display Free Breakfast Child Option
                    if(val.freebreakfast && val.freebreakfast !== "" && val.freebreakfast > 0) {
                        var freebreakfast_text = '1(C)';
                        var childBedType = 'CNB';
                        
                        var is_chk_free = '';
                        
                        // For SAVED categories: ONLY check if EXACT 0 cost child exists
                        if (hasSavedCategoryData) {
                            savedCatRooms.forEach(savedRoom => {
                                if (typeof savedRoom === 'string') {
                                    if (savedRoom.trim() === '1(C) 0 CNB' || savedRoom.trim() === '1(C) 0') {
                                        is_chk_free = 'checked="checked"';
                                        if (groupEleChk.indexOf(class_chk) === -1) {
                                            groupEleChk.push(class_chk);
                                        }
                                    }
                                }
                            });
                        }
                        // For NEW hotels: use the original logic
                        else if(!group.hasSavedData) {
                            if((hasCNB || hasCWB) && freebreakfast_text == qdata.child+"C" && hasCheckedOption){ 
                                is_chk_free = 'checked="checked"'; 
                                if (groupEleChk.indexOf(class_chk) === -1) {
                                    groupEleChk.push(class_chk);
                                }
                            }
                        }
                        
                        // ========== CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        let childInputNames = [];
                        nightsToShow.forEach(nightNum => {
                            childInputNames.push('night_'+nightNum+'_'+val.id+'_'+group.hotelId+'_hotel_prices[0][]');
                        });
                        // ========== END: CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        
                        html += '<div class="col-md-3 p-1" style=" padding-top: 5px;">';
                        html += '<input type="checkbox" class="chk-prices chk-freebreakfast" data-person="'+freebreakfast_text+'" ' +
                                'data-id="'+val.id+'_'+group.hotelId+'" value="'+freebreakfast_text+' 0 '+childBedType+'" ' +
                                'name="'+childInputNames.join(' ')+'" '+is_chk_free+'>';
                        html += ' <span style="font-size: 12px;">'+freebreakfast_text+'</span>';
                        html += '<input type="textbox" style="width:100%; font-size: 11px;" class="chk-prices-input" ' +
                                'name="'+val.id+'_'+group.hotelId+'_hotel_prices_input[][]" value="'+formatPrice(0)+'" readonly>';
                        html += '<small style="display:block; text-align:center; font-size:10px;">Free | '+val.freebreakfast+'</small>';
                        html += '</div>';
                    }

                    // Display Paid Child Prices
                    if (val.chid1_price && val.chid1_price > 0) {
                        var childType1 = val.child_type1 || 'CNB';
                        var is_chk_child = '';
                        
                        // For SAVED categories: check saved data
                        if (hasSavedCategoryData) {
                            savedCatRooms.forEach(savedRoom => {
                                if (typeof savedRoom === 'string') {
                                    if (savedRoom.includes('1(C)') && savedRoom.includes(val.chid1_price.toString()) && savedRoom.includes(childType1)) {
                                        is_chk_child = 'checked="checked"';
                                        if (groupEleChk.indexOf(class_chk) === -1) {
                                            groupEleChk.push(class_chk);
                                        }
                                    }
                                }
                            });
                        }
                        // For NEW hotels: use the original logic
                        else if(!group.hasSavedData && hasCheckedOption && group.roomType.includes(childType1)) {
                            is_chk_child = 'checked="checked"';
                            if (groupEleChk.indexOf(class_chk) === -1) {
                                groupEleChk.push(class_chk);
                            }
                        }
                        
                        // ========== CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        let child1InputNames = [];
                        nightsToShow.forEach(nightNum => {
                            child1InputNames.push('night_'+nightNum+'_'+val.id+'_'+group.hotelId+'_hotel_prices[0][]');
                        });
                        // ========== END: CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        
                        html += '<div class="col-md-3 p-1" style=" padding-top: 5px;">'
                            + '<input type="checkbox" class="chk-child-prices" data-child="1" data-id="'+val.id+'_'+group.hotelId+'" value="1(C) '+val.chid1_price+' '+childType1+'" name="'+child1InputNames.join(' ')+'" '+is_chk_child+'> '
                            + '<span style="font-size: 12px;">1(C) | '+childType1+'</span>'
                            + '<input type="textbox" style="width:100%; font-size: 11px;" class="chk-prices-input" name="'+val.id+'_'+group.hotelId+'_hotel_prices_input[][]" value="'+formatPrice(val.chid1_price)+'" readonly>'
                            + '<small style="display:block; text-align:center; font-size:10px;">Age: '+val.child1_age_from+'-'+val.child1_age_to+' </small>'
                            + '</div>';
                    }

                    // Display Paid Child Prices - chid2_price
                    if (val.chid2_price && val.chid2_price > 0) {
                        var childType2 = val.child_type2 || 'CNB';
                        var is_chk_child = '';
                        
                        // For SAVED categories: check saved data
                        if (hasSavedCategoryData) {
                            savedCatRooms.forEach(savedRoom => {
                                if (typeof savedRoom === 'string') {
                                    if (savedRoom.includes('1(C)') && 
                                        savedRoom.includes(val.chid2_price.toString()) && 
                                        savedRoom.includes(childType2)) {
                                        is_chk_child = 'checked="checked"';
                                        if (groupEleChk.indexOf(class_chk) === -1) {
                                            groupEleChk.push(class_chk);
                                        }
                                    }
                                }
                            });
                        }
                        // For NEW hotels: use the original logic
                        else if(!group.hasSavedData && hasCheckedOption && group.roomType.includes(childType2)) {
                            is_chk_child = 'checked="checked"';
                            if (groupEleChk.indexOf(class_chk) === -1) {
                                groupEleChk.push(class_chk);
                            }
                        }
                        
                        // ========== CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        let child2InputNames = [];
                        nightsToShow.forEach(nightNum => {
                            child2InputNames.push('night_'+nightNum+'_'+val.id+'_'+group.hotelId+'_hotel_prices[0][]');
                        });
                        // ========== END: CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        
                        html += '<div class="col-md-3 p-1" style=" padding-top: 5px;">'
                            + '<input type="checkbox" class="chk-child-prices" data-child="2" data-id="'+val.id+'_'+group.hotelId+'" value="1(C) '+val.chid2_price+' '+childType2+'" name="'+child2InputNames.join(' ')+'" '+is_chk_child+'> '
                            + '<span style="font-size: 12px;">1(C) | '+childType2+'</span>'
                            + '<input type="textbox" style="width:100%; font-size: 11px;" class="chk-prices-input" name="'+val.id+'_'+group.hotelId+'_hotel_prices_input[][]" value="'+formatPrice(val.chid2_price)+'" readonly>'
                            + '<small style="display:block; text-align:center; font-size:10px;">Age: '+val.child2_age_from+'-'+val.child2_age_to+' </small>'
                            + '</div>';
                    }

                    // Display Paid Child Prices - chid3_price
                    if (val.chid3_price && val.chid3_price > 0) {
                        var childType3 = val.child_type3 || 'CNB';
                        var is_chk_child = '';
                        
                        // For SAVED categories: check saved data
                        if (hasSavedCategoryData) {
                            savedCatRooms.forEach(savedRoom => {
                                if (typeof savedRoom === 'string') {
                                    if (savedRoom.includes('1(C)') && 
                                        savedRoom.includes(val.chid3_price.toString()) && 
                                        savedRoom.includes(childType3)) {
                                        is_chk_child = 'checked="checked"';
                                        if (groupEleChk.indexOf(class_chk) === -1) {
                                            groupEleChk.push(class_chk);
                                        }
                                    }
                                }
                            });
                        }
                        // For NEW hotels: use the original logic
                        else if(!group.hasSavedData && hasCheckedOption && group.roomType.includes(childType3)) {
                            is_chk_child = 'checked="checked"';
                            if (groupEleChk.indexOf(class_chk) === -1) {
                                groupEleChk.push(class_chk);
                            }
                        }
                        
                        // ========== CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        let child3InputNames = [];
                        nightsToShow.forEach(nightNum => {
                            child3InputNames.push('night_'+nightNum+'_'+val.id+'_'+group.hotelId+'_hotel_prices[0][]');
                        });
                        // ========== END: CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        
                        html += '<div class="col-md-3 p-1" style=" padding-top: 5px;">'
                            + '<input type="checkbox" class="chk-child-prices" data-child="3" data-id="'+val.id+'_'+group.hotelId+'" value="1(C) '+val.chid3_price+' '+childType3+'" name="'+child3InputNames.join(' ')+'" '+is_chk_child+'> '
                            + '<span style="font-size: 12px;">1(C) | '+childType3+'</span>'
                            + '<input type="textbox" style="width:100%; font-size: 11px;" class="chk-prices-input" name="'+val.id+'_'+group.hotelId+'_hotel_prices_input[][]" value="'+formatPrice(val.chid3_price)+'" readonly>'
                            + '<small style="display:block; text-align:center; font-size:10px;">Age: '+val.child3_age_from+'-'+val.child3_age_to+'</small>'
                            + '</div>';
                    }

                    // Display Paid Child Prices - chid4_price
                    if (val.chid4_price && val.chid4_price > 0) {
                        var childType4 = val.child_type4 || 'CNB';
                        var is_chk_child = '';
                        
                        // For SAVED categories: check saved data
                        if (hasSavedCategoryData) {
                            savedCatRooms.forEach(savedRoom => {
                                if (typeof savedRoom === 'string') {
                                    if (savedRoom.includes('1(C)') && 
                                        savedRoom.includes(val.chid4_price.toString()) && 
                                        savedRoom.includes(childType4)) {
                                        is_chk_child = 'checked="checked"';
                                        if (groupEleChk.indexOf(class_chk) === -1) {
                                            groupEleChk.push(class_chk);
                                        }
                                    }
                                }
                            });
                        }
                        // For NEW hotels: use the original logic
                        else if(!group.hasSavedData && hasCheckedOption && group.roomType.includes(childType4)) {
                            is_chk_child = 'checked="checked"';
                            if (groupEleChk.indexOf(class_chk) === -1) {
                                groupEleChk.push(class_chk);
                            }
                        }
                        
                        // ========== CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        let child4InputNames = [];
                        nightsToShow.forEach(nightNum => {
                            child4InputNames.push('night_'+nightNum+'_'+val.id+'_'+group.hotelId+'_hotel_prices[0][]');
                        });
                        // ========== END: CREATE INPUT NAMES FOR NIGHTS WITH PRICING ONLY ==========
                        
                        html += '<div class="col-md-3 p-1" style=" padding-top: 5px;">'
                            + '<input type="checkbox" class="chk-child-prices" data-child="4" data-id="'+val.id+'_'+group.hotelId+'" value="1(C) '+val.chid4_price+' '+childType4+'" name="'+child4InputNames.join(' ')+'" '+is_chk_child+'> '
                            + '<span style="font-size: 12px;">1(C) | '+childType4+'</span>'
                            + '<input type="textbox" style="width:100%; font-size: 11px;" class="chk-prices-input" name="'+val.id+'_'+group.hotelId+'_hotel_prices_input[][]" value="'+formatPrice(val.chid4_price)+'" readonly>'
                            + '<small style="display:block; text-align:center; font-size:10px;">Age: '+val.child4_age_from+'-'+val.child4_age_to+'</small>'
                            + '</div>';
                    }

                    html += '</div></div><div class="col-md-1" style="display:flex;">' +
                            '<span class="span_btn" style="margin-left:3px;">' +
                            '<button type="button" data-id="'+val.id+r_num+'" ' +
                            'style="background-color: #0a87f5;color: #FFF;height:25px;cursor:pointer;float:right;padding: 0px 5px;" ' +
                            'class="add btn-primary">+</button></span></div></div><div class="col-md-1"></div></div>';
                    
                    // If a category has checked options (either saved or new), add its checkbox to groupEleChk
                    if ((hasSavedCategoryData || hasCheckedOption) && groupEleChk.indexOf(class_chk) === -1) {
                        groupEleChk.push(class_chk);
                    }
                });
            }
            
            return html;
        }
        
        // Error handling for the function
        try {
            // Any additional initialization code here
        } catch (error) {
            console.error('Error in individual_hotels_categories_new:', error);
            alert('An error occurred while loading hotel categories. Please try again.');
        }
    }
    
        
        function getTimeAsNumberOfMinutes(time){
            var timeParts = time.split(":");
            var timeInMinutes = parseInt((timeParts[0] * 60)) + parseInt(timeParts[1]);
            return timeInMinutes;
        }
        
