                function new_row(id, obj, arr_all, data_idx, j, counts, $sepHotel) {
            var n = parseInt($(".rooms_cnt_" + id).length);

            var x = Math.floor((Math.random() * 10000) + 1);

            var h = $("#prices-div_" + id).clone().attr('id', 'prices-div_' + x);
            h.find('input:checkbox').prop('checked', false);
            h.find('input[type="number"]').val("");

            // Update checkbox names
            h.find('.chk-prices').each(function () {
                $(this).attr('name', 'night_' + j + '_' + data_idx + '_hotel_prices[' + n + '][]');
            });

            // Split occupancy string
            var q = obj.split(",");

            let allPresent = q.every(val => arr_all.includes(val));
            if (allPresent) {
                var child_idx = 0;
                $.each(q, function (w, ob) {
                    const checkbox = h.find(
                        'input:checkbox[name="night_' + j + '_' + data_idx + '_hotel_prices[' + n + '][]"][data-person="' + ob + '"][data-id="' + data_idx + '"]'
                    );
                    var idx_num = 0;
                    if (ob == "1(C)") idx_num = child_idx;

                    if (checkbox.length) {
                        checkbox.eq(idx_num).prop('checked', true);
                        $("#chk_" + data_idx).prop("checked", true);
                        if (ob == "1(C)") child_idx++;
                    }
                });
            }

            // Add remove button
            h.find(".span_btn").html(
                '<i title="Remove" class="bi bi-x-lg div_remove" style="color:red;cursor: pointer;padding:6px 4px;"></i>'
            );
            h.find(".div-category").html("");

            // ✅ use the passed separate_hotel reference
            var parentRow = $sepHotel
                .closest(".row")
                .next(".row.mt-2");

            // Determine occupancy type (like "1(A)", "2(A)", etc.)
            var occupancyType = q[0]; // since obj = "1(A)" or "2(A)" etc.

            // ✅ set room count according to counts
            if (counts[occupancyType] !== undefined) {
                h.find(".rooms-cnt").val(counts[occupancyType]);
            }

            if (h.find("input:checkbox:checked").length > 0) {
                var target = parentRow.find(".prices-div-" + id);

                if (occupancyType === "1(A)") {
                    if (target.length > 0) {
                        h.insertBefore(target.first());
                        console.log("✅ Row inserted before first target for 1(A)");
                    } else {
                        parentRow.append(h);
                        console.log("✅ Row appended (no target found) for 1(A)");
                    }
                } else {
                    if (target.length > 0) {
                        h.insertAfter(target.last());
                        console.log("✅ Row inserted after last target for", occupancyType);
                    } else {
                        parentRow.append(h);
                        console.log("✅ Row appended (no target found) for", occupancyType);
                    }
                }


                console.log(
                    "➕ Row added for", occupancyType,
                    " → count set:", h.find(".rooms-cnt").val()
                );
            } else {
                console.warn("⛔ Skipped blank row (no occupancy selected) for obj:", obj);
            }
        }
        
