        $("#frm_1").on("change", '.qtn-transfer', function(e) {
            var idx = $(this).index(".qtn-transfer");
            var CityInputVal = $(this).closest(".row").find(".qtn-city").val();
            let arrival_city = $('#flight-city-initial-arrival').val();
            let countryname = getCountryFromEnquiry(qdata.enquiry_abbr);
            let $transfer = $(this);
            let $row = $transfer.closest(".row");

            if($transfer.val() === "train"){
                $row.find(".overnight-type").hide();
                $row.find(".overnight-type input[type='radio']").prop("checked", false);
                $row.next(".local-train").slideDown(1000);
                $row.find(".with-train").css("display", "block");
            }else{
                
                if (countryname === 'kazakhstan' || countryname === 'georgia') {
                        $row.find(".overnight-type").show();
                        $row.find(".with-train input[type='radio'][value='yes']").prop("checked", true);
                        $row.find(".overnight-type input[value='overnight']").prop("checked", true).prop("disabled", false);
                        $row.find(".overnight-type input[value='drop_off']").prop("disabled", true).prop("checked", true);
                        if (CityInputVal.toLowerCase() === arrival_city.toLowerCase()) {
                            $row.find(".with-train").css("display", "none");
                        }else{
                            $row.find(".with-train").css("display", "block");
                        }
                    
                } 
                else if (countryname === 'uzbekistan') {
                    // Set Drop Off checked, disable Overnight
                    $row.find(".overnight-type").show();
                    // $row.find(".with-train").css("display", "block");
                    if (CityInputVal.toLowerCase() === arrival_city.toLowerCase()) {
                        $row.find(".with-train").css("display", "none");
                    }else{
                        $row.find(".with-train").css("display", "block");
                    }
                    $row.find(".overnight-type input[value='drop_off']").prop("checked", true).prop("disabled", false);
