        // Clone route-change-section when "+" is clicked
        $(document).on('click', '.add-route', function() {
            var $originalSection = $(this).closest('.route-change-section');
            var dayIndex = $originalSection.data('day');
            
            // Count all sections for this day (including the original)
            var sectionsForDay = $('.route-change-section[data-day="' + dayIndex + '"]');
            var newSectionIndex = sectionsForDay.length; // e.g., if there are 2, next index = 2
            
            var $clone = $originalSection.clone();
            
            // Update data-section attribute
            $clone.attr('data-section', newSectionIndex);
            
            // Update all form field names in the clone
            $clone.find('[name]').each(function() {
                var $this = $(this);
                var oldName = $this.attr('name');
                // Replace the section index part in the name: route_changes[day][old_section][field] -> route_changes[day][newSectionIndex][field]
                var newName = oldName.replace(/\[\d+\]\[(\d+)\]/, '[' + dayIndex + '][' + newSectionIndex + ']');
                $this.attr('name', newName);
            });
            
            // Clear all input, select, and hidden values
            $clone.find('input[type="text"], input[type="hidden"], select').val('');
            // Reset radio buttons
            $clone.find('input[type="radio"]').prop('checked', false);
            // Set default radio values
            $clone.find('input[type="radio"][value="overnight"]').prop('checked', true);
            $clone.find('input[type="radio"][value="no"]').prop('checked', true);
            
            // Change the "+" button to "-" in the clone
            var $cloneButton = $clone.find('.add-route');
            $cloneButton
                .removeClass('btn-success add-route')
                .addClass('btn-danger remove-route')
                .text('-');
            
            // Insert the clone after the original
            $originalSection.after($clone);
            
            // Re-apply country rules to the new section
            var countryname = getCountryFromEnquiry(qdata.enquiry_abbr);
            applyCountryRulesToSection($clone, countryname);
            
            // Trigger change on transfer mode to show/hide train container based on default value (road)
            $clone.find('.transfer-mode').trigger('change');
        });

        // Remove cloned section when "-" is clicked
