        $(document).on('change', '.route-change-section .transfer-mode', function() {
            var $section = $(this).closest('.route-change-section');
            var $trainContainer = $section.find('.local-train');
            var $transfer = $(this);
            var countryname = getCountryFromEnquiry(qdata.enquiry_abbr);
            var $overnightContainer = $section.find('.overnight-type-container');
            var $guideRadios = $section.find('input[name^="travelling_with_guide_"]');

            if ($transfer.val() === 'train') {
                $trainContainer.slideDown();
