        });

        function applyCountryRulesToSection($section, countryname) {
            // Find the overnight radios inside this section
            var $overnightRadios = $section.find('input[name$="[overnight_type]"]');
            var $guideRadios = $section.find('input[name$="[travelling_with_guide]"]');
            
            if (countryname === 'kazakhstan' || countryname === 'georgia') {
                $guideRadios.filter('[value="yes"]').prop('checked', true);
                $overnightRadios.filter('[value="drop_off"]').prop('disabled', true);
                $guideRadios.filter('[value="no"]').prop('disabled', true);
            } else if (countryname === 'uzbekistan') {
                $overnightRadios.filter('[value="drop_off"]').prop('checked', true);
                $guideRadios.filter('[value="no"]').prop('checked', true);
            } else {
                $overnightRadios.prop('disabled', false);
                $guideRadios.prop('disabled', false);
            }
        }

        function buildRouteChangeData() 
        {
            let routeChanges = [];

            // Loop over each day (0 to qdata.nights)
            for (let i = 0; i <= qdata.nights; i++) {
                // Check if route change is enabled for this day
                let $routeChangeRadio = $(`input[name="route_change${i}"]:checked`);
                let $daytripRadio = $(`input[name="day_trip${i}"]:checked`);
                // if ($routeChangeRadio.length === 0 || $routeChangeRadio.val() !== "yes") {
                //     continue; // Skip days where route change is not "yes"
                // }
                
                if (
                    ($routeChangeRadio.length === 0 || $routeChangeRadio.val() !== "yes") &&
                    ($daytripRadio.length === 0 || $daytripRadio.val() !== "yes")
                ) {
                    continue; // skip only if BOTH are NOT yes
                }

                // Find all route-change sections for this day
                let $sections = $(`.route-change-section[data-day="${i}"]`);

                $sections.each(function (sectionIdx) {
                    let $section = $(this);
                    let sectionData = {
                        day: i + 1,           // 1‑based day number (for readability)
                        section: sectionIdx,   // 0‑based section index within the day
                        from_city: $section.find('.from-city').val() || '',
                        to_city: $section.find('.to-city').val() || '',
                        transfer_mode: $section.find('.transfer-mode').val() || '',
                        overnight_type: $section.find('input[name$="[overnight_type]"]:checked').val() || '',
                        travel_with_guide: $section.find('input[name$="[travelling_with_guide]"]:checked').val() || ''
                    };

                    // If transfer mode is train, collect additional train details
                    if (sectionData.transfer_mode === 'train') {
                        let $trainRow = $section.find('.local-train');
                        sectionData.train_id = $trainRow.find('.train-id').val() || '';
                        sectionData.ticket_type = $trainRow.find('.ticket-type').val() || '';

                        // Parse train timing text (example: "🕒 Depart: 10:00 | Arrive: 12:00")
                        let timingText = $trainRow.find('.train-timing').text();
                        let departMatch = timingText.match(/Depart:\s*(\S+)/i);
                        let arriveMatch = timingText.match(/Arrive:\s*(\S+)/i);
                        if (departMatch) sectionData.train_depart = departMatch[1];
                        if (arriveMatch) sectionData.train_arrive = arriveMatch[1];
                    }

                    routeChanges.push(sectionData);
                });
            }

            // Store the collected data in a hidden field
            $('#routeChangeData').val(JSON.stringify(routeChanges));
            console.log('Route Change Data:', routeChanges);
            updateItineraryPlaceholders();
            updateItineraryRouteAndTime();
        }

        function updateItineraryPlaceholders() 
        {
            let routeData = JSON.parse($('#routeChangeData').val() || '[]');
            let dayMap = {};
            routeData.forEach(item => {
                if (!dayMap[item.day]) dayMap[item.day] = [];
                dayMap[item.day].push(item);
            });
            
            $(".add-itinerary").each(function () {
                let dayIndex = $(this).data("dayindex");
                let items = dayMap[dayIndex];
                if (items && items.length) {
                    // Sort by section index
                    items.sort((a, b) => a.section - b.section);
                    // Build chain: start with first from_city, then add each to_city
                    let chain = [items[0].from_city];
                    items.forEach(item => {
                        chain.push(item.to_city);
                    });
                    // Remove duplicates if consecutive (optional)
                    let uniqueChain = [];
                    for (let i = 0; i < chain.length; i++) {
                        if (i === 0 || chain[i] !== chain[i-1]) {
                            uniqueChain.push(chain[i]);
                        }
                    }
                    let routeText = uniqueChain.join(' → ');
                    $(this).attr("placeholder", `Search & Add Itinerary (${routeText})`);
                } 
            });
        }

        function updateItineraryRouteAndTime() 
        {
            let routeData = JSON.parse($('#routeChangeData').val() || '[]');

            // Group data day-wise
            let dayMap = {};
            routeData.forEach(item => {
                if (!dayMap[item.day]) {
                    dayMap[item.day] = [];
                }
                dayMap[item.day].push(item);
            });

            // Loop each day
            Object.keys(dayMap).forEach(day => {

                let items = dayMap[day];

                // Sort by section (important for correct order)
                items.sort((a, b) => a.section - b.section);

                // =========================
                // ✅ Build Route Chain
                // =========================
                let chain = [items[0].from_city];

                items.forEach(item => {
                    chain.push(item.to_city);
                });

                // Remove consecutive duplicates
                let uniqueChain = [];
                for (let i = 0; i < chain.length; i++) {
                    if (i === 0 || chain[i] !== chain[i - 1]) {
                        uniqueChain.push(chain[i]);
                    }
                }

                let routeText = uniqueChain.join(' → ');

                // =========================
                // ✅ Train Timing (Row-wise)
                // =========================
                let trainText = '';
                let trainItems = items.filter(i => i.transfer_mode === 'train');

                trainItems.forEach(t => {
                    let from = t.from_city || '';
                    let to = t.to_city || '';
                    let depart = t.train_depart || '';
                    let arrive = t.train_arrive || '';

                    let timePart = '';

                    if (depart && arrive) {
                        timePart = `(Departure- ${depart} → Arrival- ${arrive})`;
                    } 
                    else if (depart) {
                        timePart = `(Departure- ${depart})`;
                    } 
                    else if (arrive) {
                        timePart = `(Arrival- ${arrive})`;
                    }

                    if (from && to) {
                        trainText += `<br>Train Timing: ${from} → ${to} ${timePart}`;
                    }
                });

                // =========================
                // ✅ Final Output
                // =========================
                let finalHTML = `
                    ${routeText}
                    ${trainText}`;

                // =========================
                // ✅ Update UI
                // =========================
                let $header = $(`a[href="#collapse${day}"] span.itinerary_date`);
                if ($header.length) {
                    $header.find('.route-time-indicator').remove();
                    $header.append(`
                        <span class="route-time-indicator" 
                            style="margin-left:15px; color:#28a745; font-weight:700; display:block;">
                            ${finalHTML}
                        </span>
                    `);
                }
            });
        }

        
        
        $(document).on('keydown.autocomplete', ".train-search", function () {
            let $trainInput = $(this);
            let $trainRow   = $trainInput.closest('.row.local-train');
            let $section    = $trainRow.closest('.route-change-section');
            let isRouteChange = $section.length > 0;

            let fromCity, toCity, dayNo, dayName, arrival_city = $('#flight-city-initial-arrival').val();

            if (isRouteChange) {
                // ---------- Route‑change section ----------
                fromCity = $section.find('.from-city').val() || '';
                toCity   = $section.find('.to-city').val() || '';
                let dayIdx = $section.data('day');          // 0‑based day index (set when section was created)
                dayNo = dayIdx + 1;                         // 1‑based day number for display / localStorage

                // Retrieve day name from localStorage (stored earlier)
                let stored = localStorage.getItem("day_" + dayNo);
                if (stored) {
                    let parsed = JSON.parse(stored);
                    dayName = parsed.dayName;
                } else {
                    dayName = ''; // fallback – maybe use a default
                }
            } else {
                // ---------- Normal day (original logic) ----------
                let $validRows = $trainRow.prevAll('.row.mt-2').not('.local-train');

                // TO CITY row (the row containing the city input for this day)
                let $toRow = $validRows.eq(0);
                toCity = $toRow.find('.qtn-city').val();
                dayName = $toRow.find('.qtn-city').data('dayname');

                // Extract day number from "Day X City" text
                let dayText = $toRow.find('span.bold').first().text();
                let dayMatch = dayText.match(/\d+/);
                dayNo = dayMatch ? parseInt(dayMatch[0]) : null;

                // FROM CITY row (previous day's city or arrival city)
                let $fromRow = $validRows.eq(1);
                fromCity = $fromRow.find('.qtn-city').val() || arrival_city;
            }

            // Stop if essential data is missing
            if (!toCity || !fromCity || !dayNo) {
                console.warn('Train search: missing city or day info');
                return;
            }

            // Create hidden fields if they don't exist (they will be used to store train_id and day_no)
            if ($trainInput.next('.train-id').length === 0) {
                $trainInput.after('<input type="hidden" class="train-id" name="train_id[]">');
            }
            if ($trainInput.nextAll('.train-day-no').length === 0) {
                $trainInput.after('<input type="hidden" class="train-day-no" name="train_day_no[]">');
            }

            const selectedCountry = getCountryFromEnquiry(qdata.enquiry_abbr);

            // Map day name to database column prefix
            const dayMap = {
                'monday': 'mon', 'tuesday': 'tue', 'wednesday': 'wed',
                'thursday': 'thu', 'friday': 'fri', 'saturday': 'sat', 'sunday': 'sun'
            };
            let dayPrefix = dayMap[dayName] || '';

            $trainInput.autocomplete({
                minLength: 1,
                source: function (request, response) {
                    $.ajax({
                        url: "<?= base_url() ?>admin/quotation/get_trains",
                        type: "POST",
                        dataType: "json",
                        data: {
                            search: request.term,
                            from_city: fromCity,
                            to_city: toCity,
                            country: selectedCountry
                        },
                        success: function (data) {
                            response(data);
                        }
                    });
                },
                select: function (event, ui) {
                    $trainInput.val(ui.item.label);
                    $trainInput.nextAll('.train-id').first().val(ui.item.train_id);
                    $trainInput.nextAll('.train-day-no').first().val(dayNo);

                    // Populate ticket types dropdown
                    let $ticketSelect = $trainRow.find('.ticket-type');
                    $ticketSelect.empty();
                    $ticketSelect.append('<option value="">Select Ticket Type</option>');
                    if (Array.isArray(ui.item.types)) {
                        ui.item.types.forEach(function (type) {
                            let label = type.replace(/_/g, ' ').toUpperCase();
                            $ticketSelect.append(`<option value="${type}">${label}</option>`);
                        });
                    }

                    // Display train timing for the selected day
                    let $timingDisplay = $trainRow.find('.train-timing');
                    if ($timingDisplay.length === 0) {
                        $timingDisplay = $('<span class="train-timing" style="margin-left:15px; font-size:12px; color:#333;"></span>');
                        $ticketSelect.after($timingDisplay);
                    }
                    if (dayPrefix) {
                        let depTime = ui.item[dayPrefix + '_dep_time'] || '';
                        let arrTime = ui.item[dayPrefix + '_arr_time'] || '';
                        if (depTime || arrTime) {
                            $timingDisplay.html('🕒 Depart: ' + depTime + ' | Arrive: ' + arrTime);
                        } else {
                            $timingDisplay.html('⚠️ No schedule for this day');
                        }
                    } else {
                        $timingDisplay.html('');
                    }

                    // If you have a function to update the itinerary header with train times, call it here
                    // updateItineraryTrainTimes();

                    return false;
                }
            });
        });

