        function buildDayWiseTransferData() 
        {
            let result = [];

            $(".qtn-city").each(function () {
                let $cityInput = $(this);
                let cityVal    = $cityInput.val().trim();

                if (!cityVal) return;

                let $row = $cityInput.closest(".row");

                // let $routeChangeDiv = $row.find(".route-change");
                // let $dayTrip = $row.find(".day_trip");
                // if ($routeChangeDiv.hasClass("hide")) {
                //     return; // day not included
                // }

                // Skip if transfer select is hidden
                let $transferSelect = $row.find(".qtn-transfer:visible");
                // if (!$transferSelect.length) return;

                let transferMode = $transferSelect.val();

                let isOvernightVisible = $row.find(".overnight-type").is(":visible");
                let isTravellingVisible = $row.find(".with-train").is(":visible");
                let isRouteChange = $row.find(".route-change").is(":visible");

                // Extract day number from "Day X City"
                let dayText  = $row.find("span.bold").first().text().trim();
                let dayMatch = dayText.match(/Day\s+(\d+)/i);
                let dayNo    = dayMatch ? parseInt(dayMatch[1]) : null;

                if (!dayNo) return; 
                
                // let overnightType = $row.find('input[name="overnight_type_'+(dayNo-1)+'"]:checked').val();
                // let trevelling_with_guide = $row.find('input[name="trevelling_with_guide_'+(dayNo-1)+'"]:checked').val();
                // use values only if visible
                let overnightType = isOvernightVisible
                    ? $row.find(`input[name="overnight_type_${dayNo-1}"]:checked`).val()
                    : '';

                let trevelling_with_guide = isTravellingVisible
                    ? $row.find(`input[name="trevelling_with_guide_${dayNo-1}"]:checked`).val()
                    : '';
                let routeChange = $row.find('input[name="route_change'+(dayNo-1)+'"]:checked').val();
                let daytrip = $row.find('input[name="day_trip'+(dayNo-1)+'"]:checked').val();

                let isRouteVisible = !$row.find(".route-change").hasClass("hide");

                // FINAL LOGIC
                if (!(daytrip === "yes" || routeChange === "yes" || isRouteVisible)) {
                    return;
                }

                let dayData = {
                    day: dayNo,
                    transfer_mode: transferMode,
                    daytrip: daytrip
                };

                if(isTravellingVisible){
                    dayData.travel_with_guide = trevelling_with_guide;
                }

                if(overnightType){
                    dayData.overnight_type = overnightType;
                }

                if(isRouteChange){
                    dayData.route_change = routeChange;
                }

                // If train → get train_id and timing from the next local-train row
                if (transferMode === "train") {
                    let $trainRow = $row.next(".local-train");
                    let trainId   = $trainRow.find(".train-id").val();
                    let ticketType = $trainRow.find(".ticket-type").val();

                    if (trainId) {
                        dayData.train_id = trainId;
                    }

                    if (ticketType) {
                        dayData.type = ticketType;
                    }

                    // Extract train departure and arrival times from the timing span
                    let $timingSpan = $trainRow.find(".train-timing");
                    if ($timingSpan.length) {
                        let timingText = $timingSpan.text();
                        // Format example: "🕒 Depart: 10:00 | Arrive: 12:00"
                        let departMatch = timingText.match(/Depart:\s*(\S+)/i);
                        let arriveMatch = timingText.match(/Arrive:\s*(\S+)/i);
                        if (departMatch) {
                            dayData.train_depart = departMatch[1];
                        }
                        if (arriveMatch) {
                            dayData.train_arrive = arriveMatch[1];
                        }
                    }
                }

                result.push(dayData);
            });

            // Store JSON in hidden field
            $("#dayWiseTransferData").val(JSON.stringify(result));
            
            // Also update the itinerary display with any train times
            updateItineraryTrainTimes();
        }


        function updateItineraryTrainTimes() 
        {
            $(".qtn-city").each(function () {

                let $cityRow = $(this).closest(".row");

                // Get day number
                let daySpan = $cityRow.find("span.bold").first();
                let dayText = daySpan.text().trim();
                let dayMatch = dayText.match(/Day\s*:?\s*(\d+)/i);
                if (!dayMatch) return;

                let dayNo = dayMatch[1];

                // Check transfer mode
                let transferSelect = $cityRow.find(".qtn-transfer").val();
                if (transferSelect !== "train") return;

                // Train row
                let $trainRow = $cityRow.next(".local-train");
                let $timingSpan = $trainRow.find(".train-timing");
                if ($timingSpan.length === 0) return;

                // =========================
                // ✅ GET FROM & TO CITY
                // =========================

                let toCity = $cityRow.find('.qtn-city').val();

                let $prevRow = $cityRow.prevAll('.row.mt-2').not('.local-train').first();
                let fromCity = $prevRow.find('.qtn-city').val();

                // fallback (arrival city)
                if (!fromCity) {
                    fromCity = $('#flight-city-initial-arrival').val();
                }

                // =========================
                // ✅ GET TIMING
                // =========================

                let timingText = $timingSpan.text();

                let departMatch = timingText.match(/Depart:\s*(\S+)/i);
                let arriveMatch = timingText.match(/Arrive:\s*(\S+)/i);

                let timeStr = '';

                if (departMatch && arriveMatch) {
                    timeStr = `Train Timing: ${fromCity} → ${toCity} (Departure- ${departMatch[1]} → Arrival- ${arriveMatch[1]})`;
                } 
                else if (departMatch) {
                    timeStr = `Train Timing: ${fromCity} → ${toCity} (Departure- ${departMatch[1]})`;
                } 
                else if (arriveMatch) {
                    timeStr = `Train Timing: ${fromCity} → ${toCity} (Arrival- ${arriveMatch[1]})`;
                }

                // =========================
                // ✅ UPDATE UI
                // =========================

                if (timeStr) {
                    let $itineraryHeader = $(`a[href="#collapse${dayNo}"] span.bold.itinerary_date`);

                    if ($itineraryHeader.length) {
                        $itineraryHeader.find('.train-time-indicator').remove();

                        $itineraryHeader.append(`
                            <span class="train-time-indicator" 
                                style="margin-left:15px; color:#28a745; font-weight:700;">
                                ${timeStr}
                            </span>
                        `);
                    }
                }
            });
        }

        
        $(".airline").on("change",function(){
            var idx = $(this).index(".airline");
            $(".airline-show").eq(idx).slideUp("1000").slideDown("2000");
            var d = JSON.parse($(".airline option:selected").eq(idx).attr("data-attr"));
            var city = flight_time = '';
            if(idx == 0){ 
                city = d.arrival_city;
                flight_time = d.arrival_time;
                $("#hdn_arrival_time").val(flight_time);

                const date1 = new Date();
                const compare_arrival_time = new Date(date1.getFullYear()+"-"+date1.getMonth()+1+"-"+(date1.getDate() + '').padStart( 2, '0' )+'T08:00:00').getTime();
                const flight_arrival_time = new Date(date1.getFullYear()+"-"+date1.getMonth()+1+"-"+(date1.getDate() + '').padStart( 2, '0' )+'T'+flight_time+':00').getTime();
                $("#early_checkin").prop("checked",false).attr("disabled","disabled");
                if(flight_arrival_time < compare_arrival_time){
                    $("#early_checkin").removeAttr("disabled");
                }
            }else{ 
                city = d.arrival_city;
                flight_time = d.departure_time;
                $("#hdn_departure_time").val(flight_time);
            }

            $(".info-city").eq(idx).text(city);
            $(".info-time").eq(idx).text(flight_time);
        });

