        function getRouteCitiesForDay(dayIndex) {
            let routeData = [];
            try {
                routeData = JSON.parse($('#routeChangeData').val() || '[]');
            } catch(e) {
                console.warn('Invalid routeChangeData JSON');
                return [];
            }
            const cities = new Set();
            routeData.forEach(item => {
                if (item.day === dayIndex) {
                    if (item.from_city) cities.add(item.from_city);
                    if (item.to_city) cities.add(item.to_city);
                }
            });
            return Array.from(cities);
        }

        $(document).on('keydown.autocomplete', ".add-itinerary", function() {
            let $this = $(this);
            
            let dayIndex = $this.data("dayindex");

            let cityName = $('.qtn-city[data-dayindex="' + dayIndex + '"]').val();
            let prevDayIndex = dayIndex - 1;
            let prevCity = prevDayIndex > 0 ? $('.qtn-city[data-dayindex="' + prevDayIndex + '"]').val() : '';

            let routeCities = getRouteCitiesForDay(dayIndex);

            $(this).autocomplete({                
                source: function (request, response) {
                    // Fetch data
                    $.ajax({
                        url: "<?= base_url() ?>admin/quotation/get_sites",
                        type: 'post',
                        dataType: "json",
                        data: {
                            search: request.term,
                            enq_no: $(".qdata").eq(0).text(),
                            city: cityName,
                            prev_city: prevCity,
                            route_cities: routeCities.join(',')
                        },
                        success: function (data) {
                            response(data);
                        }
                    });
                },
                select: function (event, ui) {
                    // Set selection
                    var idx = $(this).index(".add-itinerary");
                    var entryFeeText = '';

                    if (ui.item.entry_ticket == 'yes') 
                    {
                        if ((ui.item.entry_ticket_fee && ui.item.entry_ticket_fee != 0) || 
                            (ui.item.child_entry_ticket_fee && ui.item.child_entry_ticket_fee != 0)) 
                        {
                            entryFeeText = 'Entry Fee: ' + (ui.item.entry_ticket_fee || '0') + ' (A) ' +
                                        (ui.item.child_entry_ticket_fee || '0') + ' (C)';
                        } 
                        else 
                        {
                            entryFeeText = 'Entry Fee: ' + (ui.item.group_entry_ticket_fee || '0') + ' (Group)';
                        }
                    }
                    var act = (entryFeeText ? entryFeeText + ' | ' : '') +'<button type="button" data-site-id="'+ui.item.id+'" class="btn btn-link activities" style="padding:0;">Add Activities</button> | <button type="button" data-site-id="'+ui.item.id+'" class="btn btn-link entrance" style="padding:0;">Add Entrance</button>';
                    //var act = 'Entry Fee : '+((ui.item.entry_ticket_fee!=0)?ui.item.entry_ticket_fee+' (A) ':'')+ ((ui.item.child_entry_ticket_fee!=0)?ui.item.child_entry_ticket_fee+' (C) ':'')+' | <button type="button" class="btn btn-sm btn-link activities" style="padding:0;">Add Activities</button>';
                    // var act = 'Entry Fee : '+(ui.item.entry_ticket_fee+' (A) ') + (ui.item.child_entry_ticket_fee+' (C) ')+' | <button type="button" data-site-id="'+ui.item.id+'" class="btn btn-link activities" style="padding:0;">Add Activities</button> | <button type="button" data-site-id="'+ui.item.id+'" class="btn btn-link entrance" style="padding:0;">Add Entrance</button>';
                    $(".itinerary_ul").eq(idx).append("<li style='display:inline-flex;'><input type='hidden' name='hdn_site_id["+idx+"][]' value='"+ui.item.id+"'><i class='fa fa-circle fa-xs' style='margin:6px;'></i><input type='hidden' name='hdn_itinerary_content["+idx+"][]' value='"+ui.item.label+"'><div>"+ui.item.label+" <br>("+act+")</div><i title='Remove' class='bi bi-x-lg edit-remove' style='color:red;cursor: pointer;float: right;margin-top: 5px;position:relative;'></i><input type='hidden' class='activities-list' name='hdn_activities["+idx+"][]' value=''><input type='hidden' class='entrance-data' name='hdn_entrance_data["+idx+"]["+ui.item.id+"]' value=''></li>");
