       $(document).on('keydown.autocomplete', ".qtn-city", function() {
            $(this).autocomplete({                
                source: function (request, response) {
                    // Fetch data
                    $.ajax({
                        url: "<?= base_url() ?>admin/quotation/get_cities",
                        type: 'post',
                        dataType: "json",
                        data: {
                            search: request.term,
                            enq_no: $(".qdata").eq(0).text()
                        },
                        success: function (data) {
                            response(data);
                        }
                    });
                },
                
                select: function (event, ui) {
                    var idx = $(this).index(".qtn-city");
                    var $cityInput = $(".qtn-city").eq(idx);
                    var parentRow = $cityInput.closest(".row");

                    // Set the selected city value
                    $cityInput.val(ui.item.label);
                    $cityInput.attr('data-city-valid', 'true');
                    $cityInput.attr("data-suburb", ui.item.suburb_flag);

                    // Get arrival city (adjust selector as needed)
                    var arrival_city = $("[name='arrival_city']").val().trim();

                    // Get day number from the row
                    var dayText = parentRow.find("span.bold").first().text().trim();
                    var dayMatch = dayText.match(/Day\s+(\d+)/i);
                    var dayNo = dayMatch ? parseInt(dayMatch[1]) : null;
                    if (!dayNo) return false;

                    // Get country name (adjust based on your storage)
                    var countryname = window.countryname || getCountryFromEnquiry(qdata.enquiry_abbr) || '';

                    // Check if all .qtn-city are the same
                    var allCities = $(".qtn-city").map(function () {
                        return $(this).val().trim().toLowerCase();
                    }).get().filter(Boolean); // remove empty

                    if (allCities.length > 0) {
                        var firstCity = allCities[0];
                        var allSame = allCities.every(function (c) { return c === firstCity; });

                        if (allSame) {
                            console.warn("All cities are the same (" + firstCity + "), removing related sites.");
                            $(".itinerary_ul li[data-related-site]").remove();
                            localStorage.removeItem("differentCities"); // clear storage too
                            return; 
                        }
                    }

                    // Set selected city
                    $cityInput.val(ui.item.label);
                    $cityInput.attr("data-suburb", ui.item.suburb_flag);

                    var arrivalCity = $("[name='arrival_city']").val().trim().toLowerCase();
                    var differentCities = [];

                    // Collect different cities with their Day numbers
                    $(".qtn-city").each(function () {
                        var city = $(this).val().trim().toLowerCase();
                        if (city && city !== arrivalCity) {
                            var row = $(this).closest(".row");
                            var dayText = row.find("span.bold").first().text().trim();
                            var dayMatch = dayText.match(/Day\s+(\d+)/i);
                            var dayNo = dayMatch ? dayMatch[1] : "unknown";

                            differentCities.push({
                                day: "Day " + dayNo,
                                city: $(this).val().trim()
                            });
                        }
                    });

                    // Store or clear localStorage
                    if (differentCities.length > 0) {
                        localStorage.setItem("differentCities", JSON.stringify(differentCities));
                        console.log("Saved in localStorage:", differentCities);
                    } else {
                        localStorage.removeItem("differentCities");
                    }

                    // Process different cities
                    var diffCities = JSON.parse(localStorage.getItem("differentCities") || "[]");

                    // Step 1: Group by city (case-insensitive)
                    var grouped = {};
                    diffCities.forEach(function (item) {
                        var cityName = item.city.trim();
                        var dayNumber = parseInt(item.day.replace("Day", "").trim(), 10);

                        var key = cityName.toLowerCase(); // normalize key
                        if (!grouped[key]) {
                            grouped[key] = { name: cityName, days: [] };
                        }
                        grouped[key].days.push(dayNumber);
                    });

                    // Loop each city only once
                    Object.keys(grouped).forEach(function (key) {
                        var cityData = grouped[key];
                        var cityName = cityData.name;
                        var days = cityData.days;

                        // Pick earliest day
                        var targetDay = Math.min.apply(null, days);
                        var totalDays = $(".itinerary_ul").length;

                        // Count how many times this city appears
                        var count = $(".qtn-city").filter(function () {
                            return $(this).val().trim().toLowerCase() === cityName.toLowerCase();
                        }).length;

                        console.log("City:", cityName, "| Target Day:", targetDay, "| Nights (count):", count);

                        // AJAX call
                        $.ajax({
                            url: "<?= base_url('admin/quotation/checkCityNights') ?>",
                            type: "POST",
                            dataType: "json",
                            data: { city: cityName, nights: count },
                            success: function (res2) {
                                // console.log(res2,'res2');
                                if (res2.status === "success" && res2.related_sites) {
                                    let relatedKeys = Object.keys(res2.related_sites);

                                    if (targetDay === totalDays) {
                                        console.warn("Target day is the last day (" + targetDay + "), skipping all related_sites.");
                                        return;
                                    }

                                    $(".itinerary_ul li[data-related-site][data-city='" + cityName + "']").remove();

                                    // remove old related sites for these days
                                    for (let i = 0; i < relatedKeys.length; i++) {
                                        let dayIndex = targetDay + i;
                                        $("#collapse" + dayIndex + " li[data-related-site][data-city='" + cityName + "']").remove();
                                    }

                                    // Append new sites
                                    relatedKeys.forEach(function (dayKey, index) {
                                        var sites = res2.related_sites[dayKey];
                                        var appendDay = targetDay + index;

                                        if (appendDay === totalDays && index > 0) {
                                            console.warn("Skipping " + dayKey + " because last day reached:", appendDay);
                                            return;
                                        }
                                        
                                        var siteDay = appendDay - 1;

                                        var $ul = $("#collapse" + appendDay);
                                        if ($ul.length > 0) {
                                            sites.forEach(function (site) {
                                                var liHtml = `
                                                    <li data-related-site data-city="${cityName}" style="display:inline-flex; list-style-type: circle">
                                                        <input type="hidden" name="hdn_site_id[${siteDay}][]" value="${site.id}">
                                                        <i class="fa fa-circle-o" style="margin:6px;"></i>
                                                        <input type="hidden" name="hdn_itinerary_content[${siteDay}][]" value="${site.site_name}">
                                                        <div>
                                                            ${site.site_name}
                                                            <br>(Entry Fee : ${site.entry_ticket_fee} (A) ${site.child_entry_ticket_fee} (C) |
                                                            <button type="button" data-site-id="${site.id}" class="btn btn-sm btn-link activities" style="padding:0;">Add Activities</button>)
                                                        </div>
                                                        <i title="Remove" class="bi bi-x-lg edit-remove" style="color:red;cursor: pointer;float: right;margin-top: 5px;position:relative;"></i>
                                                        <input type="hidden" class="activities-list" name="hdn_activities[${siteDay}][]" value="">
                                                    </li>
                                                `;
                                                $ul.append(liHtml);
                                            });
                                            console.log("Appended", dayKey, "into collapse" + appendDay);
                                        } else {
                                            console.warn("UL not found for target", appendDay);
                                        }
                                    });
                                }
                            }
                        });
                    });

                    applyRoadTransferRules(parentRow, countryname, $cityInput.val().trim(), arrival_city, dayNo);

                    // Show/Hide logic
                    if ($cityInput.attr("data-suburb") == "true" && idx !== 0 && $cityInput.val() !== $(".qtn-city").eq(idx - 1).val()) {
                        parentRow.find(".qtn-transfer").parent().removeClass("hide");
                        parentRow.find(".route-change").parent().removeClass("hide");
                        parentRow.find(".route-change").css("display", "block");
                        parentRow.find(".day_trip").removeClass("hide");
                        // parentRow.find(".qtn-transfer-date").closest(".col-md-6").removeClass("hide");
                    } else if ($cityInput.attr("data-suburb") == "true" && idx !== 0) {
                        parentRow.find(".qtn-transfer").parent().addClass("hide");
                        parentRow.find(".overnight-type").addClass("hide");
                        parentRow.find(".route-change").addClass("hide");
                        parentRow.find(".day_trip").removeClass("hide");
                        // parentRow.find(".qtn-transfer-date").closest(".col-md-6").addClass("hide");
                    } else if ($cityInput.attr("data-suburb") == "false" && idx !== 0) {
                        parentRow.find(".qtn-transfer").parent().removeClass("hide");
                        parentRow.find(".overnight-type").removeClass("hide");
                        parentRow.find(".route-change").removeClass("hide");
                        parentRow.find(".route-change").css("display", "block");
                        parentRow.find(".overnight-type").css("display", "block");
                        parentRow.find(".with-train").css("display", "block");
                        parentRow.find(".day_trip").removeClass("hide");
                        if (countryname === 'kazakhstan' || countryname === 'georgia') {
                            parentRow.find(".with-train input[type='radio'][value='yes']").prop("checked", true);
                        }else{
                            parentRow.find(".with-train input[type='radio'][value='no']").prop("checked", true);
                        }
                        // parentRow.find(".qtn-transfer-date").closest(".col-md-6").removeClass("hide");
                    }

                    updateCityUIOnSelection($cityInput);
                    
                    var currentIdx = $cityInput.index(".qtn-city");
                    var $nextCityInput = $(".qtn-city").eq(currentIdx + 1);
                    if ($nextCityInput.length) {
                        updateCityUIOnSelection($nextCityInput);
                    }

                    return false;
                }   
                
            });
        });    
    
        $(document).on('keydown.autocomplete', ".from-city, .to-city", function() {
            $(this).autocomplete({
                source: function (request, response) {
                    $.ajax({
                        url: "<?= base_url() ?>admin/quotation/get_cities",
                        type: 'post',
                        dataType: "json",
                        data: {
                            search: request.term,
                            enq_no: $(".qdata").eq(0).text()
                        },
                        success: function (data) {
                            response(data);
                        }
                    });
                },
                select: function (event, ui) {
                    // Set the selected city value
                    $(this).val(ui.item.label);

                    return false;
                }
            });
        });

        /*
        |--------------------------------------------------------------------------
        | Remove saved itinerary when day city changes
        |--------------------------------------------------------------------------
        */

        let savedCityItineraryWatchReady = false;

        function normalizeItineraryCity(city) {
            return String(city || '')
                .trim()
                .replace(/\s+/g, ' ')
                .toLowerCase();
        }

        /**
         * City input se actual day number return karega.
         */
        function getDayNumberFromCityInput($cityInput) {
            let dayNumber = parseInt(
                $cityInput.attr('data-dayindex') ||
                $cityInput.attr('data-day'),
                10
            );

            if (!Number.isNaN(dayNumber) && dayNumber > 0) {
                return dayNumber;
            }

            const $dayRow = $cityInput.closest('.row.mt-2');

            if (!$dayRow.length) {
                return null;
            }

            const dayText = $dayRow.find('span.bold').first().text().trim();
            const dayMatch = dayText.match(/Day\s*:?\s*(\d+)/i);

            return dayMatch ? parseInt(dayMatch[1], 10) : null;
        }

        /**
         * Saved quotation load hone ke baad har day ki original city store karega.
         */
        function captureSavedCityItineraryBaseline() {
            $('.city-details .qtn-city').each(function () {
                const $cityInput = $(this);
                const dayNumber = getDayNumberFromCityInput($cityInput);

                if (!dayNumber) {
                    return;
                }

                $cityInput.attr(
                    'data-saved-itinerary-city',
                    normalizeItineraryCity($cityInput.val())
                );

                $cityInput.attr(
                    'data-saved-itinerary-day',
                    dayNumber
                );
            });

            savedCityItineraryWatchReady = true;

            console.log(
                'Saved city itinerary watcher enabled:',
                $('.city-details .qtn-city').length
            );
        }

        /**
         * New saved quotation load karne se pehle watcher reset karega.
         */
        function resetSavedCityItineraryWatcher() {
            savedCityItineraryWatchReady = false;

            $('.city-details .qtn-city')
                .removeAttr('data-saved-itinerary-city')
                .removeAttr('data-saved-itinerary-day');
        }

        function normalizeHotelCity(city) {
            return String(city || '')
                .trim()
                .replace(/\s+/g, ' ')
                .toLowerCase();
        }

        /**
         * Edit mode mein city change hone par us night ke saved hotels invalidate karega.
         */
        function requireHotelForChangedCity($cityInput, newCityName) {

            // Sirf edit mode mein apply hoga
            if ($('.file_status').val() !== 'edit') {
                return;
            }

            const dayNumber = getDayNumberFromCityInput($cityInput);

            const totalNights = parseInt(
                (typeof qdata !== 'undefined' && qdata.nights)
                    ? qdata.nights
                    : $('#number_of_nights').val(),
                10
            ) || 0;

            /*
            * Last departure day ka hotel nahi hota.
            * Isliye sirf Day 1 se total nights tak validation lagegi.
            */
            if (
                !dayNumber ||
                dayNumber < 1 ||
                dayNumber > totalNights
            ) {
                return;
            }

            newCityName = String(newCityName || '').trim();

            /*
            * City input par mark store karo.
            */
            $cityInput
                .attr('data-hotel-selection-required', 'yes')
                .attr('data-required-hotel-city', normalizeHotelCity(newCityName))
                .attr('data-required-hotel-city-label', newCityName);

            /*
            * Changed city ke corresponding night ke hotel inputs.
            * Day 1 City = Night 1 Hotel
            * Day 2 City = Night 2 Hotel
            */
            const $hotelInputs = $(
                '.daywise-hotels[data-night="' + dayNumber + '"]'
            );

            $hotelInputs.each(function () {

                const $hotelInput = $(this);

                // Saved hotel name remove
                $hotelInput
                    .val('')
                    .removeAttr('data-selected-hotel-city')
                    .attr(
                        'placeholder',
                        'Search Hotel In ' + newCityName
                    )
                    .addClass('hotel-city-changed-required');

                // Saved hotel ID remove
                $hotelInput
                    .prevAll('.hdn-hotelids')
                    .first()
                    .val('');
            });

            /*
            * City change hone ke baad "Same Hotels For All Days"
            * selection valid nahi rahegi.
            */
            if ($('#chk_all_hotels').is(':checked')) {
                $('#chk_all_hotels')
                    .prop('checked', false)
                    .data('manual-uncheck', true);
            }

            console.log(
                'Hotel selection required for Day ' +
                dayNumber +
                ', City: ' +
                newCityName
            );
        }

        function removeSavedItineraryOnCityChange(
            $cityInput,
            selectedCity
        ) {
            if (!savedCityItineraryWatchReady) {
                return;
            }

            /*
            * Sirf day-wise city inputs ke liye.
            * Arrival flight city input par apply nahi hoga.
            */
            if (!$cityInput.closest('.city-details').length) {
                return;
            }

            const dayNumber =
                getDayNumberFromCityInput($cityInput);

            if (!dayNumber) {
                return;
            }

            const hasSavedCity = $cityInput.is(
                '[data-saved-itinerary-city]'
            );

            if (!hasSavedCity) {
                return;
            }

            const oldCity = normalizeItineraryCity(
                $cityInput.attr(
                    'data-saved-itinerary-city'
                )
            );

            const newCityDisplay = String(
                selectedCity !== undefined
                    ? selectedCity
                    : $cityInput.val()
            ).trim();

            const newCity = normalizeItineraryCity(
                newCityDisplay
            );

            /*
            * Same city select ki hai to itinerary remove nahi hogi.
            */
            if (oldCity === newCity) {
                return;
            }

            /*
            * Flight Details Yes/No dono cases se
            * current arrival city nikalo.
            */
            const flightDetailsMode = String(
                $('input[name="fligt_details"]:checked').val() || ''
            ).trim().toLowerCase();

            const arrivalCityWithFlight = String(
                $('#flight-city-initial-arrival').val() || ''
            ).trim();

            const arrivalCityWithoutFlight = String(
                $('#flight-city-initial-arrival_no').val() || ''
            ).trim();

            let arrivalCityDisplay = '';

            if (flightDetailsMode === 'no') {
                arrivalCityDisplay =
                    arrivalCityWithoutFlight ||
                    arrivalCityWithFlight;
            } else {
                arrivalCityDisplay =
                    arrivalCityWithFlight ||
                    arrivalCityWithoutFlight;
            }

            const arrivalCity = normalizeItineraryCity(
                arrivalCityDisplay
            );

            const isArrivalCity =
                newCity !== '' &&
                arrivalCity !== '' &&
                newCity === arrivalCity;

            /*
            * Edit mode me city change hui hai,
            * isliye is night ka saved hotel invalidate karo.
            */
            requireHotelForChangedCity(
                $cityInput,
                newCityDisplay
            );

            const $itineraryList = $(
                '#collapse' + dayNumber
            );

            /*
            * Add itinerary input ka placeholder
            * new city ke according update karo.
            */
            const $addItineraryInput = $(
                '.add-itinerary[data-day="' +
                dayNumber +
                '"]'
            );

            if ($addItineraryInput.length) {
                $addItineraryInput.attr(
                    'placeholder',
                    newCityDisplay
                        ? 'Search & Add Itinerary in ' +
                        newCityDisplay
                        : 'Search & Add Itinerary'
                );
            }

            /*
            * Important:
            * Changed city arrival city ke equal hai to
            * saved itinerary remove nahi hogi.
            *
            * Example:
            * Almaty -> Almaty
            * Departure/check-out/airport itinerary preserve rahegi.
            */
            if (isArrivalCity) {
                $cityInput.attr(
                    'data-saved-itinerary-city',
                    newCity
                );

                if ($itineraryList.length) {
                    $itineraryList.removeAttr(
                        'data-city-changed'
                    );
                }

                console.log(
                    'Day ' + dayNumber +
                    ' city changed from "' +
                    oldCity +
                    '" to arrival city "' +
                    newCity +
                    '". Saved itinerary preserved.'
                );

                return;
            }

            /*
            * Arrival city ke alawa kisi aur city me
            * change hua to saved itinerary remove hogi.
            */
            if (!$itineraryList.length) {
                console.warn(
                    'Itinerary UL not found for Day ' +
                    dayNumber
                );

                $cityInput.attr(
                    'data-saved-itinerary-city',
                    newCity
                );

                return;
            }

            const itineraryCount =
                $itineraryList.children('li').length;

            /*
            * Saare saved itinerary hidden inputs remove:
            * hdn_site_id
            * hdn_itinerary_content
            * hdn_activities
            * hdn_entrance_data
            */
            $itineraryList.empty();

            $itineraryList.attr(
                'data-city-changed',
                'yes'
            );

            /*
            * Train timing indicator bhi remove karo.
            */
            $(
                'a[href="#collapse' +
                dayNumber +
                '"] .train-time-indicator'
            ).remove();

            /*
            * Current city ko new baseline banao.
            */
            $cityInput.attr(
                'data-saved-itinerary-city',
                newCity
            );

            console.log(
                'Day ' + dayNumber +
                ' city changed from "' +
                oldCity +
                '" to "' +
                newCity +
                '". Removed ' +
                itineraryCount +
                ' saved itinerary item(s).'
            );
        }

        $(document)
        .off(
            'autocompleteselect.savedItineraryCity',
            '.city-details .qtn-city'
        )
        .on(
            'autocompleteselect.savedItineraryCity',
            '.city-details .qtn-city',
            function (event, ui) {
                const $cityInput = $(this);

                const selectedCity =
                    ui &&
                    ui.item &&
                    (ui.item.label || ui.item.value)
                        ? ui.item.label || ui.item.value
                        : $cityInput.val();

                removeSavedItineraryOnCityChange(
                    $cityInput,
                    selectedCity
                );
            }
        );

        $(document)
        .off(
            'change.savedItineraryCity',
            '.city-details .qtn-city'
        )
        .on(
            'change.savedItineraryCity',
            '.city-details .qtn-city',
            function () {
                removeSavedItineraryOnCityChange(
                    $(this),
                    $(this).val()
                );
            }
        );
        
        function showCityField($element) {
            if (!$element || !$element.length) {
                return;
            }

            $element.each(function () {
                this.classList.remove('hide');

                /*
                * Edit load ke waqt lagaya hua:
                * display:none !important
                * completely remove karega.
                */
                this.style.removeProperty('display');
            });

            $element.stop(true, true).show();
        }

        function hideCityField($element) {
            if (!$element || !$element.length) {
                return;
            }

            $element.each(function () {
                this.classList.add('hide');
                this.style.setProperty(
                    'display',
                    'none',
                    'important'
                );
            });
        }

        function updateCityUIOnSelection($cityInput)
        {
            var idx = $cityInput.index(".qtn-city");
            var parentRow = $cityInput.closest(".row");
            var cityVal = $cityInput.val().trim();
            var arrival_city = $('#flight-city-initial-arrival').val();

            var dayText = parentRow.find("span.bold").first().text().trim();
            var dayMatch = dayText.match(/Day\s+(\d+)/i);
            var dayNo = dayMatch ? parseInt(dayMatch[1]) : null;

            var countryname = getCountryFromEnquiry(qdata.enquiry_abbr);

            if (!dayNo) {
                return;
            }

            if (idx !== 0) {

                let currentCity = $cityInput.val().trim().toLowerCase();
                let previousCity = $(".qtn-city")
                    .eq(idx - 1)
                    .val()
                    .trim()
                    .toLowerCase();

                let cityChanged = currentCity !== previousCity;

                if (cityChanged) {

                    let $transferSelect = parentRow.find(".qtn-transfer");

                    // Show fields
                    $transferSelect.parent().removeClass("hide").show();

                    parentRow.find(".overnight-type")
                        .removeClass("hide")
                        .show();

                    parentRow.find(".route-change")
                        .removeClass("hide")
                        .css("display", "block");

                    // Blank hone par Road default
                    if (!$transferSelect.val()) {
                        $transferSelect.val("road").trigger("change");
                    }

                } else {

                    parentRow.find(".overnight-type")
                        .addClass("hide")
                        .hide();

                    parentRow.find(".qtn-transfer")
                        .val("")
                        .parent()
                        .addClass("hide")
                        .hide();

                    parentRow.find(".route-change")
                        .addClass("hide")
                        .hide();

                    parentRow.find(".with-train").hide();

                    parentRow.next(".local-train").slideUp(1000);
                }
            }

            applyRoadTransferRules(
                parentRow,
                countryname,
                cityVal,
                arrival_city,
                dayNo
            );
        }
        
        $("#frm_1").on("click", ".qtn-city", function() {
            updateCityUIOnSelection($(this));
        });
        
        $(document).on('input', '.qtn-city', function() {
            $(this).attr('data-city-valid', 'false');
        });

        function applyRoadTransferRules($row, countryname, cityVal, arrival_city, dayNo) {
            console.log($row,'row',countryname,'countryname',cityVal,'cityVal',arrival_city,'arrival_city',dayNo,'dayNo',);
            var transferMode = $row.find(".qtn-transfer").val();
            if (transferMode !== "road") return; // only applies to road transfers

            if (countryname === 'kazakhstan' || countryname === 'georgia') {
                // Ensure Overnight option exists
                if ($row.find(".overnight-type input[value='overnight']").length === 0) {
                    $row.find(".radio-group").prepend(
                        '<label><input type="radio" name="overnight_type_' + (dayNo - 1) + '" value="overnight"><span class="bold"> Overnight</span></label>'
                    );
                }

                if ($row.find(".qtn-transfer").closest('.col-md-3').is(':visible')) {
                    $row.find(".with-train").css("display", "block");
                    $row.find(".with-train input[type='radio'][value='yes']").prop("checked", true);
                }

                // City match condition
                if (cityVal.toLowerCase() === arrival_city.toLowerCase()) {
                    // Hide Overnight, show only Drop Off
                    $row.find(".overnight-type input[value='overnight']").closest('label').hide();
                    $row.find(".overnight-type input[value='drop_off']").closest('label').show();
                    $row.find(".overnight-type input[value='drop_off']").prop("checked", false).prop("disabled", true);
                    $row.find(".overnight-type input[value='overnight']").prop("disabled", true).prop("checked", false);
                    $row.find(".with-train").css("display", "none");
                    $row.find(".with-train input[type='radio']").prop("checked", false).prop("checked", false);
                } else {
                    // Show both, set Overnight checked, disable Drop Off
                    $row.find(".overnight-type input").closest('label').show();
                    $row.find(".overnight-type input[value='overnight']").prop("checked", true).prop("disabled", false);
                    $row.find(".overnight-type input[value='drop_off']").prop("disabled", true);
                }
            }
            else if (countryname === 'uzbekistan') {
                // Ensure Drop Off exists
                if ($row.find(".overnight-type input[value='drop_off']").length === 0) {
                    $row.find(".radio-group").append(
                        '<label><input type="radio" name="overnight_type_' + (dayNo - 1) + '" value="drop_off"><span class="bold"> Drop Off</span></label>'
                    );
                }
                // Set Drop Off checked, disable Overnight
                $row.find(".overnight-type input[value='drop_off']").prop("checked", true).prop("disabled", false);
                $row.find(".overnight-type input[value='overnight']").prop("disabled", true).prop("checked", false);
                if ($row.find(".qtn-transfer").closest('.col-md-3').is(':visible')) {
                    $row.find(".with-train").css("display", "block");
                    $row.find(".with-train input[type='radio'][value='no']").prop("checked", true);
                }
                if (cityVal.toLowerCase() === arrival_city.toLowerCase()) {
                    $row.find(".with-train").css("display", "none");
                    $row.find(".with-train input[type='radio']").prop("checked", false).prop("checked", false);
                }
            }
            else {
                // All other countries: enable both options
                $row.find(".overnight-type input").prop("disabled", false);
                // Optionally show both labels if they were hidden
                $row.find(".overnight-type input").closest('label').show();
            }
        }
        
         // Function to toggle main day fields based on route change selection
        function toggleMainDayFields($row, isYes) {
            // Find elements
            let $transferDiv = $row.find(".qtn-transfer").closest(".col-md-2");
            let $overnightDiv = $row.find(".overnight-type");
            let $guideDiv = $row.find(".with-train");
            let $routeSection = $row.nextAll(".route-change-section").first();

            if (isYes) {
                // Hide main day fields
                $transferDiv.addClass("hide");
                $overnightDiv.addClass("hide");
                // $overnightDiv.css("display", "none");
                $guideDiv.hide(); // ensure hidden (style display:none)
                
                // Uncheck any radios inside these hidden divs
                $overnightDiv.find("input[type='radio']").prop("checked", false);
                $guideDiv.find("input[type='radio']").prop("checked", false);
                
                // Show route-change section
                $routeSection.slideDown(500);
            } else {
                // Show main day fields (remove hide class and show)
                $transferDiv.removeClass("hide").show();
                $overnightDiv.removeClass("hide").show();
                // $overnightDiv.css("display", "block");
                $guideDiv.show();
                
                // Hide route-change section
                $routeSection.slideUp(500);
                
                // Optionally reset route-change section fields
                $routeSection.find("input, select").val("");
                $routeSection.find("input[type='radio']").prop("checked", false);
                $routeSection.find(".local-train").hide();
                
                // Apply country-specific rules if needed
                let countryname = getCountryFromEnquiry(qdata.enquiry_abbr);
                applyOvernightRules($row, countryname);
            }
        }

        // Event handler for route change radio group
        $(document).on("change", "input[name^='route_change']", function() {
            let $row = $(this).closest(".row.mt-2");
            let isYes = ($(this).val() === "yes");
            toggleMainDayFields($row, isYes);
        });

        // After city details are appended, initialise visibility for each day
        $(".city-details .row.mt-2").each(function() {
            let $row = $(this);
            let $checkedRadio = $row.find("input[name^='route_change']:checked");
            if ($checkedRadio.length) {
                let isYes = ($checkedRadio.val() === "yes");
                toggleMainDayFields($row, isYes);
            } else {
                // default to 'no' (checked by default)
                toggleMainDayFields($row, false);
            }
        });

        function applyOvernightRules($row, countryname) {
            let $overnightRadio = $row.find(".overnight-type input[value='overnight']");
            let $dropoffRadio = $row.find(".overnight-type input[value='drop_off']");
            if (countryname === 'kazakhstan' || countryname === 'georgia') {
                $overnightRadio.prop("checked", true).prop("disabled", false);
                $dropoffRadio.prop("disabled", true).prop("checked", false);
            } else if (countryname === 'uzbekistan') {
                $dropoffRadio.prop("checked", true).prop("disabled", false);
                $overnightRadio.prop("disabled", true).prop("checked", false);
            } else {
                $overnightRadio.prop("disabled", false);
                $dropoffRadio.prop("disabled", false);
            }
        }
        
