        function get_index(idx){
            var return_idx = 0;
            if(idx >= 0 && idx <= 2){
                return_idx = 0;
            }else if(idx >= 3 && idx <= 5){
                return_idx = 1;
            }else if(idx >= 6 && idx <= 8){
                return_idx = 2;
            }else if(idx >= 9 && idx <= 11){
                return_idx = 3;
            }else if(idx >= 12 && idx <= 14){
                return_idx = 4;
            }else if(idx >= 15 && idx <= 17){
                return_idx = 5;
            }else if(idx >= 18 && idx <= 20){
                return_idx = 6;
            }else if(idx >= 21 && idx <= 23){
                return_idx = 7;
            }else if(idx >= 24 && idx <= 26){
                return_idx = 8;
            }else if(idx >= 27 && idx <= 29){
                return_idx = 9;
            }
            return return_idx;
        }

