        $(document).on('keydown.autocomplete', ".daywise-hotels", function() 
        {
            var idx = $(this).index(".daywise-hotels");
            var type = $(this).attr("data-category");
            var nightNumber = parseInt($(this).attr("data-night"));
            var cityIndex = nightNumber + 1;
            var allCityInputs = $(".qtn-city");
            var city_name = "";

            if (cityIndex < allCityInputs.length) {
                city_name = allCityInputs.eq(cityIndex).val();
            } else if (allCityInputs.length > 0) {
                // Fallback to last city if index out of bounds
                city_name = allCityInputs.last().val();
            }
            
           
            // var city_name = $(".qtn-city").eq($(this).attr("data-night")).val();
            
            // var currentNight = parseInt($(this).attr("data-night"));
            // var nextNight = currentNight + 1;
            // var city_name = "";
            // if(nextNight <= qdata.nights) {
            //     city_name = $(".qtn-city").eq(nextNight).val();
            // } else {
            //     // अगर next night नहीं है (last night है), तो current night की city use करें
            //     city_name = $(".qtn-city").eq(currentNight).val();
            // }
            
            var hotel_ids = $("input[name='hdn_night_"+$(this).attr("data-night")+"_"+type.replaceAll(" ","_").toLowerCase()+"_ids[]']").map(function () {
                return this.value;
            }).get();
            var all_cities = $(".qtn-city").map(function () {
                return $(this).val();
            }).get();
            if (city_name && city_name.toLowerCase() === "kolsai") {
                type = "4 Star";
            }
            $(this).autocomplete({                
                source: function (request, response) {
                    // Fetch data
                    $.ajax({
                        url: "<?= base_url() ?>admin/quotation/get_hotel_citywise",
                        type: 'post',
                        dataType: "json",
                        data: {
                            search: request.term,
                            city: city_name,
                            all_cities: all_cities,
                            type: type,
                            hotel_ids: hotel_ids,
                            check_in: qdata.checkin, 
                            check_out: qdata.checkout,
                        },
                        success: function (data) {
                            response(data);
                        }
                    });
                },
                 select: function (event, ui) {
                    var cleanName = $("<div>").html(ui.item.label).text();  
                    $(".daywise-hotels").eq(idx).val(cleanName);
                    $(".hdn-hotelids").eq(idx).val(ui.item.hotel_id);
                    return false;
                }
            }).data("ui-autocomplete")._renderItem = function(ul, item) {
                return $("<li></li>")
                    .data("item.autocomplete", item)
                    .append(item.label) 
                    .appendTo(ul);
            };
            
            $(this).blur(function() {
                if($(".daywise-hotels").eq(idx).val() === ""){
                    $(".hdn-hotelids").eq(idx).val("");
                }
            });
        });
        
