<script>
    // 07 feb 2026 updated 
    $(document).ready(function() {
        let selectedQuoteId = null;
        let originalDropdownHTML = null;
        let roomTypeMapping = {
            'single': { label: 'Single Room', capacity: 1 },
            'double': { label: 'Double/Twin Room', capacity: 2 },
            'triple': { label: 'Triple Room', capacity: 3 },
            'quad': { label: 'Quad Room', capacity: 4 },
            'quint': { label: 'Quint Room', capacity: 5 },
            'sext': { label: 'Sext Room', capacity: 6 }
        };
        
        // Open final quote modal
        $('#btn_final_quote').click(function() {
            loadQuotesInDropdown();
            $('#finalQuoteModal').modal('show');
        });
        
        // Load quotes from main modal into dropdown
        function loadQuotesInDropdown() {
            const $dropdown = $('#quote_dropdown');
            $dropdown.empty().append('<option value="">-- Select Quote --</option>');
            $('#btn_mark_final').prop('disabled', true);
            $('#quote_info').hide();
            $('#adult_room_breakdown').hide();
            $('#child_type').hide();
            $('#room_allocation_error').hide();
            $('#cnb, #cwb').prop('checked', false);
            $('#child_inputs').empty();
            $('#room_type_inputs').empty();
            $('#adult_count_display').empty();
            
            // Store original dropdown HTML before clearing
            originalDropdownHTML = $('#quote_dropdown').html();
            
            // Get all quotes from main modal
            const $quotes = $('.open-quote-popup');
            
            if ($quotes.length === 0) {
                $dropdown.append('<option value="" disabled>No quotes found</option>');
                return;
            }
            
            // Collect all quotes with their data
            const quotesArray = [];
            
            $quotes.each(function(index) {
                const $quote = $(this);
                const quoteId = $quote.data('id');
                const quoteText = $quote.text().trim();
                
                // Extract date and time from quote text
                let quoteDateTime = null;
                let formattedDate = '';
                
                const dateTimeMatch1 = quoteText.match(/(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2}:\d{2})/);
                const dateTimeMatch2 = quoteText.match(/(\d{1,2}-[A-Za-z]{3}-\d{4})\s+(\d{2}:\d{2})/);
                const dateMatch = quoteText.match(/(\d{4}-\d{2}-\d{2})|(\d{1,2}-[A-Za-z]{3}-\d{4})/);
                
                if (dateTimeMatch1 && dateTimeMatch1[1]) {
                    quoteDateTime = new Date(dateTimeMatch1[1] + 'T' + dateTimeMatch1[2]);
                    formattedDate = formatDateToDDMMMYYYY(quoteDateTime);
                } else if (dateTimeMatch2 && dateTimeMatch2[1]) {
                    const dateStr = dateTimeMatch2[1];
                    const [day, monthName, year] = dateStr.split('-');
                    const months = {
                        'Jan': 0, 'Feb': 1, 'Mar': 2, 'Apr': 3, 'May': 4, 'Jun': 5,
                        'Jul': 6, 'Aug': 7, 'Sep': 8, 'Oct': 9, 'Nov': 10, 'Dec': 11
                    };
                    quoteDateTime = new Date(year, months[monthName], day);
                    formattedDate = dateStr;
                } else if (dateMatch) {
                    const dateStr = dateMatch[0];
                    if (dateStr.includes('-')) {
                        if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
                            quoteDateTime = new Date(dateStr);
                            formattedDate = formatDateToDDMMMYYYY(quoteDateTime);
                        }
                    }
                }
                
                // Extract actual quote number from text
                let actualQuoteNumber = null;
                const quoteNumMatch = quoteText.match(/Quote\s*(\d+)/i);
                if (quoteNumMatch && quoteNumMatch[1]) {
                    actualQuoteNumber = parseInt(quoteNumMatch[1]);
                }
                
                // Check if final
                const hasBadge = $quote.find('.badge-success').length > 0;
                const hasFinalText = quoteText.includes('FINAL');
                const isFinal = hasBadge || hasFinalText;
                
                quotesArray.push({
                    id: quoteId,
                    idValue: parseInt(quoteId),
                    actualNumber: actualQuoteNumber,
                    isFinal: isFinal,
                    dateTime: quoteDateTime,
                    formattedDate: formattedDate,
                    text: quoteText,
                    element: $quote
                });
            });
            
            // Sort quotes
            quotesArray.sort((a, b) => {
                if (a.dateTime && b.dateTime) {
                    const timeDiff = a.dateTime.getTime() - b.dateTime.getTime();
                    if (timeDiff !== 0) return timeDiff;
                } else if (a.dateTime && !b.dateTime) return -1;
                else if (!a.dateTime && b.dateTime) return 1;
                return a.idValue - b.idValue;
            });
            
            // Add sorted quotes to dropdown with sequential numbers
            let sequentialNumber = 1;
            quotesArray.forEach(quoteInfo => {
                let displayText = `Quote ${sequentialNumber}`;
                if (quoteInfo.formattedDate) displayText += ` - ${quoteInfo.formattedDate}`;
                if (quoteInfo.isFinal) displayText += ' - FINAL';
                
                const $option = $('<option>', {
                    value: quoteInfo.id,
                    text: displayText,
                    selected: quoteInfo.isFinal,
                    'data-is-final': quoteInfo.isFinal,
                    'data-quote-number': sequentialNumber,
                    'data-quote-date': quoteInfo.formattedDate || '',
                    'data-original-text': quoteInfo.text,
                    'data-actual-number': quoteInfo.actualNumber || '',
                    'data-quote-id': quoteInfo.id
                });
                
                $dropdown.append($option);
                
                // If this is final quote, select it
                if (quoteInfo.isFinal) {
                    selectedQuoteId = quoteInfo.id;
                    $('#btn_mark_final').prop('disabled', false);
                    $('#btn_mark_final').html('<i class="fa fa-check"></i> Update Final');
                    showQuoteInfo(quoteInfo.id, sequentialNumber, quoteInfo.formattedDate, quoteInfo.isFinal);
                }
                sequentialNumber++;
            });
            
            // If multiple quotes are final, select the first one
            const finalOptions = $dropdown.find('option[data-is-final="true"]');
            if (finalOptions.length > 0 && !selectedQuoteId) {
                const $firstFinal = $(finalOptions[0]);
                selectedQuoteId = $firstFinal.val();
                $firstFinal.prop('selected', true);
                $('#btn_mark_final').prop('disabled', false);
                $('#btn_mark_final').html('<i class="fa fa-check"></i> Update Final');
                showQuoteInfo(selectedQuoteId, $firstFinal.data('quote-number'), $firstFinal.data('quote-date'), true);
            }
        }
        
        // Format date to DD-MMM-YYYY
        function formatDateToDDMMMYYYY(dateObj) {
            if (!dateObj || isNaN(dateObj.getTime())) return '';
            const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const day = String(dateObj.getDate()).padStart(2, '0');
            const month = months[dateObj.getMonth()];
            const year = dateObj.getFullYear();
            return `${day}-${month}-${year}`;
        }
        
        // When dropdown selection changes
        $(document).on('change', '#quote_dropdown', function() {
            const quoteId = $(this).val();
            const selectedOption = $(this).find('option:selected');
            const isFinal = selectedOption.data('is-final') === true;
            const quoteNumber = selectedOption.data('quote-number');
            const quoteDate = selectedOption.data('quote-date') || '';
            
            selectedQuoteId = quoteId;
            
            $('#btn_mark_final').prop('disabled', true);
            $('#cnb, #cwb').prop('checked', false);
            $('#child_inputs').empty();
            $('#room_type_inputs').empty();
            $('#adult_count_display').empty();
            $('#adult_room_breakdown').hide();
            $('#child_type').hide();
            $('#room_allocation_error').hide();
            
            if (quoteId) {
                if (isFinal) {
                    $('#btn_mark_final').html('<i class="fa fa-check"></i> Update Final');
                } else {
                    $('#btn_mark_final').html('<i class="fa fa-check"></i> Mark as Final');
                }
                
                // Show quote info immediately
                showQuoteInfo(quoteId, quoteNumber, quoteDate, isFinal);
                
                // Check if quote has same_hotels_all_nights = 'yes'
                checkSameHotelsAllNights(quoteId);
            } else {
                $('#quote_info').hide();
            }
        });
        

        function checkSameHotelsAllNights(quoteId) {
            $.ajax({
                url: '<?php echo site_url("admin/quotation/check_same_hotels"); ?>',
                type: 'POST',
                dataType: 'json',
                data: { quote_id: quoteId },
                success: function(response) {
                    if (response.success) {
                        const hasSameHotels = (response.same_hotels_all_nights === 'yes');
                        // Check if hotel_details is empty (null, empty string, empty array)
                        let hotelDetailsEmpty = false;
                        if (response.hotel_details) {
                            try {
                                const details = typeof response.hotel_details === 'string' 
                                    ? JSON.parse(response.hotel_details) 
                                    : response.hotel_details;
                                hotelDetailsEmpty = (Array.isArray(details) && details.length === 0);
                            } catch(e) {
                                hotelDetailsEmpty = true;
                            }
                        } else {
                            hotelDetailsEmpty = true;
                        }

                        if (!hotelDetailsEmpty) {
                            // Normal case: load hotel details and show allocation UI
                            loadHotelDetails(quoteId);
                        } else {
                            // No hotels needed: hide allocation UI, show info, enable final button
                            $('#adult_room_breakdown').hide();
                            $('#child_type').hide();
                            showInfoMessage('This quote has no hotel details. Room allocation is not required.');
                            validateFinalButton(true); // force enable button
                        }
                        // Always call validateFinalButton to set final state
                        validateFinalButton();
                    } else {
                        alert('Error checking quote details');
                    }
                },
                error: function() {
                    alert('Error occurred while checking quote');
                }
            });
        }

        // New function to control final button state
        function validateFinalButton(noHotelsMode = false) {
            
            // If hotel allocation UI is visible, rely on validateAllocation()
            if ($('#adult_room_breakdown').is(':visible')) {
                validateAllocation();
            } else {
                // If allocation UI is hidden, enable button (fallback for edge cases)
                $('#btn_mark_final').prop('disabled', false);
            }
        }
        
        // Show info message
        function showInfoMessage(message) {
            // Create or update info message
            let $infoDiv = $('#same_hotels_info');
            if ($infoDiv.length === 0) {
                $infoDiv = $('<div id="same_hotels_info" class="alert alert-info mt-3"></div>');
                $('#quote_info').after($infoDiv);
            }
            $infoDiv.html(`<i class="fa fa-info-circle"></i> ${message}`);
            $infoDiv.show();
        }
        
        // Hide info message
        function hideInfoMessage() {
            $('#same_hotels_info').hide();
        }
    
        function loadHotelDetails(quoteId) {
            $.ajax({
                url: '<?php echo site_url("admin/quotation/get_quote_hotels"); ?>',
                type: 'POST',
                dataType: 'json',
                data: { quote_id: quoteId },
                success: function(response) {
                    if (response.success && response.data.length > 0) {
                        renderHotelAllocation(response.data);
                        $('#adult_room_breakdown').show();
                    } else {
                        $('#adult_room_breakdown').hide();
                        showInfoMessage('No hotel details found for this quote.');
                    }
                    validateFinalButton();
                },
                error: function() {
                    alert('Error loading hotel details');
                }
            });
        }

        function renderHotelAllocation(hotels) {
            const $container = $('#room_type_inputs');
            $container.empty();

            const totalAdults = parseInt($('#number_of_adults').val()) || 0;
            const totalChildren = parseInt($('#number_of_child').val()) || 0;
            $('#adult_count_display').html(`
                <div class="alert alert-secondary p-2 mb-3">
                    <strong>👥 Total Adults:</strong> ${totalAdults} &nbsp;|&nbsp;
                    <strong>🧒 Total Children:</strong> ${totalChildren}
                </div>
            `);

            $.each(hotels, function(hotelIdx, hotel) {
                const hotelDiv = $('<div>', { class: 'hotel-group mb-4 p-3' });
                hotelDiv.append(`<h5 class="text-primary">🏨 ${hotel.hotel_name} <small class="text-muted">(${hotel.hotel_category})</small></h5>`);

                $.each(hotel.rooms, function(roomName, options) {
                    const roomDiv = $('<div>', { class: 'room-category mb-3' });
                    roomDiv.append(`<h6 class="font-weight-bold">${roomName}</h6>`);
                    const rowDiv = $('<div>', { class: 'd-flex flex-wrap' });

                    // Adult options
                    if (options.adult && options.adult.length) {
                        const adultGroup = $('<div>', { class: 'adult-options mr-3 mb-2' });
                        adultGroup.append('<strong>👤 Adult Occupancy</strong>');
                        $.each(options.adult, function(optIdx, opt) {
                            const optDiv = $('<div>', { class: 'mb-2 d-flex align-items-center' });
                            const chkId = `adult_${hotel.hotel_id}_${roomName.replace(/\s/g, '_')}_occ_${opt.occupancy}`;
                            const chk = $('<input>', {
                                type: 'checkbox',
                                class: 'adult-room-chk mr-1',
                                'data-hotel-id': hotel.hotel_id,
                                'data-room': roomName,
                                'data-occupancy': opt.occupancy,
                                'data-price': opt.price,
                                id: chkId
                            });
                            const label = $('<label>', { for: chkId, text: opt.label, class: 'ml-1 mr-2', style: 'width: 130px;' });
                            const countInput = $('<input>', {
                                type: 'number',
                                class: 'form-control form-control-sm adult-room-count',
                                style: 'width: 80px;',
                                'data-occupancy': opt.occupancy,
                                placeholder: 'Rooms',
                                min: 0,
                                value: 0,
                                disabled: true
                            });
                            chk.on('change', function() {
                                countInput.prop('disabled', !this.checked);
                                if (!this.checked) countInput.val(0);
                                validateAllocation();
                            });
                            countInput.on('input', function() { validateAllocation(); });
                            optDiv.append(chk, label, countInput);
                            adultGroup.append(optDiv);
                        });
                        rowDiv.append(adultGroup);
                    }

                    // Child options inline
                    if (options.child && options.child.length) {
                        const childGroup = $('<div>', { class: 'child-options mb-2' });
                        childGroup.append('<strong>🧒 Child Options</strong>');
                        $.each(options.child, function(childIdx, child) {
                            const childDiv = $('<div>', { class: 'mb-2 d-flex align-items-center' });
                            const childId = `child_${hotel.hotel_id}_${roomName.replace(/\s/g, '_')}_${child.type}`;
                            const chk = $('<input>', {
                                type: 'checkbox',
                                class: 'child-room-chk mr-1',
                                'data-type': child.type,
                                'data-price': child.price,
                                id: childId
                            });
                            const label = $('<label>', { for: childId, text: child.label, class: 'ml-1 mr-2', style: 'width: 100px;' });
                            const countInput = $('<input>', {
                                type: 'number',
                                class: 'form-control form-control-sm child-room-count',
                                style: 'width: 80px;',
                                placeholder: 'Count',
                                min: 0,
                                value: 0,
                                disabled: true
                            });
                            chk.on('change', function() {
                                countInput.prop('disabled', !this.checked);
                                if (!this.checked) countInput.val(0);
                                validateAllocation();
                            });
                            countInput.on('input', function() { validateAllocation(); });
                            childDiv.append(chk, label, countInput);
                            childGroup.append(childDiv);
                        });
                        rowDiv.append(childGroup);
                    }

                    roomDiv.append(rowDiv);
                    hotelDiv.append(roomDiv);
                });
                $container.append(hotelDiv);
            });

            // Attach input listeners to all number fields
            $('.adult-room-count, .child-room-count').on('input', function() {
                validateAllocation();
            });

            // Initial validation
            validateAllocation();
        }

        function validateAllocation() {
            const totalAdults = parseInt($('#number_of_adults').val()) || 0;
            const totalChildren = parseInt($('#number_of_child').val()) || 0;

            let allocatedAdults = 0;
            let allocatedChildren = 0;
            let anyRoomSelected = false;
            let anyChildSelected = false;

            // Adult counts
            $('.adult-room-chk:checked').each(function() {
                const occ = parseInt($(this).data('occupancy'));
                const count = parseInt($(this).closest('.adult-options').find('.adult-room-count').val()) || 0;
                if (count > 0) anyRoomSelected = true;
                allocatedAdults += occ * count;
            });

            // Child counts
            $('.child-room-chk:checked').each(function() {
                const count = parseInt($(this).closest('.child-options').find('.child-room-count').val()) || 0;
                if (count > 0) anyChildSelected = true;
                allocatedChildren += count;
            });

            // Show/hide error messages
            const adultOk = (allocatedAdults === totalAdults);
            const childOk = (allocatedChildren === totalChildren);
            $('#room_allocation_error').toggle(!adultOk && totalAdults > 0);

            $('#child_allocation_error').toggle(!childOk && totalChildren > 0);

            // Enable button if at least one room OR one child is selected (value > 0)
            const enable = anyRoomSelected || anyChildSelected;
            $('#btn_mark_final').prop('disabled', !enable);
        }
        
        // Show quote info
        function showQuoteInfo(quoteId, quoteNumber, quoteDate, isFinal) {
            let dateDisplay = quoteDate || 'Date not available';
            const infoHtml = `
                <div class="quote-info">
                    <strong>Selected Quote:</strong> Quote ${quoteNumber}<br>
                    <strong>Created Date:</strong> ${dateDisplay}
                </div>
            `;
            $('#selected_quote_details').html(infoHtml);
            $('#quote_info').show();
        }

        $('#btn_mark_final').click(function() {
            if (!selectedQuoteId) {
                Swal.fire('Error', 'No quote selected', 'error');
                return;
            }

            const selectedOption = $('#quote_dropdown option:selected');
            const isAlreadyFinal = selectedOption.data('is-final') === true;
            const quoteNumber = selectedOption.data('quote-number');
            const quoteDate = selectedOption.data('quote-date') || '';

            const enquiryId = $('#enquiry_id').val() || getEnquiryId();
            if (!enquiryId) {
                Swal.fire('Error', 'Enquiry ID not found', 'error');
                return;
            }

            function getRoomType(occupancy) {
                const types = {1:'single',2:'double',3:'triple',4:'quad',5:'quint',6:'sext'};
                return types[occupancy] || 'single';
            }

            const roomBreakdown = {};
            let totalRooms = 0;

            // 1. Collect adult occupancies
            $('.adult-room-chk:checked').each(function() {
                const $chk = $(this);
                const occupancy = $chk.data('occupancy');
                const $parentGroup = $chk.closest('.adult-options');
                const $countInput = $parentGroup.find(`.adult-room-count[data-occupancy="${occupancy}"]`);
                let roomCount = parseInt($countInput.val()) || 0;

                console.log(`Found checkbox: occupancy=${occupancy}, roomCount=${roomCount}, hotel-id=${$chk.data('hotel-id')}, roomName=${$chk.closest('.room-category').find('h6').text()}`);

                if (roomCount === 0) {
                    console.log(`Skipping because roomCount is 0`);
                    return;
                }

                // Extract room and hotel info
                const $roomCategory = $chk.closest('.room-category');
                const roomName = $roomCategory.find('h6').text().trim();
                const $hotelGroup = $chk.closest('.hotel-group');
                const hotelId = $chk.data('hotel-id');
                const hotelName = $hotelGroup.find('h5').text().replace(/🏨 /, '').split(' (')[0].trim();
                const hotelCategory = $hotelGroup.find('h5 small').text().replace(/[()]/g, '').trim();

                // Initialize hotel
                if (!roomBreakdown[hotelId]) {
                    roomBreakdown[hotelId] = {
                        hotel_id: hotelId,
                        hotel_name: hotelName,
                        hotel_category: hotelCategory,
                        rooms: []
                    };
                }

                // Find or create room entry
                let roomEntry = roomBreakdown[hotelId].rooms.find(r => r.room_name === roomName);
                if (!roomEntry) {
                    roomEntry = { room_name: roomName, occupancies: [], children: [] };
                    roomBreakdown[hotelId].rooms.push(roomEntry);
                }

                // Add adult occupancy
                roomEntry.occupancies.push({
                    occupancy: occupancy,
                    room_count: roomCount,
                    total_adults: occupancy * roomCount,
                    room_type: getRoomType(occupancy)
                });
                totalRooms += roomCount;

                console.log(`Added adult occupancy: ${roomName} occ=${occupancy} count=${roomCount}`);
            });

            // 2. Collect child selections per room (associated with the same room)
            $('.child-room-chk:checked').each(function() {
                const $chk = $(this);
                const $roomCategory = $chk.closest('.room-category');
                const roomName = $roomCategory.find('h6').text().trim();
                const $hotelGroup = $chk.closest('.hotel-group');
                const hotelId = $hotelGroup.find('.adult-room-chk').first().data('hotel-id'); // get hotelId from any adult checkbox in same group
                const childType = $chk.data('type');
                const $countInput = $chk.closest('.child-options').find('.child-room-count');
                let childCount = parseInt($countInput.val()) || 0;

                console.log(`Found child: type=${childType}, count=${childCount}, hotelId=${hotelId}, roomName=${roomName}`);

                if (childCount === 0) return;

                if (!roomBreakdown[hotelId]) {
                    // Should not happen, but initialize if missing
                    const hotelName = $hotelGroup.find('h5').text().replace(/🏨 /, '').split(' (')[0].trim();
                    const hotelCategory = $hotelGroup.find('h5 small').text().replace(/[()]/g, '').trim();
                    roomBreakdown[hotelId] = {
                        hotel_id: hotelId,
                        hotel_name: hotelName,
                        hotel_category: hotelCategory,
                        rooms: []
                    };
                }

                let roomEntry = roomBreakdown[hotelId].rooms.find(r => r.room_name === roomName);
                if (!roomEntry) {
                    roomEntry = { room_name: roomName, occupancies: [], children: [] };
                    roomBreakdown[hotelId].rooms.push(roomEntry);
                }

                const existingChild = roomEntry.children.find(c => c.type === childType);
                if (existingChild) {
                    existingChild.count += childCount;
                } else {
                    roomEntry.children.push({ type: childType, count: childCount });
                }
                console.log(`Added child: ${roomName} ${childType} count=${childCount}`);
            });

            // 3. Compute global child counts (optional)
            let globalCnbCount = 0, globalCwbCount = 0;
            Object.values(roomBreakdown).forEach(hotel => {
                hotel.rooms.forEach(room => {
                    (room.children || []).forEach(child => {
                        if (child.type === 'CNB') globalCnbCount += child.count;
                        else if (child.type === 'CWB') globalCwbCount += child.count;
                    });
                });
            });

            const postData = {
                quote_id: selectedQuoteId,
                enquiry_id: enquiryId,
                cnb: globalCnbCount > 0 ? 1 : 0,
                cnb_count: globalCnbCount,
                cwb: globalCwbCount > 0 ? 1 : 0,
                cwb_count: globalCwbCount,
                room_breakdown: roomBreakdown,
                total_rooms: totalRooms
            };

            console.log("Final roomBreakdown:", JSON.stringify(roomBreakdown, null, 2));
            console.log("postData:", postData);

            // SweetAlert confirmation (unchanged)
            Swal.fire({
                title: isAlreadyFinal ? 'Update Final Quote?' : 'Mark as Final Quote?',
                html: isAlreadyFinal ? 
                    `Quote ${quoteNumber} <br><small>Date: ${quoteDate}</small><br><br>is already marked as FINAL. Do you want to update it?` : 
                    `Are you sure you want to mark <strong>Quote ${quoteNumber}</strong> as FINAL?<br><small>Date: ${quoteDate}</small>`,
                icon: 'question',
                showCancelButton: true,
                confirmButtonColor: '#28a745',
                cancelButtonColor: '#6c757d',
                confirmButtonText: isAlreadyFinal ? 'Yes, Update!' : 'Yes, Mark as Final!',
                cancelButtonText: 'Cancel',
                showLoaderOnConfirm: true,
                preConfirm: () => {
                    return $.ajax({
                        url: '<?php echo site_url("admin/quotation/mark_final"); ?>',
                        type: 'POST',
                        contentType: 'application/json',
                        dataType: 'json',
                        data: JSON.stringify(postData)
                    }).then(response => {
                        if (!response.success) throw new Error(response.message || 'Failed to update quote');
                        return response;
                    }).catch(error => {
                        Swal.showValidationMessage(`Request failed: ${error.statusText || error.message}`);
                    });
                },
                allowOutsideClick: () => !Swal.isLoading()
            }).then((result) => {
                if (result.isConfirmed) {
                    updateMainModal(selectedQuoteId, quoteNumber);
                    loadQuotesInDropdown();
                    $('#finalQuoteModal').modal('hide');
                    Swal.fire({
                        title: 'Success!',
                        html: `Quote <strong>${quoteNumber}</strong> has been marked as FINAL.<br><small>Date: ${quoteDate}</small>`,
                        icon: 'success',
                        confirmButtonColor: '#28a745',
                        timer: 2000,
                        timerProgressBar: true
                    });
                }
            });
        });
        
        // Update main modal quotes
        function updateMainModal(finalQuoteId, quoteNumber) {
            // Remove final style from all quotes
            $('.quotations-made').each(function() {
                const $quote = $(this);
                const $faIcon = $quote.find('.fa');
                
                $quote.css({
                    'color': '',
                    'font-weight': '',
                    'border-left': '',
                    'background-color': ''
                });
                
                if ($faIcon.length) $faIcon.css('color', '');
                $quote.find('.badge-success').remove();
                
                const html = $quote.html();
                let newHtml = html.replace(/<span[^>]*FINAL[^>]*>[^<]*<\/span>/gi, '')
                                .replace(/\s*FINAL\s*/gi, '');
                $quote.html(newHtml);
            });
            
            // Add final style to selected quote
            const $finalQuote = $(`.quotations-made[data-id="${finalQuoteId}"]`);
            if ($finalQuote.length) {
                $finalQuote.css({
                    'color': '#28a545ff !important',
                    'font-weight': '800 !important'
                });
                
                const $faIcon = $finalQuote.find('.fa');
                if ($faIcon.length) {
                    $faIcon.css('color', '#28a545ff');
                    $faIcon.removeClass('fa-star').addClass('fa-file');
                }
                
                const html = $finalQuote.html();
                if (!html.includes('badge-success')) {
                    const newHtml = html.replace(
                        /(Quote\s*\d+)/,
                        `$1 <span class="badge badge-success" style="font-size: 10px; padding: 2px 5px; color: #28a545ff; margin-left: 5px; font-weight: 700 !important;">FINAL</span>`
                    );
                    $finalQuote.html(newHtml);
                }
            }
        }
        
        // Helper function to get enquiry ID
        function getEnquiryId() {
            return $('#enquiry_id').val() || 
                $('#enquiry_num').val() || 
                $('input[name="enquiry_id"]').val() ||
                $('.quotations-made').first().closest('[data-enquiry-id]').data('enquiry-id');
        }
        
        // Modal cleanup
        $('#finalQuoteModal').on('hidden.bs.modal', function() {
            selectedQuoteId = null;
            $('#btn_mark_final').prop('disabled', true);
            $('#quote_info').hide();
            $('#adult_room_breakdown').hide();
            $('#child_type').hide();
            $('#room_allocation_error').hide();
            $('#same_hotels_info').hide();
            
            if (originalDropdownHTML) {
                $('#quote_dropdown').html(originalDropdownHTML);
            }
        });
        
        // Accessibility fixes
        $(document).on('shown.bs.modal', '#finalQuoteModal', function() {
            setTimeout(function() {
                $('#quote_dropdown').focus();
            }, 100);
        });
        
        $(document).on('hidden.bs.modal', '#finalQuoteModal', function() {
            $('#btn_final_quote').focus();
        });
    });
</script>